#include <iostream>
#include <bits/stdc++.h>

using namespace std;

typedef pair<string, float> DataPacket;
typedef pair<string, bool> BoolPair;

// Functor for sorting DataPackets based on marks and roll numbers
class Sorter {
public:
    bool operator()(const DataPacket& packet1, const DataPacket& packet2) {
        // Sort primarily by marks
        if (packet1.second > packet2.second) return true;
        if (packet1.second < packet2.second) return false;

        // If marks are equal, sort by ASCII sum of roll number
        int asciiSum1 = accumulate(packet1.first.begin(), packet1.first.end(), 0);
        int asciiSum2 = accumulate(packet2.first.begin(), packet2.first.end(), 0);

        if (asciiSum1 < asciiSum2) return true;
        if (asciiSum2 < asciiSum1) return false;

        // If ASCII sums are also equal, sort lexicographically by roll number
        return packet1.first <= packet2.first;
    }
};

// Main class for managing student data and processing commands
class ExaminationSystem {
private:
    map<string, bool> studentMap; // Tracks student admission status
    vector<DataPacket> studentList; // Stores examination marks data

public:
    // Inserts new student data without sorting
    void NewInsert(const string& rollNumber, float marks) {
        DataPacket newEntry = {rollNumber, marks};
        studentList.push_back(newEntry);

        if (studentMap.find(rollNumber) == studentMap.end()) {
            studentMap[rollNumber] = true;
        }
    }

    // Inserts or updates student data and sorts the list
    void Insert(const string& rollNumber, float marks) {
        if (studentMap.find(rollNumber) == studentMap.end()) {
            // New entry
            DataPacket newEntry = {rollNumber, marks};
            studentList.push_back(newEntry);
            Sorter sorter;
            sort(studentList.begin(), studentList.end(), sorter);
            studentMap[rollNumber] = true;
        } else {
            if (!studentMap[rollNumber]) {
                cout << "ALREADY ADMITTED" << endl;
                return;
            }

            // Update existing entry
            auto it = find_if(studentList.begin(), studentList.end(),
                              [&rollNumber](const DataPacket& packet) { return packet.first == rollNumber; });
            if (it != studentList.end()) {
                it->second = (it->second + marks) / 2;
                Sorter sorter;
                sort(studentList.begin(), studentList.end(), sorter);
            }
        }
    }

    // Checks admission criteria and processes top students
    void IsAdmit(int percentageStudents, int percentageMarks) {
        float maxMarks = studentList[0].second;
        float threshold = maxMarks * percentageMarks / 100.0;
        int totalStudents = studentList.size();
        int passedStudents = count_if(studentList.begin(), studentList.end(),
                                       [&threshold](const DataPacket& packet) { return packet.second >= threshold; });

        if (passedStudents >= (percentageStudents * totalStudents) / 100 && totalStudents >= 10) {
            cout << "YES" << endl;
            int topCount = floor(0.10 * studentList.size());
            Print(0, topCount - 1);
            for (int i = 0; i < topCount; i++) {
                studentMap[studentList[i].first] = false;
            }
            studentList.erase(studentList.begin(), studentList.begin() + topCount);
        } else {
            cout << "NO" << endl;
        }
    }

    // Prints entries between specified indices
    void Print(int startIndex, int endIndex) {
        for (int i = startIndex; i <= endIndex; i++) {
            cout << fixed << setprecision(3) << studentList[i].first << " " << studentList[i].second << endl;
        }
    }

    // Prints the entire list
    void Print() {
        for (const auto& entry : studentList) {
            cout << fixed << setprecision(3) << entry.first << " " << entry.second << endl;
        }
    }
};

int main() {
    ExaminationSystem examSystem;

    int numberOfEntries;
    string rollNumber;
    float marks;
    scanf("%d\n", &numberOfEntries);

    // Input initial student data
    for (int i = 0; i < numberOfEntries; i++) {
        cin >> rollNumber >> marks;
        examSystem.NewInsert(rollNumber, marks);
    }

    int numberOfQueries;
    scanf("%d\n", &numberOfQueries);

    // Process commands
    for (int i = 0; i < numberOfQueries; i++) {
        string query;
        cin >> query;

        if (query == "INSERT") {
            cin >> rollNumber >> marks;
            examSystem.Insert(rollNumber, marks);
        } else if (query == "IS_ADMIT") {
            int percentageStudents, percentageMarks;
            cin >> percentageStudents >> percentageMarks;
            examSystem.IsAdmit(percentageStudents, percentageMarks);
        } else if (query == "PRINT") {
            string inputLine;
            getline(cin, inputLine);
            istringstream iss(inputLine);
            vector<int> indices;

            int index;
            while (iss >> index) {
                indices.push_back(index);
            }

            if (indices.empty()) {
                examSystem.Print();
            } else {
                examSystem.Print(indices[0] - 1, indices[1] - 1);
            }
        }
    }
    return 0;
}

