void initialize_dungeon(Dungeon *dungeon) {
    strcpy(dungeon->monsters[0].name, "Goblin");
    dungeon->monsters[0].health = 30;
    dungeon->monsters[0].attack = 5;

    strcpy(dungeon->monsters[1].name, "Skeleton");
    dungeon->monsters[1].health = 40;
    dungeon->monsters[1].attack = 7;

    strcpy(dungeon->monsters[2].name, "Orc");
    dungeon->monsters[2].health = 50;
    dungeon->monsters[2].attack = 10;

    strcpy(dungeon->monsters[3].name, "Troll");
    dungeon->monsters[3].health = 70;
    dungeon->monsters[3].attack = 12;

    strcpy(dungeon->monsters[4].name, "Dragon");
    dungeon->monsters[4].health = 100;
    dungeon->monsters[4].attack = 15;

    strcpy(dungeon->treasures[0].name, "Gold");
    dungeon->treasures[0].value = 100;

    strcpy(dungeon->treasures[1].name, "Silver");
    dungeon->treasures[1].value = 50;

    strcpy(dungeon->treasures[2].name, "Diamond");
    dungeon->treasures[2].value = 150;

    strcpy(dungeon->treasures[3].name, "Emerald");
    dungeon->treasures[3].value = 120;

    strcpy(dungeon->treasures[4].name, "Ruby");
    dungeon->treasures[4].value = 130;

    dungeon->monster_count = MAX_MONSTERS;
    dungeon->treasure_count = MAX_TREASURES;
}

void encounter_monster(Monster *monster) {
    printf("A wild %s appeared! Health: %d, Attack: %d\n", 
           monster->name, monster->health, monster->attack);
}

void encounter_treasure(Treasure *treasure) {
    printf("You found a treasure: %s worth %d gold!\n", treasure->name, treasure->value);
}

void battle(Monster *monster) {
    int player_health = 100;
    int player_attack = 10;
    printf("You engage the %s in battle!\n", monster->name);

    while (player_health > 0 && monster->health > 0) {
        monster->health -= player_attack;
        printf("You hit the %s! It has %d health left.\n", 
               monster->name, monster->health);
        if (monster->health <= 0) {
            printf("You have defeated the %s!\n", monster->name);
            break;
        }
        player_health -= monster->attack;
        printf("The %s attacked you! You have %d health left.\n",
               monster->name, player_health);
    }

    if (player_health <= 0) {
        printf("You have been defeated by the %s...\n", monster->name);
    }
}

void explore_dungeon() {
    Dungeon dungeon;
    initialize_dungeon(&dungeon);

    srand(time(NULL));
    int step;

    printf("Welcome brave adventurer! You are about to explore the dungeon!\n");

    for (step = 0; step < MAX_DUNGEON_SIZE; step++) {
        int random_encounter = rand() % 10;

        if (random_encounter < 5) {
            int monster_index = rand() % dungeon.monster_count;
            encounter_monster(&dungeon.monsters[monster_index]);
            battle(&dungeon.monsters[monster_index]);
        } else {
            int treasure_index = rand() % dungeon.treasure_count;
            encounter_treasure(&dungeon.treasures[treasure_index]);
        }

        printf("\nYou move deeper into the dungeon...\n\n");
    }

    printf("Your adventure in the dungeon has ended. Brave adventurer, you have encountered many challenges!\n");
}

int main() {
    explore_dungeon();
    return 0;
}

