public:
    string name;
    int age;
    int studentID;
    string major;

    // Displays the reading activity of the student
    void read(const Book& book) {
        cout << name << " is reading the book <<" << book.title << ">>" << endl;
    }

    // Creates a new book authored by the student
    Book write(const string& content, const string& title) {
        return Book(content, title, name);
    }

    // Greets another student
    void greet(const Student& other) {
        cout << "Hello " << other.name << ", my name is " << name << endl;
    }

    // Recommends a book to another student
    void recommend(const Student& other, const Book& book) {
        other.read(book);
    }
};

int main() {
    Student students[10];
    Book library[MAX_BOOKS];
    int currentBookIndex = 5;

    char title[10] = "Book of A";

    srand(static_cast<unsigned int>(time(nullptr)));

    // Initialize student names
    for (int i = 0; i < 10; i++) {
        students[i].name = 'A' + i;
