    // Populate the library with books
    library[0] = Book("IN 1977, AS TWELVE-YEAR-OLD THEO STRUGGLES WITH A SCIENCE CLASS PROJECT ON SPACE EXPLORATION, QUESTIONS EMERGE ABOUT WHY HIS FATHER NEVER RETURNED FROM VIETNAM AND WHY THEO'S MOTHER HAS BEEN KEEPING SECRETS FOR MANY YEARS.", "Greetings From Planet Earth", "Barbara Kerley");
