#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NUM_CARDS 52
#define MIN_RANK 1
#define MAX_RANK 13
#define MIN_SUIT 1
#define MAX_SUIT 4

typedef struct Card {
    int rank;
    int suit;
} Card;

void initDeck(Card *deck) {
    int i = 0;
    for (int suit = MIN_SUIT; suit <= MAX_SUIT; suit++) {
        for (int rank = MIN_RANK; rank <= MAX_RANK; rank++) {
            deck[i].rank = rank;
            deck[i].suit = suit;
            i++;
        }
    }
}

void shuffleDeck(Card *deck, int numCards) {
    srand(time(NULL));
    for (int i = 0; i < numCards; i++) {
        int j = rand() % numCards;
        Card temp = deck[i];
        deck[i] = deck[j];
        deck[j] = temp;
    }
}

int checkForThreeOfAKind(Card *hand, int numCards) {
    int ranks[MAX_RANK] = {0};
    for (int i = 0; i < numCards; i++) {
        ranks[hand[i].rank]++;
    }

    for (int i = MIN_RANK; i <= MAX_RANK; i++) {
        if (ranks[i] >= 3) {
            return 1;
        }
    }

    return 0;
}

void printHand(Card *hand, int numCards) {
    for (int i = 0; i < numCards; i++) {
        printf("%d of %d ", hand[i].rank, hand[i].suit);
    }
    printf("\n");
}

int main() {
    Card deck[NUM_CARDS];
    initDeck(deck);
    shuffleDeck(deck, NUM_CARDS);

    Card hand[5];
    for (int i = 0; i < 5; i++) {
        hand[i] = deck[i];
    }

    printHand(hand, 5);

    int threeOfAKind = checkForThreeOfAKind(hand, 5);

    if (threeOfAKind == 1) {
        printf("You have three of a kind!\n");
    } else {
        printf("Sorry, you don't have three of a kind.\n");
    }

    return 0;
}

