    char name[50];
} Genre;

typedef struct {
    Song songs[MAX_SONGS];
    int numSongs;
} Playlist;

void initPlaylist(Playlist *playlist) {
    playlist->numSongs = 0;
}

void addSongToPlaylist(Playlist *playlist, Song song) {
    if (playlist->numSongs >= MAX_SONGS) {
        printf("Playlist is full!\n");
        return;
    }
    playlist->songs[playlist->numSongs++] = song;
}

void printPlaylist(Playlist playlist) {
    printf("Playlist:\n");
    for (int i = 0; i < playlist.numSongs; i++) {
        printf("%s by %s on %s (%s)\n", playlist.songs[i].title, playlist.songs[i].artist, playlist.songs[i].album, playlist.songs[i].genre);
    }
}

