    addSongToPlaylist(&playlists[0], (Song) {"Stairway to Heaven", "Led Zeppelin", "Led Zeppelin IV", "Rock"});
    addSongToPlaylist(&playlists[0], (Song) {"Smells Like Teen Spirit", "Nirvana", "Nevermind", "Grunge"});

