        printf("%d from %d to %d\n", disks[i], current_pole, temp_pole);
        temp_pole = current_pole;
        current_pole = temp_pole - 1;
        if(temp_pole == 0) {
            current_pole = temp_pole;
        }
        printf("\n");
        printf("%d from %d to %d\n", disks[i], current_pole, temp_pole);
        temp_pole = current_pole;
