#define MAX_DEVICES 10

typedef struct {
    char* name;
    int state;
} device_t;

void set_device_state(device_t* devices, int device_id, int state) {
    devices[device_id].state = state;
}

int get_device_state(device_t* devices, int device_id) {
    return devices[device_id].state;
}

void print_devices(device_t* devices, int num_devices) {
    for (int i = 0; i < num_devices; i++) {
        printf("%s: %s\n", devices[i].name, devices[i].state ? "ON" : "OFF");
    }
}

int main() {
    device_t devices[MAX_DEVICES] = {
        {"Light", 0},
        {"TV", 0},
        {"Air Conditioner", 0},
        {"Door", 0},
        {"Window", 0},
        {"Motion Sensor", 0},
        {"Garage Door", 0},
        {"Speaker", 0},
        {"Heater", 0},
        {"Refrigerator", 0}
    };

    int num_devices = sizeof(devices) / sizeof(devices[0]);

    set_device_state(devices, 0, 1);
    set_device_state(devices, 1, 1);
    set_device_state(devices, 2, 1);

    print_devices(devices, num_devices);

    return 0;
}

