class HotelRoom {
public:
    // Retrieves the room number
    int GetRoomNumber();

    // Retrieves the maximum room capacity
    int GetRoomCapacity();

    // Retrieves the current occupancy status of the room
    int GetRoomStatus();

    // Retrieves the daily room rate
    double GetRoomRate();

    // Modifies the occupancy status based on capacity
    int UpdateOccupancyStatus(int capacity);

    // Adjusts the room rate based on the season
    void SetRoomRate(double rate);

    // Reserves the specified hotel room
    void ReserveRoom(HotelRoom& hotelRoom);

    // Modifies room details based on the season
    void UpdateRoomDetails(HotelRoom& hotelRoom, string season);

    // Displays the details of the room
    void DisplayRoomDetails();

    // Constructor to initialize room attributes
    HotelRoom(int roomNumber, int capacity, double roomRate);

private:
    int roomNumber;
    int roomCapacity;
    int occupancyStatus;
    double dailyRate;
};

int main() {
    // Initialize hotel rooms with specific attributes
    HotelRoom room1(349, 4, 150);
    HotelRoom room2(147, 2, 175);
    HotelRoom room3(10, 1, 150);

    // Display details of each room
    room1.DisplayRoomDetails();
    room2.DisplayRoomDetails();
    room3.DisplayRoomDetails();

    return 0;
}

void HotelRoom::DisplayRoomDetails() {
    cout << "Room Number: " << roomNumber << endl; // Display room number
    cout << "Capacity: " << roomCapacity << endl; // Display room capacity
    cout << "Rate: " << dailyRate << endl; // Display room rate
    cout << "Season: " << (occupancyStatus > 0 ? "Occupied" : "Available") << endl; // Display occupancy status
}

int HotelRoom::GetRoomNumber() {
    return roomNumber;
}

int HotelRoom::GetRoomCapacity() {
    return roomCapacity;
}

int HotelRoom::GetRoomStatus() {
    return occupancyStatus;
}

double HotelRoom::GetRoomRate() {
    return dailyRate;
}

int HotelRoom::UpdateOccupancyStatus(int capacity) {
    // Check if the requested capacity exceeds the room capacity
    if (capacity > roomCapacity) {
        return -1; // Indicate failure
    }
    occupancyStatus = capacity; // Update occupancy status
    return 1; // Indicate success
}

void HotelRoom::SetRoomRate(double rate) {
    dailyRate = rate; // Update the daily room rate
}

HotelRoom::HotelRoom(int roomNumber, int capacity, double roomRate) 
    : roomNumber(roomNumber), roomCapacity(capacity), dailyRate(roomRate), occupancyStatus(0) {
}

