#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define HOTEL_NAME "Cosmic Dreams"
#define MAX_GUESTS 100
#define ROOMS 50
#define RATES (100 * 3)

typedef struct {
    char name[50];
    char email[50];
    int checkin;
    int checkout;
    int room_no;
    int status;
} guest_t;

typedef struct {
    char name[50];
    int num_guests;
    int capacity;
    int rate;
} room_t;

typedef struct {
    char name[50];
    int num_rooms;
    int total_guests;
    int total_revenue;
} hotel_t;

hotel_t hotel;
room_t rooms[ROOMS];
guest_t guests[MAX_GUESTS];

void init_hotel() {
    int i, j;

    for (i = 0; i < ROOMS; i++) {
        rooms[i].num_guests = 0;
        rooms[i].capacity = 5;
        rooms[i].rate = RATES;
    }

    for (i = 0; i < MAX_GUESTS; i++) {
        guests[i].name[0] = '\0';
        guests[i].email[0] = '\0';
        guests[i].checkin = 0;
        guests[i].checkout = 0;
        guests[i].room_no = 0;
        guests[i].status = 0;
    }

    hotel.num_rooms = ROOMS;
    hotel.total_guests = 0;
    hotel.total_revenue = 0;
}

void handle_reservation(int room_no, int num_guests) {
    int i;

    for (i = 0; i < num_guests; i++) {
        if (guests[i].name[0] == '\0') {
            strcpy(guests[i].name, "Unknown Guest");
        }
        guests[i].room_no = room_no;
        guests[i].checkin = time(NULL);
        guests[i].status = 1;
        hotel.total_guests++;
    }

    rooms[room_no].num_guests += num_guests;
    hotel.total_revenue += rooms[room_no].rate * num_guests;
}

void check_out(int room_no) {
    int i;

    for (i = 0; i < rooms[room_no].num_guests; i++) {
        guests[i].checkout = time(NULL);
        guests[i].status = 0;
    }

    rooms[room_no].num_guests -= rooms[room_no].num_guests;
    hotel.total_guests -= rooms[room_no].num_guests;
}

void display_hotel_info() {
    int i;

    printf("Hotel Name: %s\n", HOTEL_NAME);
    printf("Total Guests: %d\n", hotel.total_guests);
    printf("Total Revenue: %d\n", hotel.total_revenue);

    for (i = 0; i < ROOMS; i++) {
        printf("Room %d: Capacity %d, Occupancy %d, Rate %d\n",
            i, rooms[i].capacity, rooms[i].num_guests, rooms[i].rate);
    }

    for (i = 0; i < MAX_GUESTS; i++) {
        if (guests[i].name[0] != '\0') {
            printf("Guest %d: Name %s, Email %s, Checkin %d, Checkout %d\n",
                i, guests[i].name, guests[i].email, guests[i].checkin, guests[i].checkout);
        }
    }
}

int main() {
    init_hotel();

    while (1) {
        int room_no, num_guests;

        printf("Welcome to the Cosmic Dreams Hotel!\n");
        printf("Please enter the room number and number of guests: ");
        scanf("%d%d", &room_no, &num_guests);

        handle_reservation(room_no, num_guests);

        display_hotel_info();
    }

    return 0;
}

