	            ac.modify();
	            int pos=(-1)*static_cast<int>(sizeof(acc));
	            x.seekp(pos,ios::cur);
	            x.write(reinterpret_cast<char *> (&ac), sizeof(acc));
	            cout<<"\n\n\t Record Updated";
	            found=true;
	          }
	    }
