#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LOG_ENTRY_LENGTH 1024
#define MAX_URL_LENGTH 256
#define MAX_STATUS_CODE_LENGTH 4
#define MAX_REQUESTS 10000

typedef struct {
    char url[MAX_URL_LENGTH];
    int count;
} UrlCount;

typedef struct {
    char statusCode[MAX_STATUS_CODE_LENGTH];
    int count;
} StatusCount;

// Function to read log entries from a file
int readLogFile(const char *filename, char logEntries[MAX_REQUESTS][LOG_ENTRY_LENGTH], int maxEntries) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Unable to open the log file");
        return -1;
    }

    int entryCount = 0;
    while (fgets(logEntries[entryCount], LOG_ENTRY_LENGTH, file) && entryCount < maxEntries) {
        entryCount++;
    }

    fclose(file);
    return entryCount;
}

// Function to analyze the log entries
void analyzeLogs(char logEntries[MAX_REQUESTS][LOG_ENTRY_LENGTH], int entryCount, UrlCount *urls, StatusCount *statuses) {
    int urlCount = 0;
    int statusCount = 0;

    for (int i = 0; i < entryCount; i++) {
        char *url_ptr = strtok(logEntries[i], " ");
        char *statusCode_ptr = strtok(NULL, " ");

        if (url_ptr && statusCode_ptr) {
            // Count url occurrences
            int found = 0;
            for (int j = 0; j < urlCount; j++) {
                if (strcmp(urls[j].url, url_ptr) == 0) {
                    urls[j].count++;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                strcpy(urls[urlCount].url, url_ptr);
                urls[urlCount].count = 1;
                urlCount++;
            }

            // Count status code occurrences
            found = 0;
            for (int j = 0; j < statusCount; j++) {
                if (strcmp(statuses[j].statusCode, statusCode_ptr) == 0) {
                    statuses[j].count++;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                strcpy(statuses[statusCount].statusCode, statusCode_ptr);
                statuses[statusCount].count = 1;
                statusCount++;
            }
        }
    }

    // Print the analysis results
    printf("\n--- Log Analysis Results ---\n");
    printf("Total Requests: %d\n\n", entryCount);
    printf("Most Accessed URLs:\n");
    for (int i = 0; i < urlCount; i++) {
        printf("URL: %s, Count: %d\n", urls[i].url, urls[i].count);
    }
    printf("\nHTTP Status Codes:\n");
    for (int i = 0; i < statusCount; i++) {
        printf("Status Code: %s, Count: %d\n", statuses[i].statusCode, statuses[i].count);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char logEntries[MAX_REQUESTS][LOG_ENTRY_LENGTH];
    UrlCount urls[MAX_REQUESTS];
    StatusCount statuses[MAX_REQUESTS];

    int entryCount = readLogFile(argv[1], logEntries, MAX_REQUESTS);
    if (entryCount < 0) {
        return EXIT_FAILURE;
    }

    analyzeLogs(logEntries, entryCount, urls, statuses);
    return EXIT_SUCCESS;
}

