// Function to write a new account to the file
void writeAccount() {
    Account account;
    ofstream outFile("account.dat", ios::binary | ios::app);
    account.createAccount();
    outFile.write(reinterpret_cast<char*>(&account), sizeof(Account));
    outFile.close();
}

// Function to display details of a specific account
void displayAccount(int accountNumber) {
    Account account;
    bool found = false;
    ifstream inFile("account.dat", ios::binary);

    if (!inFile) {
        cout << "File could not be opened! Press any key...";
        return;
    }

    cout << "BALANCE DETAILS" << endl;

    while (inFile.read(reinterpret_cast<char*>(&account), sizeof(Account))) {
        if (account.getAccountNumber() == accountNumber) {
            account.showAccount();
            found = true;
        }
    }
    inFile.close();

    if (!found) {
        cout << "Account number does not exist" << endl;
    }
}

// Function to modify a specific account record
void modifyAccount(int accountNumber) {
    bool found = false;
    Account account;
    fstream file("account.dat", ios::binary | ios::in | ios::out);

    if (!file) {
        cout << "File could not be opened! Press any key...";
        return;
    }

    while (!file.eof() && !found) {
        file.read(reinterpret_cast<char*>(&account), sizeof(Account));
        if (account.getAccountNumber() == accountNumber) {
            account.showAccount();
            cout << "Enter The New Details of account" << endl;
            account.modify();
            int position = (-1) * static_cast<int>(sizeof(Account));
            file.seekp(position, ios::cur);
            file.write(reinterpret_cast<char*>(&account), sizeof(Account));
            cout << "Record Updated" << endl;
            found = true;
        }
    }
    file.close();

    if (!found) {
        cout << "Record Not Found" << endl;
    }
}

// Function to delete a specific account record
void deleteAccount(int accountNumber) {
    Account account;
    ifstream inFile("account.dat", ios::binary);
    ofstream outFile("Temp.dat", ios::binary);

    if (!inFile) {
        cout << "File could not be opened! Press any key...";
        return;
    }

    while (inFile.read(reinterpret_cast<char*>(&account), sizeof(Account))) {
        if (account.getAccountNumber() != accountNumber) {
            outFile.write(reinterpret_cast<char*>(&account), sizeof(Account));
        }
    }
    inFile.close();
    outFile.close();

    remove("account.dat");
    rename("Temp.dat", "account.dat");
    cout << "Record Deleted.." << endl;
}

// Function to display all account details
void displayAllAccounts() {
    Account account;
    ifstream inFile("account.dat", ios::binary);

    if (!inFile) {
        cout << "File could not be opened! Press any key...";
        return;
    }

    cout << "ACCOUNT HOLDER LIST" << endl;
    cout << "====================================================" << endl;
    cout << "A/c no.      NAME           Type  Balance" << endl;
    cout << "====================================================" << endl;

    while (inFile.read(reinterpret_cast<char*>(&account), sizeof(Account))) {
        account.report();
    }
    inFile.close();
}

// Function to deposit or withdraw amounts for a specific account
void depositWithdraw(int accountNumber, int option) {
    int amount;
    bool found = false;
    Account account;
    fstream file("account.dat", ios::binary | ios::in | ios::out);

    if (!file) {
        cout << "File could not be opened! Press any key...";
        return;
    }

    while (!file.eof() && !found) {
        file.read(reinterpret_cast<char*>(&account), sizeof(Account));
        if (account.getAccountNumber() == accountNumber) {
            account.showAccount();
            if (option == 1) {
                cout << "TO DEPOSIT AMOUNT" << endl;
                cout << "Enter The amount to be deposited: ";
                cin >> amount;
                account.deposit(amount);
            } else if (option == 2) {
                cout << "TO WITHDRAW AMOUNT" << endl;
                cout << "Enter The amount to be withdrawn: ";
                cin >> amount;
                int newBalance = account.getBalance() - amount;

                if ((newBalance < 500 && account.getAccountType() == 'S') || (newBalance < 1000 && account.getAccountType() == 'C')) {
                    cout << "Insufficient balance" << endl;
                } else {
                    account.withdraw(amount);
                }
            }
            int position = (-1) * static_cast<int>(sizeof(Account));
            file.seekp(position, ios::cur);
            file.write(reinterpret_cast<char*>(&account), sizeof(Account));
            cout << "Record Updated" << endl;
            found = true;
        }
    }
    file.close();

    if (!found) {
        cout << "Record Not Found" << endl;
    }
}

