// Define the structure for a bank account
struct BankAccount {
    int accountNumber;
    char accountType[20];
    double balance;
};

// Function to create a new bank account
struct BankAccount* createAccount(int accountNumber, char* accountType, double balance) {
    struct BankAccount* newAccount = (struct BankAccount*) malloc(sizeof(struct BankAccount));
    if (newAccount == NULL) {
        printf("Failed to allocate memory\n");
        return NULL;
    }

    newAccount->accountNumber = accountNumber;
    strcpy(newAccount->accountType, accountType);
    newAccount->balance = balance;

    return newAccount;
}

// Function to deposit money into an account
void deposit(struct BankAccount* account, double amount) {
    if (amount <= 0) {
        printf("Invalid amount: must be greater than zero\n");
        return;
    }

    account->balance += amount;
}

// Function to withdraw money from an account
void withdraw(struct BankAccount* account, double amount) {
    if (amount <= 0) {
        printf("Invalid amount: must be greater than zero\n");
        return;
    }

    if (account->balance < amount) {
        printf("Insufficient funds\n");
        return;
    }

    account->balance -= amount;
}

// Function to display the details of a bank account
void display(struct BankAccount* account) {
    printf("Account Number: %d\n", account->accountNumber);
    printf("Account Type: %s\n", account->accountType);
    printf("Balance: $%.2f\n", account->balance);
}

int main() {
    // Create a new bank account
    struct BankAccount* account = createAccount(12345, "Checking", 1000.00);
    if (account == NULL) {
        return 1;
    }

    // Deposit some money into the account
    deposit(account, 500.00);

    // Withdraw some money from the account
    withdraw(account, 250.00);

    // Display the details of the account
    display(account);

    // Free the memory allocated for the account
    free(account);

    return 0;
}

#include"page.h"

/**
 * @brief The BufferManager is responsible for reading pages to the main memory.
 * Recall that large files are broken and stored as blocks in the hard disk. The
 * minimum amount of memory that can be read from the disk is a block whose size
 * is indicated by BLOCK_SIZE. within this system we simulate blocks by
 * splitting and storing the file as multiple files each of one BLOCK_SIZE,
 * although this isn't traditionally how it's done. You can alternatively just
 * random access to the point where a block begins within the same
 * file. In this system we assume that the the sizes of blocks and pages are the
 * same. 
 * 
 * <p>
 * The buffer can hold multiple pages quantified by BLOCK_COUNT. The
 * buffer manager follows the FIFO replacement policy i.e. the first block to be
 * read in is replaced by the new incoming block. This replacement policy should
 * be transparent to the executors i.e. the executor should not know if a block
 * was previously present in the buffer or was read in from the disk. 
 * </p>
 *
 */
class BufferManager{

    deque<Page> pages; 
    bool inPool(string pageName);
    Page getFromPool(string pageName);
    Page insertIntoPool(string tableName, int pageIndex);

    public:

    BufferManager();
    Page getPage(string tableName, int pageIndex);
    void writePage(string pageName, vector<vector<int>> rows);
    void deleteFile(string tableName, int pageIndex);
    void deleteFile(string fileName);
    void writePage(string tableName, int pageIndex, vector<vector<int>> rows, int rowCount);
};

#include <stdio.h>
#include <stdlib.h>

#define ROWS 5
#define COLS 5

int main() {
    int matrix[ROWS][COLS];

    // Initialize the matrix with random values from 1-20
    for(int i=0; i<ROWS; i++) {
        for(int j=0; j<COLS; j++) {
            matrix[i][j] = (rand() % 20) + 1;
        }
    }

    // Print the matrix before manipulation
    printf("Original Matrix:\n");
    for(int i=0; i<ROWS; i++) {
        for(int j=0; j<COLS; j++) {
            printf("%d\t", matrix[i][j]);
        }
        printf("\n");
    }

    // Find the maximum value in the matrix and its location
    int max = -1, max_row, max_col;
    for(int i=0; i<ROWS; i++) {
        for(int j=0; j<COLS; j++) {
            if(matrix[i][j] > max) {
                max = matrix[i][j];
                max_row = i;
                max_col = j;
            }
        }
    }
    printf("Maximum value in matrix: %d\n", max);
    printf("Location of maximum value: row %d, column %d\n", max_row, max_col);

    // Transpose the matrix
    int transpose[COLS][ROWS];
    for(int i=0; i<COLS; i++) {
        for(int j=0; j<ROWS; j++) {
            transpose[i][j] = matrix[j][i];
        }
    }

    // Print the transposed matrix
    printf("Transposed Matrix:\n");
    for(int i=0; i<COLS; i++) {
        for(int j=0; j<ROWS; j++) {
            printf("%d\t", transpose[i][j]);
        }
        printf("\n");
    }

    // Find the sum of each row in the transposed matrix
    int row_sums[COLS] = {0};
    for(int i=0; i<COLS; i++) {
        for(int j=0; j<ROWS; j++) {
            row_sums[i] += transpose[i][j];
        }
    }

    // Print the row sums
    printf("Row Sums:\n");
    for(int i=0; i<COLS; i++) {
        printf("Row %d: %d\n", i+1, row_sums[i]);
    }

    return 0;
}

