/* This program create class DoubMatrix that creates a dynamic matrix (array) and  */
/* calculates multiplication between matrices, vectors, and scalars. It overloads  */
/* <<, *(5 types) and = operators to multiply and prints multiplication results to */
/* the screen. A power function is also created to make multiplication easier. When*/
/* compiling, the main file includes DoubArray to ensure successful executions. If */
/* the program runs as expected, DoubMatrix type(incl.row/col vectors) new objects */
/* after multiplication and power operation are returned and printed to the screen.*/
/***********************************************************************************/

#ifndef DoubMatrix_h
#define DoubMatrix_h

#include "DoubArray.h"

#include <iostream>
#include <cassert>
#include <cmath>

class DoubMatrix
{
protected:
    double **m_A;
    int m_row;
    int m_col;

public:
    // Member Functions
    DoubMatrix(int row, int col);
    DoubMatrix(const DoubMatrix &org_matrix);
    ~DoubMatrix();

    void setValue(int row, int col, double value);
    double& getValue(int row, int col) const ;
    int getRow() const ;
    int getCol() const ;
    // = overload
    void operator= (const DoubMatrix &matrix_new);
    // Power: (Matrix)^exponent
    DoubMatrix Pow(int exponent);

    // Friend Functions
    // << overload
    friend std::ostream& operator<<(std::ostream& output, const DoubMatrix &matrix);

    // matrix, matrix
    friend DoubMatrix operator*(const DoubMatrix &matrix1, const DoubMatrix &matrix2);
    // matrix, vector = col vector = matrix(row, col=1)
    friend DoubMatrix operator*(const DoubMatrix &matrix, const DoubArray &array);
    // vector, matrix = row vector = matrix(row=1, col)
    friend DoubMatrix operator*(const DoubArray &array, const DoubMatrix &matrix);
    // scalar, matrix = matrix, scalar; hence 1 function is sufficient
    friend DoubMatrix operator*(int integer, const DoubMatrix &matrix);
};

#endif /* DoubMatrix_h */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char filename[50];
    char* data;
    int size;
    int ref_count;
} File;

File* open_file(const char* filename) {
    File* file = (File*)malloc(sizeof(File));
    if (file == NULL) {
        return NULL;
    }
    strncpy(file->filename, filename, sizeof(file->filename));
    file->data = NULL;
    file->size = 0;
    file->ref_count = 1;
    return file;
}

int close_file(File* file) {
    if (file == NULL) {
        return -1;
    }
    if (--file->ref_count == 0) {
        free(file->data);
        free(file);
        return 0;
    }
    return 0;
}

int write_file(File* file, const char* data, int size) {
    if (file == NULL || data == NULL) {
        return -1;
    }
    if (file->size + size > 1024 * 1024) {
        return -2;
    }
    if (file->data == NULL) {
        file->data = (char*)malloc(size);
        if (file->data == NULL) {
            return -3;
        }
    }
    strncpy(file->data + file->size, data, size);
    file->size += size;
    return 0;
}

int read_file(File* file, char* data, int size) {
    if (file == NULL || data == NULL) {
        return -1;
    }
    if (file->size < size) {
        return -2;
    }
    if (file->data == NULL) {
        return -3;
    }
    strncpy(data, file->data, size);
    return 0;
}

int main() {
    File* file1 = open_file("file1.txt");
    if (file1 == NULL) {
        printf("Error opening file1.txt\n");
        return 1;
    }
    write_file(file1, "Hello, world!", 13);
    close_file(file1);

    File* file2 = open_file("file2.txt");
    if (file2 == NULL) {
        printf("Error opening file2.txt\n");
        return 1;
    }
    read_file(file2, "data", 13);
    close_file(file2);

    return 0;
}

