				int bal=ac.retdeposit()-amt;

				if((bal<500 && ac.rettype()=='S') || (bal<1000 && ac.rettype()=='C'))

					cout<<"Insufficience balance";

				else

					ac.draw(amt);

			}

			int pos=(-1)*static_cast<int>(sizeof(ac));

			File.seekp(pos,ios::cur);

			File.write(reinterpret_cast<char *> (&ac), sizeof(account));

			cout<<"\n\n\t Record Updated";

			found=true;

	       }

         }

	File.close();

	if(found==false)

		cout<<"\n\n Record Not Found ";

}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MATRIX_ROWS 10
#define MATRIX_COLS 10

typedef struct {
    int rows;
    int cols;
    int **data;
} matrix_t;

void matrix_init(matrix_t *mat) {
    mat->rows = MATRIX_ROWS;
    mat->cols = MATRIX_COLS;
    mat->data = calloc(MATRIX_ROWS, sizeof(int *));
    for (int i = 0; i < MATRIX_ROWS; i++) {
        mat->data[i] = calloc(MATRIX_COLS, sizeof(int));
    }
}

void matrix_print(matrix_t *mat) {
    for (int i = 0; i < MATRIX_ROWS; i++) {
        for (int j = 0; j < MATRIX_COLS; j++) {
            printf("%d ", mat->data[i][j]);
        }
        printf("\n");
    }
}

void matrix_add(matrix_t *a, matrix_t *b, matrix_t *res) {
    for (int i = 0; i < MATRIX_ROWS; i++) {
        for (int j = 0; j < MATRIX_COLS; j++) {
            res->data[i][j] = a->data[i][j] + b->data[i][j];
        }
    }
}

void matrix_mult(matrix_t *a, matrix_t *b, matrix_t *res) {
    for (int i = 0; i < MATRIX_ROWS; i++) {
        for (int j = 0; j < MATRIX_COLS; j++) {
            int sum = 0;
            for (int k = 0; k < MATRIX_ROWS; k++) {
                sum += a->data[i][k] * b->data[k][j];
            }
            res->data[i][j] = sum;
        }
    }
}

int main() {
    srand(time(NULL));

    matrix_t *a, *b, *c;
    matrix_init(&a);
    matrix_init(&b);
    matrix_init(&c);

    for (int i = 0; i < MATRIX_ROWS; i++) {
        for (int j = 0; j < MATRIX_COLS; j++) {
            int val = rand() % 10;
            a->data[i][j] = val;
            b->data[i][j] = val;
        }
    }

    matrix_add(a, b, c);
    matrix_mult(a, b, c);

    matrix_print(c);

    return 0;
}

