char* generate_password(int length);
void shuffle_array(char *array, int n);
int char_in_string(char c, char *s);

int main()
{
    int length;

    printf("Enter the length of the password: ");
    scanf("%d", &length);

    char* password = generate_password(length);

    printf("Your secure password is: %s\n", password);

    free(password);
}

char* generate_password(int length)
{
    char* password = malloc(length + 1);

    // Define all the possible characters that can be in the password
    char lowercase[] = "abcdefghijklmnopqrstuvwxyz";
    char uppercase[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    char numbers[] = "0123456789";
    char symbols[] = "!@#$%^&*()_-+={}[]\\|;:'\",.<>/?";

    int lowercase_len = strlen(lowercase);
    int uppercase_len = strlen(uppercase);
    int numbers_len = strlen(numbers);
    int symbols_len = strlen(symbols);

    // Create an array to hold all the possible characters
    char all_chars[lowercase_len + uppercase_len + numbers_len + symbols_len];

    strncpy(all_chars, lowercase, lowercase_len);
    strncpy(all_chars + lowercase_len, uppercase, uppercase_len);
    strncpy(all_chars + lowercase_len + uppercase_len, numbers, numbers_len);
    strncpy(all_chars + lowercase_len + uppercase_len + numbers_len, symbols, symbols_len);

    // Shuffle the array of possible characters
    shuffle_array(all_chars, strlen(all_chars));

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < length; i++)
    {
        char c;

        // Randomly select a character from the array of possible characters
        do {
            c = all_chars[rand() % strlen(all_chars)];
        } while (char_in_string(c, password));

        password[i] = c;
    }

    password[length] = '\0';

    return password;
}

// Shuffle an array of characters
void shuffle_array(char *array, int n)
{
    if (n > 1) 
    {
        for (int i = 0; i < n - 1; i++) 
        {
            int j = i + rand() / (RAND_MAX / (n - i) + 1);
            char t = array[j];
            array[j] = array[i];
            array[i] = t;
        }
    }
}

// Check if a character is already in the given string
int char_in_string(char c, char *s)
{
    for (int i = 0; i < strlen(s); i++)
    {
        if (s[i] == c)
        {
            return 1;
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ENTRIES 100
#define NAME_LENGTH 50
#define MESSAGE_LENGTH 200

typedef struct {
    char name[NAME_LENGTH];
    char message[MESSAGE_LENGTH];
} LoveLetter;

LoveLetter database[MAX_ENTRIES];
int current_size = 0;

void addLetter(const char *name, const char *message) {
    if (current_size < MAX_ENTRIES) {
        strncpy(database[current_size].name, name, NAME_LENGTH);
        strncpy(database[current_size].message, message, MESSAGE_LENGTH);
        current_size++;
        printf("A new letter hath been added, sweet words from %s.\n", name);
    } else {
        printf("Alack! The database is full, cannot add more letters.\n");
    }
}

void displayLetters() {
    if (current_size == 0) {
        printf("No letters to display, thy hearts lie still.\n");
        return;
    }

    printf("\n--- Love Letters Database ---\n");
    for (int i = 0; i < current_size; i++) {
        printf("Letter %d:\n", i + 1);
        printf("From: %s\n", database[i].name);
        printf("Message: %s\n", database[i].message);
        printf("---------------------------\n");
    }
}

void searchLettersByName(const char *name) {
    int found = 0;
    printf("\nSearching letters from %s...\n", name);
    for (int i = 0; i < current_size; i++) {
        if (strcmp(database[i].name, name) == 0) {
            printf("Letter %d:\n", i + 1);
            printf("From: %s\n", database[i].name);
            printf("Message: %s\n", database[i].message);
            printf("---------------------------\n");
            found = 1;
        }
    }
    if (!found) {
        printf("No letters found from %s, a love lost in the fabric of time.\n", name);
    }
}

int main() {
    char name[NAME_LENGTH];
    char message[MESSAGE_LENGTH];
    int choice;

    printf("Welcome to the Love Letters Database, a tale of hearts entwined.\n");

    while (1) {
        printf("\nSelect thy action:\n");
        printf("1. Add a Love Letter\n");
        printf("2. Display All Love Letters\n");
        printf("3. Search Love Letters by Name\n");
        printf("4. Exit\n");
        printf("Enter thy choice: ");
        scanf("%d", &choice);
        getchar(); // clear newline after choice input

        switch (choice) {
            case 1:
                printf("Enter thy name (Romeo, Juliet, etc.): ");
                fgets(name, NAME_LENGTH, stdin);
                name[strcspn(name, "\n")] = 0; // remove newline char

                printf("Enter thy heart's message: ");
                fgets(message, MESSAGE_LENGTH, stdin);
                message[strcspn(message, "\n")] = 0; // remove newline char

                addLetter(name, message);
                break;
            case 2:
                displayLetters();
                break;
            case 3:
                printf("Whose letters dost thou seek? ");
                fgets(name, NAME_LENGTH, stdin);
                name[strcspn(name, "\n")] = 0; // remove newline char

                searchLettersByName(name);
                break;
            case 4:
                printf("Farewell! Thy heart's desires linger on...\n");
                return 0;
            default:
                printf("Soft! An invalid choice, choose wisely.\n");
        }
    }

    return 0;
}

