int globalCounter = 1;

class PointerHandler {
public:
    int displayCounter();
};

inline int PointerHandler::displayCounter() {
    // Increment and display the global counter for a fixed number of iterations
    for (int iteration = 0; iteration < 5; iteration++, globalCounter++) {
        cout << globalCounter << " " << endl;
    }

    // Reset the counter if it reaches a specific value
    if (globalCounter == 26) {
        globalCounter = 1;
    }

    printf("\n");
}

