    PointerHandler objects[3]; // Array of PointerHandler objects

    // Display counter values using the object array
    for (int index = 0; index < 5; index++) {
        objects[index].displayCounter();
    }

    PointerHandler* pointerToObjects = objects; // Assigning the address of the first object to a pointer

    printf("Pointer to object: \n");

    // Display counter values using the pointer to the object array
    for (int index = 0; index < 5; index++) {
        (pointerToObjects + index)->displayCounter();
    }

    return 0;
}

