#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WIDTH 20
#define HEIGHT 20

#define PACMAN_WIDTH 5
#define PACMAN_HEIGHT 5

#define FOOD_WIDTH 3
#define FOOD_HEIGHT 3

#define BORDER_WIDTH 2

typedef struct Pacman {
    int x;
    int y;
    int dx;
    int dy;
} Pacman;

typedef struct Food {
    int x;
    int y;
} Food;

Pacman pacman;
Food food;

void draw_border() {
    for (int x = 0; x < WIDTH; x++) {
        for (int y = 0; y < HEIGHT; y++) {
            if (x == 0 || x == WIDTH - 1 || y == 0 || y == HEIGHT - 1) {
                printf("#");
            } else {
                printf(".");
            }
        }
        printf("\n");
    }
}

void draw_pacman() {
    for (int x = pacman.x - PACMAN_WIDTH / 2; x < pacman.x + PACMAN_WIDTH / 2; x++) {
        for (int y = pacman.y - PACMAN_HEIGHT / 2; y < pacman.y + PACMAN_HEIGHT / 2; y++) {
            printf("o");
        }
    }
}

void draw_food() {
    printf("F");
}

void move_pacman() {
    pacman.x += pacman.dx;
    pacman.y += pacman.dy;

    if (pacman.x >= WIDTH - PACMAN_WIDTH / 2) {
        pacman.dx = -1;
    } else if (pacman.x <= PACMAN_WIDTH / 2) {
        pacman.dx = 1;
    }

    if (pacman.y >= HEIGHT - PACMAN_HEIGHT / 2) {
        pacman.dy = -1;
    } else if (pacman.y <= PACMAN_HEIGHT / 2) {
        pacman.dy = 1;
    }
}

int main() {
    srand(time(NULL));

    pacman.x = WIDTH / 2;
    pacman.y = HEIGHT / 2;
    pacman.dx = 1;
    pacman.dy = 1;

    food.x = rand() % WIDTH;
    food.y = rand() % HEIGHT;

    draw_border();
    draw_pacman();
    draw_food();

    move_pacman();

    draw_border();
    draw_pacman();
    draw_food();

    return 0;
}

