#include "../../core/include/fxcrt/fx_basic.h"
#include "agg_curves.h"
#include "agg_math.h"
namespace agg
{
const FX_FLOAT curve_collinearity_epsilon              = 1e-30f;
enum curve_recursion_limit_e { curve_recursion_limit = 16 };
void curve4_div::init(FX_FLOAT x1, FX_FLOAT y1,
                      FX_FLOAT x2, FX_FLOAT y2,
                      FX_FLOAT x3, FX_FLOAT y3,
                      FX_FLOAT x4, FX_FLOAT y4)
{
    m_points.remove_all();
    m_distance_tolerance_square = 1.0f / 4;
    m_distance_tolerance_manhattan = 1.0f * 4;
    bezier(x1, y1, x2, y2, x3, y3, x4, y4);
    m_count = 0;
}
void curve4_div::recursive_bezier(FX_FLOAT x1, FX_FLOAT y1,
                                  FX_FLOAT x2, FX_FLOAT y2,
                                  FX_FLOAT x3, FX_FLOAT y3,
                                  FX_FLOAT x4, FX_FLOAT y4,
                                  unsigned level)
{
    if(level > curve_recursion_limit) {
        return;
    }
    FX_FLOAT x12   = (x1 + x2) / 2;
    FX_FLOAT y12   = (y1 + y2) / 2;
    FX_FLOAT x23   = (x2 + x3) / 2;
    FX_FLOAT y23   = (y2 + y3) / 2;
    FX_FLOAT x34   = (x3 + x4) / 2;
    FX_FLOAT y34   = (y3 + y4) / 2;
    FX_FLOAT x123  = (x12 + x23) / 2;
    FX_FLOAT y123  = (y12 + y23) / 2;
    FX_FLOAT x234  = (x23 + x34) / 2;
    FX_FLOAT y234  = (y23 + y34) / 2;
    FX_FLOAT x1234 = (x123 + x234) / 2;
    FX_FLOAT y1234 = (y123 + y234) / 2;
    FX_FLOAT dx = x4 - x1;
    FX_FLOAT dy = y4 - y1;
    FX_FLOAT d2 = FXSYS_fabs(FXSYS_Mul(x2 - x4, dy) - FXSYS_Mul(y2 - y4, dx));
    FX_FLOAT d3 = FXSYS_fabs(FXSYS_Mul(x3 - x4, dy) - FXSYS_Mul(y3 - y4, dx));
    switch((int(d2 > curve_collinearity_epsilon) << 1) +
            int(d3 > curve_collinearity_epsilon)) {
        case 0:
            if(FXSYS_fabs(x1 + x3 - x2 - x2) +
                    FXSYS_fabs(y1 + y3 - y2 - y2) +
                    FXSYS_fabs(x2 + x4 - x3 - x3) +
                    FXSYS_fabs(y2 + y4 - y3 - y3) <= m_distance_tolerance_manhattan) {
                m_points.add(point_type(x1234, y1234, path_flags_jr));
                return;
            }
            break;
        case 1:
            if(FXSYS_Mul(d3, d3) <= FXSYS_Mul(m_distance_tolerance_square,
                                              FXSYS_Mul(dx, dx) + FXSYS_Mul(dy, dy))) {
                m_points.add(point_type(x23, y23, path_flags_jr));
                return;
            }
            break;
        case 2:
            if(FXSYS_Mul(d2, d2) <= FXSYS_Mul(m_distance_tolerance_square,
                                              FXSYS_Mul(dx, dx) + FXSYS_Mul(dy, dy))) {
                m_points.add(point_type(x23, y23, path_flags_jr));
                return;
            }
            break;
        case 3:
            if(FXSYS_Mul(d2 + d3, d2 + d3) <= FXSYS_Mul(m_distance_tolerance_square,
                    FXSYS_Mul(dx, dx) + FXSYS_Mul(dy, dy))) {
                m_points.add(point_type(x23, y23, path_flags_jr));
                return;
            }
            break;
    }
    recursive_bezier(x1, y1, x12, y12, x123, y123, x1234, y1234, level + 1);
    recursive_bezier(x1234, y1234, x234, y234, x34, y34, x4, y4, level + 1);
}
void curve4_div::bezier(FX_FLOAT x1, FX_FLOAT y1,
                        FX_FLOAT x2, FX_FLOAT y2,
                        FX_FLOAT x3, FX_FLOAT y3,
                        FX_FLOAT x4, FX_FLOAT y4)
{
    m_points.add(point_type(x1, y1));
    recursive_bezier(x1, y1, x2, y2, x3, y3, x4, y4, 0);
    m_points.add(point_type(x4, y4));
}
}

#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

struct Graph {
    int num_vertices;
    int** adjacency_matrix;
};

struct Graph* create_graph(int num_vertices) {
    struct Graph* graph = (struct Graph*)malloc(sizeof(struct Graph));
    graph->num_vertices = num_vertices;
    graph->adjacency_matrix = (int**)malloc(num_vertices * sizeof(int*));
    for (int i = 0; i < num_vertices; i++) {
        graph->adjacency_matrix[i] = (int*)malloc(num_vertices * sizeof(int));
    }
    for (int i = 0; i < num_vertices; i++) {
        for (int j = 0; j < num_vertices; j++) {
            graph->adjacency_matrix[i][j] = 0;
        }
    }
    return graph;
}

void free_graph(struct Graph* graph) {
    for (int i = 0; i < graph->num_vertices; i++) {
        free(graph->adjacency_matrix[i]);
    }
    free(graph->adjacency_matrix);
    free(graph);
}

bool is_safe(struct Graph* graph, int vertex, int color, int* colors) {
    for (int i = 0; i < graph->num_vertices; i++) {
        if (graph->adjacency_matrix[vertex][i] == 1 && colors[i] == color) {
            return false;
        }
    }
    return true;
}

bool graph_coloring(struct Graph* graph, int* colors, int vertex) {
    if (vertex == graph->num_vertices) {
        return true;
    }
    for (int color = 1; color <= graph->num_vertices; color++) {
        if (is_safe(graph, vertex, color, colors)) {
            colors[vertex] = color;
            if (graph_coloring(graph, colors, vertex + 1)) {
                return true;
            }
            colors[vertex] = 0;
        }
    }
    return false;
}

int main() {
    int num_vertices;
    printf("Enter the number of vertices: ");
    scanf("%d", &num_vertices);
    struct Graph* graph = create_graph(num_vertices);
    for (int i = 0; i < num_vertices; i++) {
        for (int j = 0; j < num_vertices; j++) {
            int edge;
            printf("Enter 1 if there is an edge between %d and %d, otherwise enter 0: ", i + 1, j + 1);
            scanf("%d", &edge);
            graph->adjacency_matrix[i][j] = edge;
        }
    }
    int* colors = (int*)malloc(num_vertices * sizeof(int));
    for (int i = 0; i < num_vertices; i++) {
        colors[i] = 0;
    }
    if (graph_coloring(graph, colors, 0)) {
        printf("The graph can be colored using %d colors:\n", graph->num_vertices);
        for (int i = 0; i < num_vertices; i++) {
            printf("Vertex %d: Color %d\n", i + 1, colors[i]);
        }
    } else {
        printf("The graph cannot be colored using %d colors.\n", graph->num_vertices);
    }
    free_graph(graph);
    free(colors);
    return 0;
}

