void CAppParamParser::Parse(const char* const* argv, int nArgs)
{
  if (nArgs > 1)
  {
    for (int i = 1; i < nArgs; i++)
    {
      ParseArg(argv[i]);
      if (stricmp(argv[i], "-d") == 0)
      {
        if (i + 1 < nArgs)
