namespace fs {

// Lớp quản lý chính sách thay thế bộ nhớ đệm theo phương pháp FIFO (First-In-First-Out)
class FIFO : public CacheReplacementPolicy {
 private:
  FIFO() = default; // Constructor riêng để ngăn chặn việc tạo đối tượng mới
  std::queue<std::string> fifoQueue_; // Hàng đợi lưu trữ các khóa của tệp trong bộ nhớ đệm

 public:
  FIFO(const FIFO&) = delete; // Ngăn chặn sao chép đối tượng
  FIFO& operator=(const FIFO&) = delete; // Ngăn chặn gán đối tượng

  // Thay thế tệp trong bộ nhớ đệm theo chính sách FIFO
  void replace(std::unordered_map<std::string, std::unique_ptr<fs::File>>& cache,
               std::unique_ptr<fs::File>& fileToReplace);

  // Chèn tệp vào bộ nhớ đệm và quản lý hàng đợi FIFO
  void insert(std::unordered_map<std::string, std::unique_ptr<fs::File>>& cache,
              std::unique_ptr<fs::File>& newFile);

  // Phương thức để lấy instance duy nhất của lớp FIFO
  static FIFO& getInstance() {
    static FIFO instance_; // Đối tượng duy nhất được tạo ra
    return instance_;
  }
};

}  // namespace fs

