using namespace std;

class Human {
public:
    static int totalCount; // Static variable to track the total number of Human instances
    int instanceCount = 0; // Instance-specific count

    // Constructor increments the static count and instance count
    Human() {
        totalCount++;
        instanceCount++;
        cout << "Number of static humans: " << totalCount << endl;
    }

    // Destructor decrements the static count and reports remaining instances
    ~Human() {
        cout << endl;
        cout << "There are now " << totalCount << " humans remaining" << endl;
        totalCount--;
    }

    // Static method to display the total number of Human instances
    static void displayTotalHumans() {
        cout << "There are " << totalCount << " people" << endl;
    }
};

// Definition of the static variable outside the class
int Human::totalCount = 0;

int main() {
    // Creating multiple Human objects, sharing the static variable across instances
    Human anish;
    Human mrinal;
    Human lucky;
    Human vaibhav;

    // Display the total number of Human instances created
    Human::displayTotalHumans(); 
    cout << Human::totalCount; 

    return 0;    
}

