    // Print the conspiracy.
    printf("%s", conspiracy);

    // Free the memory.
    for (int i = 0; i < 10; i++)
    {
        free(suspects[i]);
    }
    free(suspects);

    for (int i = 0; i < 5; i++)
    {
        free(motives[i]);
    }
    free(motives);

    for (int i = 0; i < 3; i++)
    {
