int main()
{
    sf::RenderWindow window(sf::VideoMode(800, 600), "SFML Shader", sf::Style::Titlebar | sf::Style::Close);
    window.setVerticalSyncEnabled(true);

    sf::Font font;
    if (!font.loadFromFile("resources/sansation.ttf"))
        return EXIT_FAILURE;
    Effect::setFont(font);

    std::vector<Effect*> effects = { new Pixelate, new WaveBlur, new StormBlink, new Edge, new Geometry };
    std::size_t currentEffectIndex = 0;

    for (auto& effect : effects)
        effect->load();

    sf::Texture textBackgroundTexture;
    if (!textBackgroundTexture.loadFromFile("resources/text-background.png"))
        return EXIT_FAILURE;
    sf::Sprite textBackground(textBackgroundTexture);
    textBackground.setPosition(0, 520);
    textBackground.setColor(sf::Color(255, 255, 255, 200));

    sf::Text description("Current effect: " + effects[currentEffectIndex]->getName(), font, 20);
    description.setPosition(10, 530);
    description.setFillColor(sf::Color(80, 80, 80));

    sf::Text instructions("Press left and right arrows to change the current shader", font, 20);
    instructions.setPosition(280, 555);
    instructions.setFillColor(sf::Color(80, 80, 80));

    sf::Clock clock;
    while (window.isOpen())
    {
        sf::Event event;
        while (window.pollEvent(event))
        {
            if (event.type == sf::Event::Closed)
                window.close();

            if (event.type == sf::Event::KeyPressed)
            {
                switch (event.key.code)
                {
                    case sf::Keyboard::Escape:
                        window.close();
                        break;

                    case sf::Keyboard::Left:
                        currentEffectIndex = (currentEffectIndex == 0) ? effects.size() - 1 : currentEffectIndex - 1;
                        description.setString("Current effect: " + effects[currentEffectIndex]->getName());
                        break;

                    case sf::Keyboard::Right:
                        currentEffectIndex = (currentEffectIndex == effects.size() - 1) ? 0 : currentEffectIndex + 1;
                        description.setString("Current effect: " + effects[currentEffectIndex]->getName());
                        break;

                    default:
                        break;
                }
            }
        }

        float x = static_cast<float>(sf::Mouse::getPosition(window).x) / window.getSize().x;
        float y = static_cast<float>(sf::Mouse::getPosition(window).y) / window.getSize().y;
        effects[currentEffectIndex]->update(clock.getElapsedTime().asSeconds(), x, y);

        window.clear(sf::Color(255, 128, 0));
        window.draw(*effects[currentEffectIndex]);
        window.draw(textBackground);
        window.draw(instructions);
        window.draw(description);
        window.display();
    }

    for (auto& effect : effects)
        delete effect;

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/statvfs.h>
#include <sys/stat.h>

#define MAX_DEPTH 1000
#define MAX_PATH 4096

typedef struct {
    char path[MAX_PATH];
    unsigned long long size;
} file_t;

static void add_file(file_t *files, int num_files, const char *path, unsigned long long size) {
    if (num_files >= MAX_DEPTH) {
        printf("Error: Maximum depth exceeded.\n");
        return;
    }

    strncpy(files[num_files].path, path, MAX_PATH - 1);
    files[num_files].size = size;
    num_files++;
}

static void print_files(file_t *files, int num_files) {
    for (int i = 0; i < num_files; i++) {
        printf("%-40s %10llu\n", files[i].path, files[i].size);
    }
}

static unsigned long long get_directory_size(const char *path) {
    unsigned long long size = 0;
    DIR *dir = opendir(path);

    if (dir == NULL) {
        return size;
    }

    struct dirent *ent;
    while ((ent = readdir(dir))!= NULL) {
        char full_path[MAX_PATH];
        snprintf(full_path, MAX_PATH, "%s/%s", path, ent->d_name);

        struct stat stat_buf;
        if (stat(full_path, &stat_buf) == 0) {
            if (S_ISDIR(stat_buf.st_mode)) {
                size += get_directory_size(full_path);
            } else {
                size += stat_buf.st_size;
            }
        }
    }

    closedir(dir);
    return size;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s [directory]\n", argv[0]);
        return 1;
    }

    char path[MAX_PATH];
    strncpy(path, argv[1], MAX_PATH - 1);

    unsigned long long total_size = get_directory_size(path);

    file_t files[MAX_DEPTH];
    int num_files = 0;

    add_file(files, num_files, path, total_size);

    print_files(files, num_files);

    return 0;
}

