// Define the number of players
#define NUM_PLAYERS 2

// Define the memory game structure
typedef struct MemoryGame
{
    int *cards;
    int size;
    int currentCard;
} MemoryGame;

// Function to initialize a memory game
MemoryGame *initializeMemoryGame(int size)
{
    MemoryGame *game = malloc(sizeof(MemoryGame));
    game->cards = malloc(size * sizeof(int));
    game->size = size;
    game->currentCard = 0;

    return game;
}

// Function to play a round of the memory game
void playRound(MemoryGame *game)
{
    // Get the card to be guessed
    int targetCard = game->cards[game->currentCard];

    // Show the card to the player
    printf("The card is: %d\n", targetCard);

    // Get the player's guess
    int guessCard;
    printf("Enter your guess: ");
    scanf("%d", &guessCard);

    // Check if the guess is correct
    if (guessCard == targetCard)
    {
        // Increment the current card
        game->currentCard++;

        // If the current card is the end of the game, end the game
        if (game->currentCard == game->size - 1)
        {
            printf("Congratulations! You won the game!\n");
            free(game->cards);
            free(game);
        }
        else
        {
            // Play the next round
            playRound(game);
        }
    }
    else
    {
        // Give the player feedback
        printf("Sorry, your guess is incorrect.\n");
    }
}

int main()
{
    // Initialize the memory game
    MemoryGame *game = initializeMemoryGame(5);

    // Play the game
    playRound(game);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <sys/socket.h>
#include <errno.h>
#include <pthread.h>

#define MAX_BUFFER 65536
#define PORT_TO_MONITOR 8080
#define FIREWALL_LOG "firewall_log.txt"

typedef struct {
    struct sockaddr_in addr;
    char payload[MAX_BUFFER];
    int len;
} packet_info;

void log_packet(const packet_info *packet) {
    FILE *log_file = fopen(FIREWALL_LOG, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "Source IP: %s\n", inet_ntoa(packet->addr.sin_addr));
    fprintf(log_file, "Packet Length: %d\n", packet->len);
    fprintf(log_file, "Payload: %s\n\n", packet->payload);
    fclose(log_file);
}

void *packet_sniffer(void *arg) {
    int sock_raw = *(int *)arg;
    struct sockaddr_in addr;
    socklen_t addr_len = sizeof(addr);
    packet_info p_info;

    while (1) {
        p_info.len = recvfrom(sock_raw, p_info.payload, MAX_BUFFER, 0, (struct sockaddr *)&addr, &addr_len);
        if (p_info.len < 0) {
            perror("Failed to receive packet");
            continue;
        }

        p_info.addr = addr;
        log_packet(&p_info);

        if (ntohs(addr.sin_port) == PORT_TO_MONITOR) {
            printf("Blocked packet from IP: %s on port %d\n", inet_ntoa(addr.sin_addr), PORT_TO_MONITOR);
        }
    }

    return NULL;
}

int create_raw_socket() {
    int sock_raw = socket(AF_INET, SOCK_RAW, IPPROTO_TCP);
    if (sock_raw < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    int option = 1;
    if (setsockopt(sock_raw, IPPROTO_IP, IP_HDRINCL, &option, sizeof(option)) < 0) {
        perror("Failed to set socket options");
        close(sock_raw);
        exit(EXIT_FAILURE);
    }

    return sock_raw;
}

void initialize_firewall() {
    printf("Initializing Firewall...\n");
    int sock_raw = create_raw_socket();

    pthread_t sniffer_thread;
    if (pthread_create(&sniffer_thread, NULL, packet_sniffer, (void *)&sock_raw) != 0) {
        perror("Failed to create sniffer thread");
        close(sock_raw);
        exit(EXIT_FAILURE);
    }

    pthread_join(sniffer_thread, NULL);
}

int main() {
    initialize_firewall();

    return 0;
}

