// C Spam Detection System
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

// Define the spam words
const char* spam_words[] = { "buy", "sale", "discount", "offer", "promotion" };

// Function to check if a word is a spam word
bool is_spam_word(const char* word) {
    for (int i = 0; i < sizeof(spam_words) / sizeof(spam_words[0]); i++) {
        if (strcmp(word, spam_words[i]) == 0) {
            return true;
        }
    }
    return false;
}

// Function to check if a message is spam
bool is_spam(const char* message) {
    // Convert the message to lowercase
    char* lowercase_message = strdup(message);
    for (int i = 0; i < strlen(lowercase_message); i++) {
        lowercase_message[i] = tolower(lowercase_message[i]);
    }

    // Check if any of the words in the message are spam words
    char* word = strtok(lowercase_message, " ");
    while (word != NULL) {
        if (is_spam_word(word)) {
            return true;
        }
        word = strtok(NULL, " ");
    }

    // If no spam words are found, the message is not spam
    return false;
}

// Example usage
int main() {
    char* message = "Hello, how are you?";
    if (is_spam(message)) {
        printf("Spam detected\n");
    } else {
        printf("Not spam\n");
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PROCESSES 100
#define MAX_PROCESS_NAME_LENGTH 50

typedef struct {
    char name[MAX_PROCESS_NAME_LENGTH];
    int pid;
    int memoryUsage;
} Process;

int getProcessMemoryUsage(int pid) {
    char filename[20];
    sprintf(filename, "/proc/%d/statm", pid);

    FILE *file = fopen(filename, "r");
    int memoryUsage = 0;

    if (file!= NULL) {
        fscanf(file, "%d", &memoryUsage);
        fclose(file);
    }

    return memoryUsage;
}

void updateProcessMemoryUsage(Process *process) {
    process->memoryUsage = getProcessMemoryUsage(process->pid);
}

int compareProcesses(const void *a, const void *b) {
    Process *processA = (Process *)a;
    Process *processB = (Process *)b;

    return processB->memoryUsage - processA->memoryUsage;
}

int main() {
    Process processes[MAX_PROCESSES];
    int numProcesses = 0;

    char command[100];
    sprintf(command, "ps -eo pid,comm --sort=-%mem | head -n %d", MAX_PROCESSES, MAX_PROCESSES);

    FILE *file = popen(command, "r");

    if (file!= NULL) {
        char line[100];
        while (fgets(line, sizeof(line), file)!= NULL) {
            int pid;
            char processName[MAX_PROCESS_NAME_LENGTH];

            sscanf(line, "%d %s", &pid, processName);

            if (numProcesses < MAX_PROCESSES) {
                strncpy(processes[numProcesses].name, processName, MAX_PROCESS_NAME_LENGTH);
                processes[numProcesses].pid = pid;
                processes[numProcesses].memoryUsage = 0;
                numProcesses++;
            }
        }

        pclose(file);

        qsort(processes, numProcesses, sizeof(Process), compareProcesses);

        printf("Process\tPID\tMemory Usage\n");

        for (int i = 0; i < numProcesses; i++) {
            updateProcessMemoryUsage(&processes[i]);
            printf("%s\t%d\t%d kB\n", processes[i].name, processes[i].pid, processes[i].memoryUsage);
        }
    }

    return 0;
}

