namespace fs {

// Class representing a no-op cache replacement policy.
class NullReplacement : public CacheReplacementPolicy {
 private:
  NullReplacement() = default; // Private constructor for singleton pattern.

 public:
  // Delete copy constructor and assignment operator to prevent copying.
  NullReplacement(const NullReplacement&) = delete;
  NullReplacement& operator=(const NullReplacement&) = delete;

  // No operation for replacing files in the cache.
  void replace(std::unordered_map<std::string, std::unique_ptr<fs::File>>& cache,
               std::unique_ptr<fs::File>& file) override {}

  // No operation for inserting files into the cache.
  void insert(std::unordered_map<std::string, std::unique_ptr<fs::File>>& cache,
              std::unique_ptr<fs::File>& file) override {}

  // Provides access to the singleton instance of NullReplacement.
  static NullReplacement& getInstance() {
    static NullReplacement instance_; // Guaranteed to be destroyed.
    return instance_;
  }
};

}  // namespace fs

#endif  // NULL_REPLACEMENT_POLICY_H

