            strcpy(resume.email, token);
        } else if (line_count == 3) {
            strcpy(resume.skills, token);
        } else if (line_count == 4) {
            strcpy(resume.education, token);
        } else if (line_count == 5) {
            strcpy(resume.experience, token);
