            {

                dire[1]=1;

                dire[0]=0;

            }

        }

        else if (GetAsyncKeyState(VK_LEFT))

        {

            if (dire[0]==0)

            {

                dire[1]=0;

                dire[0]=-1;

            }

        }

        else if (GetAsyncKeyState(VK_RIGHT))

        {

            if (dire[0]==0)

            {

                dire[1]=0;

                dire[0]=1;

            }

        }

        if(snakeMove(snake,dire))

        {

          system("cls");

          cout<<"Game Over"<<endl;

          system("pause");

          return 0;

        }

        Sleep(GameSpeed);

    }

}

