// Function to issue a book to a student
void issueBook() {
    char studentNumber[6], bookNumber[6];
    bool studentFound = false, bookFound = false;
    cout << "\nBOOK ISSUE...\n";
    cout << "\nEnter The Student's Admission Number: ";
    cin >> studentNumber;
    fileStream.open("student.dat", ios::in | ios::out);
    fstream bookFileStream;
    bookFileStream.open("book.dat", ios::in | ios::out);
    while (fileStream.read(reinterpret_cast<char*>(&student), sizeof(Student)) && !studentFound) {
        if (strcasecmp(student.getAdmissionNumber(), studentNumber) == 0) {
            studentFound = true;
            if (student.getToken() == 0) {
                cout << "\nEnter the Book Number: ";
                cin >> bookNumber;
                while (bookFileStream.read(reinterpret_cast<char*>(&book), sizeof(Book)) && !bookFound) {
                    if (strcasecmp(book.getBookNumber(), bookNumber) == 0) {
                        book.showBook();
                        bookFound = true;
                        student.issueBook();
                        student.setIssuedBookNumber(book.getBookNumber());
                        long pos = -1 * sizeof(student);
                        fileStream.seekp(pos, ios::cur);
                        fileStream.write(reinterpret_cast<char*>(&student), sizeof(Student));
                        cout << "\nBook issued successfully. Please note: Write the current date on the back of the book and submit within 15 days. Fine Rs. 1 for each day after the 15-day period.";
                    }
                }
                if (!bookFound) {
                    cout << "Book number does not exist.";
                }
            } else {
                cout << "You have not returned the last book.";
            }
        }
    }
    if (!studentFound) {
        cout << "Student record does not exist.";
    }
    cin.get();
    fileStream.close();
    bookFileStream.close();
}

// Function to deposit a book from a student
void depositBook() {
    char studentNumber[6], bookNumber[6];
    bool studentFound = false, bookFound = false;
    int days, fine;
    cout << "\nBOOK DEPOSIT...\n";
    cout << "\nEnter The Student's Admission Number: ";
    cin >> studentNumber;
    fileStream.open("student.dat", ios::in | ios::out);
    fstream bookFileStream;
    bookFileStream.open("book.dat", ios::in | ios::out);
    while (fileStream.read(reinterpret_cast<char*>(&student), sizeof(Student)) && !studentFound) {
        if (strcasecmp(student.getAdmissionNumber(), studentNumber) == 0) {
            studentFound = true;
            if (student.getToken() == 1) {
                while (bookFileStream.read(reinterpret_cast<char*>(&book), sizeof(Book)) && !bookFound) {
                    if (strcasecmp(book.getBookNumber(), student.getIssuedBookNumber()) == 0) {
                        book.showBook();
                        bookFound = true;
                        cout << "\nEnter the number of days the book was held: ";
                        cin >> days;
                        if (days > 15) {
                            fine = (days - 15) * 1;
                            cout << "\nFine to be deposited: Rs. " << fine;
                        }
                        student.returnBook();
                        long pos = -1 * sizeof(student);
                        fileStream.seekp(pos, ios::cur);
                        fileStream.write(reinterpret_cast<char*>(&student), sizeof(Student));
                        cout << "\nBook deposited successfully.";
                    }
                }
                if (!bookFound) {
                    cout << "Book number does not exist.";
                }
            } else {
                cout << "No book is issued. Please check!";
            }
        }
    }
    if (!studentFound) {
        cout << "Student record does not exist.";
    }
    cin.get();
    fileStream.close();
    bookFileStream.close();
}

