#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the number of dice and the number of sides on each die.
#define NUM_DICE 5
#define NUM_SIDES 6

// Declare an array to store the results of the dice rolls.
int dice_rolls[NUM_DICE];

// Function to roll a single die.
int roll_die() {
  return rand() % NUM_SIDES + 1;
}

// Function to roll multiple dice and store the results in an array.
void roll_dice(int dice_rolls[]) {
  for (int i = 0; i < NUM_DICE; i++) {
    dice_rolls[i] = roll_die();
  }
}

// Function to calculate the sum of the dice rolls.
int sum_dice_rolls(int dice_rolls[]) {
  int sum = 0;
  for (int i = 0; i < NUM_DICE; i++) {
    sum += dice_rolls[i];
  }
  return sum;
}

// Function to print the results of the dice rolls.
void print_dice_rolls(int dice_rolls[]) {
  printf("The dice rolls are: ");
  for (int i = 0; i < NUM_DICE; i++) {
    printf("%d ", dice_rolls[i]);
  }
  printf("\n");
}

// Main function to run the dice roller program.
int main() {
  // Seed the random number generator.
  srand(time(NULL));

  // Roll the dice and store the results in an array.
  roll_dice(dice_rolls);

  // Print the results of the dice rolls.
  print_dice_rolls(dice_rolls);

  // Calculate the sum of the dice rolls.
  int sum = sum_dice_rolls(dice_rolls);

  // Print the sum of the dice rolls.
  printf("The sum of the dice rolls is: %d\n", sum);

  return 0;
}

