struct TireRotation {

	int getCycle(string a, string b) {

		int ph[][4] = {{0, 1, 2, 3}, {3, 2, 0, 1}, {1, 0, 3, 2}, {2, 3, 1, 0}};

		forn(i, 4) {

			string s;

			forn(j, 4) s += a[ph[i][j]];

			if (s == b) return i + 1;

		}

		return -1;

	}

};





