using namespace std;

#define MIN_BALANCE 500

struct AccountNode {
    float balance;
    string firstName;
    string lastName;
    int accountNumber;
    AccountNode* next;
} *head = nullptr;

class Bank {
public:
    Bank() {}

    void openAccount(const string& firstName, const string& lastName, float initialBalance, int accountNumber);
    void displayAccounts() const;
    void deposit(int amount, int accountNumber);
    void withdraw(int amount, int accountNumber);
    void balanceEnquiry(int accountNumber) const;
    void closeAccount(int accountNumber);
    void transfer(int fromAccount, int toAccount, int amount);
    void generateReceipt(int accountNumber) const;

private:
    int readLastAccountNumber() const;
};

void Bank::openAccount(const string& firstName, const string& lastName, float initialBalance, int accountNumber) {
    ofstream outfile("Bank_data.txt", ios::app);
    outfile << "Account number: " << accountNumber << endl;
    outfile << "First name: " << firstName << endl;
    outfile << "Last name: " << lastName << endl;
    outfile << "Balance: " << initialBalance << endl;
    outfile.close();

    AccountNode* newNode = new AccountNode;
    newNode->firstName = firstName;
    newNode->lastName = lastName;
    newNode->balance = initialBalance;
    newNode->accountNumber = accountNumber;
    newNode->next = nullptr;

    if (head == nullptr) {
        head = newNode;
    } else {
        AccountNode* current = head;
        while (current->next != nullptr) {
            current = current->next;
        }
        current->next = newNode;
    }
}

void Bank::generateReceipt(int accountNumber) const {
    AccountNode* current = head;
    while (current != nullptr) {
        if (current->accountNumber == accountNumber) {
            cout << "\t\t\t\t-----------------------------------------------------------------------------"
                 << endl
                 << "\t\t\t\t\t\t\tBANK RECEIPT " << endl
                 << "\t\t\t\t First name: " << current->firstName << endl
                 << "\t\t\t\t Last name: " << current->lastName << endl
                 << "\t\t\t\t Account number: " << accountNumber << endl
                 << "\t\t\t\t Balance: " << current->balance << endl
                 << "\t\t\t\t\t\tHave a Good day :)" << endl
                 << "\t\t\t\t-----------------------------------------------------------------------------"
                 << endl;
            return;
        }
        current = current->next;
    }
}

int Bank::readLastAccountNumber() const {
    int lastAccountNumber = 0;
    ifstream fin("mob.txt");
    if (fin.is_open()) {
        fin.seekg(-1, ios_base::end);
        bool keepLooping = true;
        while (keepLooping) {
            char ch;
            fin.get(ch);
            if ((int)fin.tellg() <= 1) {
                fin.seekg(0);
                keepLooping = false;
            } else if (ch == '\n') {
                keepLooping = false;
            } else {
                fin.seekg(-2, ios_base::cur);
            }
        }
        string lastLine;
        getline(fin, lastLine);
        lastAccountNumber = stoi(lastLine);
        lastAccountNumber++;
        fin.close();
    }
    return lastAccountNumber;
}

void Bank::transfer(int fromAccount, int toAccount, int amount) {
    AccountNode* sender = head;
    AccountNode* receiver = head;

    while (sender != nullptr && sender->accountNumber != fromAccount) {
        sender = sender->next;
    }

    if (sender == nullptr) {
        cout << "Invalid account number" << endl;
        return;
    }

    while (receiver != nullptr && receiver->accountNumber != toAccount) {
        receiver = receiver->next;
    }

    if (receiver == nullptr) {
        cout << "Entered account number is not valid" << endl;
        return;
    }

    if (sender->balance - amount >= MIN_BALANCE) {
        receiver->balance += amount;
        sender->balance -= amount;
        cout << "Money transfer successful" << endl;
    } else {
        cout << "Insufficient balance" << endl;
    }
}

void Bank::deposit(int amount, int accountNumber) {
    AccountNode* current = head;
    while (current != nullptr) {
        if (current->accountNumber == accountNumber) {
            current->balance += amount;
            ofstream outfile("Bank_data.txt", ios::app);
            outfile << "Balance after deposit: " << current->balance << endl;
            outfile.close();
            cout << "Amount deposited successfully" << endl;
            return;
        }
        current = current->next;
    }
    cout << "Account not found" << endl;
}

void Bank::withdraw(int amount, int accountNumber) {
    AccountNode* current = head;
    while (current != nullptr) {
        if (current->accountNumber == accountNumber) {
            if (current->balance - amount < MIN_BALANCE) {
                cout << "Insufficient balance" << endl;
                return;
            }
            current->balance -= amount;
            cout << "Amount withdrawn successfully" << endl;
            return;
        }
        current = current->next;
    }
    cout << "Account not found" << endl;
}

void Bank::balanceEnquiry(int accountNumber) const {
    AccountNode* current = head;
    while (current != nullptr) {
        if (current->accountNumber == accountNumber) {
            cout << "First name: " << current->firstName << endl;
            cout << "Last name: " << current->lastName << endl;
            cout << "Balance: " << current->balance << endl;
            return;
        }
        current = current->next;
    }
    cout << "Account not found" << endl;
}

void Bank::closeAccount(int accountNumber) {
    AccountNode* current = head;
    AccountNode* previous = nullptr;

    while (current != nullptr && current->accountNumber != accountNumber) {
        previous = current;
        current = current->next;
    }

    if (current == nullptr) {
        cout << "Account not found" << endl;
        return;
    }

    if (previous == nullptr) {
        head = head->next;
    } else {
        previous->next = current->next;
    }

    delete current;
    cout << "Account closed successfully" << endl;
}

void Bank::displayAccounts() const {
    AccountNode* current = head;
    while (current != nullptr) {
        cout << "Account number: " << current->accountNumber << endl;
        cout << "First name: " << current->firstName << endl;
        cout << "Last name: " << current->lastName << endl;
        cout << "Balance: " << current->balance << endl;
        current = current->next;
        cout << endl;
    }
}

