class Prism : public Triangle {
private:
	int prismHeight;
	double prismArea, prismVolume;

public:
	// Constructor initializes the prism with a triangle base and height
	Prism(Triangle baseTriangle, int height) : Triangle(baseTriangle.getLength(), baseTriangle.getHeight()) {
		cout << "Creating a prism..." << endl << endl;
		prismHeight = height;
		prismArea = 2 * baseTriangle.getArea() + height * baseTriangle.getPerimeter();
		prismVolume = baseTriangle.getArea() * height;
	}

	// Returns the surface area of the prism
	double getArea() const {
		return prismArea;
	}

	// Returns the volume of the prism
	double getVolume() const {
		return prismVolume;
	}

	// Outputs the properties of the prism
	void printIt() const {
		cout << "This is a prism." << endl
			<< "It's volume, V = " << getVolume() << endl
			<< "It's area, S = " << getArea() << endl << endl;
	}

	~Prism() {}
};

