using namespace std;

class Bank {
private:
    char accountHolder[30];
    char accountType;
    float balance = 0;
    int transactionLimit = 0;

public:
    int accountNumber;

    // Collects account information from the user
    void createAccount() {
        promptAccountNumber:
        cout << "Enter the 4 digit account number: ";
        cin >> accountNumber;

        if (!isValidAccountNumber(accountNumber)) {
            cout << "Please enter a valid 4 digit account number." << endl;
            goto promptAccountNumber;
        }

        cout << "Enter account holder's name: ";
        cin >> accountHolder;

        promptAccountType:
        cout << "Enter the account type (c for checking or s for savings): ";
        cin >> accountType;

        if (accountType == 's' || accountType == 'S') {
            handleSavingsAccount();
        } else if (accountType == 'c' || accountType == 'C') {
            handleCheckingAccount();
        } else {
            cout << "Please enter a valid account type!" << endl;
            goto promptAccountType;
        }
    }

    // Displays account details
    void displayAccountDetails() {
        if (accountNumber == 0) {
            cout << "No accounts created yet! Please create an account first." << endl;
        } else {
            cout << "------------- Account Details for Account No " << accountNumber << " -------------" << endl;
            cout << "Account Number: " << accountNumber << endl;
            cout << "Account Holder: " << accountHolder << endl;
            cout << "Account Type: " << accountType << endl;
            cout << "Account Balance: " << balance << "/-" << endl;
        }
    }

    float getBalance() {
        return balance;
    }

    void deposit() {
        float amount;
        cout << "Enter the amount to be deposited to account " << accountNumber << ": ";
        cin >> amount;
        balance += amount;
        cout << "Deposit successful! Total balance after deposit is " << balance << "/-" << endl;
        logTransaction("deposition");
    }

    void withdraw() {
        float amount;
        cout << "Enter the amount to be withdrawn: ";
        cin >> amount;

        if (isEligibleForWithdrawal(amount)) {
            balance -= amount;
            cout << "Withdrawal successful! Remaining balance is " << balance << "/-" << endl;
            logTransaction("withdrawal");
        } else {
            cout << "Insufficient balance!" << endl;
        }
    }

    void deleteAccount() {
        logAccountDeletion();
        accountNumber = 0;
        cout << "Account deleted successfully!" << endl;
    }

    friend void transfer(Bank &fromAccount, Bank &toAccount);

private:
    // Validates the account number
    bool isValidAccountNumber(int accNo) {
        int count = 0;
        while (accNo != 0) {
            accNo /= 10;
            count++;
        }
        return count == 4;
    }

    // Handles savings account creation
    void handleSavingsAccount() {
        cout << "For savings accounts, the initial amount should be more than 1000." << endl;
        cout << "Enter your initial amount: ";
        cin >> balance;

        if (balance < 1000) {
            cout << "Insufficient amount for savings account!" << endl;
            handleSavingsAccount();
        } else {
            cout << "Savings account created successfully." << endl;
            logAccountCreation();
        }
    }

    // Handles checking account creation
    void handleCheckingAccount() {
        cout << "For checking accounts, the initial amount should be more than 3000." << endl;
        cout << "Enter your initial amount: ";
        cin >> balance;

        if (balance < 3000) {
            cout << "Insufficient amount for checking account!" << endl;
            handleCheckingAccount();
        } else {
            cout << "Checking account created successfully." << endl;
            logAccountCreation();
        }
    }

    // Checks if the account is eligible for withdrawal
    bool isEligibleForWithdrawal(float amount) {
        if (accountType == 'c' || accountType == 'C') {
            return (balance - amount >= 1000);
        } else {
            return (balance - amount >= 3000);
        }
    }

    // Logs account creation details to a file
    void logAccountCreation() {
        ofstream file("bankfile.txt", ios::app);
        file << "--- New Entry ---" << endl;
        file << "Account Number: " << accountNumber << endl;
        file << "Account Holder: " << accountHolder << endl;
        file << "Account Type: " << accountType << endl;
        file << "Account Balance: " << balance << "/-" << endl;
        file.close();
    }

    // Logs transaction details to a file
    void logTransaction(const string &transactionType) {
        ofstream file("bankfile.txt", ios::app);
        file << "--- Change in Entry due to " << transactionType << " ---" << endl;
        file << "Account Number: " << accountNumber << endl;
        file << "Account Holder: " << accountHolder << endl;
        file << "Account Type: " << accountType << endl;
        file << "Account Balance: " << balance << "/-" << endl;
        file.close();
    }

    // Logs account deletion details to a file
    void logAccountDeletion() {
        ofstream file("bankfile.txt", ios::app);
        file << "--- Deleted an Account ---" << endl;
        file << accountNumber << " Account was deleted by the account holder." << endl;
        file.close();
    }
};

// Transfers money from one account to another
void transfer(Bank &fromAccount, Bank &toAccount) {
    float amount;
    cout << "Enter the amount to be transferred to account " << toAccount.accountNumber << ": ";
    cin >> amount;

    if (fromAccount.isEligibleForWithdrawal(amount)) {
        fromAccount.balance -= amount;
        toAccount.balance += amount;
        cout << "Transaction successful!" << endl;
        cout << "Balance after this transaction in account " << fromAccount.accountNumber << ": " << fromAccount.balance << "/-" << endl;
        cout << "Balance after this transaction in account " << toAccount.accountNumber << ": " << toAccount.balance << "/-" << endl;
        fromAccount.logTransaction("transaction");
        toAccount.logTransaction("transaction");
    } else {
        cout << "Insufficient balance!" << endl;
    }
}

// Authenticates user login
int authenticate() {
    cout << "Please enter login password: ";
    char inputPassword[10] = {0};
    const char correctPassword[10] = "1331";

    for (int i = 0; i < 10; i++) {
        inputPassword[i] = _getch();
        if (inputPassword[i] == 13) {
            inputPassword[i] = '\0';
            break;
        } else {
            _putch('*');
        }
    }

    return strcmp(correctPassword, inputPassword) == 0;
}

// Retrieves account number from user
int getAccountNumber(Bank accounts[], int count) {
    int accountNumber;
    bool isValid = false;

    while (!isValid) {
        cout << "Enter the 4 digit valid account number: ";
        cin >> accountNumber;

        for (int j = 0; j < count; j++) {
            if (accounts[j].accountNumber == accountNumber) {
                isValid = true;
                return j;
            }
        }

        if (!isValid) {
            cout << "Invalid account number!" << endl;
        }
    }
    return -1; // Should not reach here
}

int main() {
    int choice;
    Bank *users = new Bank[100]; // Assuming a maximum of 100 users
    int userCount = 0;

    while (true) {
        cout << "************************* Welcome to Our Bank *************************" << endl;
        cout << "######################### Here's Our Menu ############################" << endl;
        cout << "1. New Account" << endl;
        cout << "2. Get Balance" << endl;
        cout << "3. Withdraw" << endl;
        cout << "4. Deposit" << endl;
        cout << "5. Display Account Details" << endl;
        cout << "6. Display All Accounts' Details" << endl;
        cout << "7. Transfer Money to an Account" << endl;
        cout << "8. Delete an Account" << endl;
        cout << "9. Exit (All accounts will be closed if you exit)" << endl;
        cout << "Enter your choice: ";
        cin >> choice;

        switch (choice) {
            case 1:
                users[userCount++].createAccount();
                break;

            case 2: {
                int index = getAccountNumber(users, userCount);
                cout << "The balance is: " << users[index].getBalance() << "/-" << endl;
                break;
            }

            case 3: {
                int index = getAccountNumber(users, userCount);
                users[index].withdraw();
                break;
            }

            case 4: {
                int index = getAccountNumber(users, userCount);
                users[index].deposit();
                break;
            }

            case 5: {
                int index = getAccountNumber(users, userCount);
                users[index].displayAccountDetails();
                break;
            }

            case 6: {
                if (authenticate()) {
                    cout << endl << "Displaying all account details..." << endl;
                    for (int c = 0; c < userCount; c++) {
                        if (users[c].accountNumber != 0) {
                            users[c].displayAccountDetails();
                            cout << endl;
                        }
                    }
                } else {
                    cout << "Incorrect password!" << endl;
                }
                break;
            }

            case 7: {
                cout << "Enter the account from which money is to be transferred: " << endl;
                int fromIndex = getAccountNumber(users, userCount);
                cout << "Enter the account to which money is to be transferred: " << endl;
                int toIndex = getAccountNumber(users, userCount);
                transfer(users[fromIndex], users[toIndex]);
                break;
            }

            case 8: {
                int index = getAccountNumber(users, userCount);
                users[index].deleteAccount();
                break;
            }

            case 9:
                delete[] users; // Free allocated memory
                exit(0);

            default:
                cout << "Please enter a valid choice!" << endl;
        }

        system("PAUSE");
        system("CLS");
    }

    return 0;
}

#include <stdio.h>
