using namespace std;

/**
 * Global input/output streams for the video database file.
 */
ifstream inputFile;
ofstream outputFile;

/**
 * Class representing a Video record in the library.
 */
class Video {
    int barcode;
    int edition;
    int cost;
    char publisher[50];
    char name[50];

public:
    void insertData(int barcode);
    void modifyData();
    void printData() const;
    int getBarcode() const;
};

/**
 * Inserts data for a new video record.
 * barcode: The barcode of the video being inserted.
 */
void Video::insertData(int barcode) {
    this->barcode = barcode;
    cout << "        Enter Name of the Video: ";
    cin.ignore();
    cin.getline(name, sizeof(name));
    cout << "        Enter the Edition number: ";
    cin >> edition;
    cout << "        Enter the Publisher name: ";
    cin.ignore();
    cin.getline(publisher, sizeof(publisher));

    cost = -1;
    while (cost == -1) {
        cout << "        Enter Price: ";
        cin >> cost;
        if (cost < 0) {
            cost = -1;
            cout << "         Price can't be negative." << endl;
        }
    }
}

/**
 * Modifies the data of an existing video record.
 */
void Video::modifyData() {
    char choice;
    cout << "         Name: ";
    puts(name);
    cout << "         The current Edition is " << edition << endl;
    cout << "         Do you wish to change it? (y/n) ";
    cin >> choice;
    if (choice == 'y' || choice == 'Y') {
        cout << "         Enter the new Edition number: ";
        cin >> edition;
    }

    cout << endl << "         The current Price is " << cost << endl;
    cout << "         Do you wish to change it? (y/n) ";
    cin >> choice;
    if (choice == 'y' || choice == 'Y') {
        cost = -1;
        while (cost == -1) {
            cout << "         Enter the new Price: ";
            cin >> cost;
            if (cost < 0) {
                cost = -1;
                cout << "         Price cannot be negative." << endl;
            }
        }
    }

    cout << endl << "         The current Publisher name is ";
    puts(publisher);
    cout << "         Do you wish to change it?  (y/n) ";
    cin >> choice;
    if (choice == 'y' || choice == 'Y') {
        cout << "         Enter the new Publisher name: ";
        cin.ignore();
        cin.getline(publisher, sizeof(publisher));
    }
}

/**
 * Prints the details of the video record.
 */
void Video::printData() const {
    cout << "        Name: ";
    puts(name);
    cout << "        Edition: " << edition << endl;
    cout << "        Price: " << cost << endl;
    cout << "        Publisher: ";
    puts(publisher);
}

/**
 * Retrieves the barcode of the video.
 */
int Video::getBarcode() const {
    return barcode;
}

/**
 * Checks if a video with the given barcode already exists.
 * barcode: The barcode to look up.
 * Returns 1 if found, 0 otherwise.
 */
int checkBarcodeExists(int barcode) {
    inputFile.seekg(ios::beg);
    Video video;
    while (inputFile.read(reinterpret_cast<char*>(&video), sizeof(video))) {
        if (video.getBarcode() == barcode) {
            return 1;
        }
    }
    return 0;
}

/**
 * Main function for the Video Library Management System.
 */
int main() {
    int choice;
    int barcode;

    do {
        clrscr();
        barcode = -1;
        inputFile.open("video.dat", ios::binary);
        outputFile.open("video.dat", ios::binary | ios::app);

        cout << "=================================================" << endl;
        cout << "         Video Library Management System         " << endl;
        cout << "=================================================" << endl;

        cout << "    Select an option " << endl;
        cout << "    1. Add a Video " << endl;
        cout << "    2. Search a Video " << endl;
        cout << "    3. Edit a Video's information" << endl;
        cout << "    4. Delete a Video" << endl;
        cout << "    5. Show all Videos" << endl;
        cout << "    6. Exit" << endl;
        cout << endl << "      Enter your choice: ";
        cin >> choice;

        switch (choice) {
            case 1:
                while (barcode == -1) {
                    cout << "        Enter the Barcode of the Video: ";
                    cin >> barcode;
                    if (barcode == -1) break;
                    else if (barcode < 0) {
                        cout << "          Barcode can't be negative." << endl;
                        barcode = -1;
                    } else if (checkBarcodeExists(barcode) == 1) {
                        cout << " Video with Barcode " << barcode << " already exists!" << endl;
                        barcode = -1;
                    } else {
                        Video video;
                        video.insertData(barcode);
                        cout << "       Saved!";
                        outputFile.write(reinterpret_cast<char*>(&video), sizeof(video));
                    }
                }
                break;

            case 2:
                while (barcode == -1) {
                    cout << "       Enter Barcode of the Video: ";
                    cin >> barcode;
                    if (barcode == -1) break;
                    else if (barcode < 0) {
                        cout << "          Barcode can't be negative." << endl;
                        barcode = -1;
                    } else if (checkBarcodeExists(barcode) == 0) {
                        cout << "          Video with Barcode " << barcode << " not found!";
                        barcode = -1;
                    } else {
                        Video video;
                        inputFile.seekg(ios::beg);
                        while (inputFile.read(reinterpret_cast<char*>(&video), sizeof(video))) {
                            if (video.getBarcode() == barcode) {
                                video.printData();
                                break;
                            }
                        }
                    }
                }
                break;

            case 3:
                while (barcode == -1) {
                    cout << "        Enter Barcode of the Video: ";
                    cin >> barcode;
                    if (barcode == -1) break;
                    else if (barcode < 0) {
                        cout << "          Barcode can't be negative." << endl;
                        barcode = -1;
                    } else if (checkBarcodeExists(barcode) == 0) {
                        cout << "          Video with Barcode " << barcode << " not found!";
                        barcode = -1;
                    } else {
                        Video video;
                        inputFile.seekg(ios::beg);
                        while (inputFile.read(reinterpret_cast<char*>(&video), sizeof(video))) {
                            if (video.getBarcode() == barcode) {
                                video.modifyData();
                                cout << "       Saved!";
                                break;
                            }
                        }
                        inputFile.clear();
                        inputFile.seekg(ios::beg);
                        ofstream tempFile("temp.dat", ios::binary);
                        while (inputFile.read(reinterpret_cast<char*>(&video), sizeof(video))) {
                            if (video.getBarcode() != barcode) {
                                tempFile.write(reinterpret_cast<char*>(&video), sizeof(video));
                            }
                        }
                        tempFile.write(reinterpret_cast<char*>(&video), sizeof(video));
                        tempFile.close();
                        inputFile.close();
                        remove("video.dat");
                        rename("temp.dat", "video.dat");
                        outputFile.open("video.dat", ios::binary | ios::app);
                    }
                }
                break;

            case 4:
                while (barcode == -1) {
                    cout << "       Enter Barcode of the Video: ";
                    cin >> barcode;
                    if (barcode == -1) break;
                    else if (barcode < 0) {
                        cout << "           Barcode can't be negative." << endl;
                        barcode = -1;
                    } else if (checkBarcodeExists(barcode) == 0) {
                        cout << "       Video with Barcode " << barcode << " not found!";
                        barcode = -1;
                    } else {
                        Video video;
                        inputFile.seekg(ios::beg);
                        while (inputFile.read(reinterpret_cast<char*>(&video), sizeof(video))) {
                            if (video.getBarcode() == barcode) {
                                video.printData();
                                char confirm;
                                cout << "Are you sure you want to delete this record? (y/n) ";
                                cin >> confirm;
                                if (confirm == 'y' || confirm == 'Y') {
                                    cout << "          Record successfully deleted!";
                                    break;
                                }
                            }
                        }
                        inputFile.clear();
                        inputFile.seekg(ios::beg);
                        ofstream tempFile("temp.dat", ios::binary);
                        while (inputFile.read(reinterpret_cast<char*>(&video), sizeof(video))) {
                            if (video.getBarcode() != barcode) {
                                tempFile.write(reinterpret_cast<char*>(&video), sizeof(video));
                            }
                        }
                        tempFile.close();
                        inputFile.close();
                        remove("video.dat");
                        rename("temp.dat", "video.dat");
                        outputFile.open("video.dat", ios::binary | ios::app);
                    }
                }
                break;

            case 5:
                barcode = 0;
                Video video;
                while (inputFile.read(reinterpret_cast<char*>(&video), sizeof(video))) {
                    cout << "       Barcode: " << video.getBarcode() << endl;
                    video.printData();
                    cout << endl;
                    barcode++;
                    getch();
                }
                if (barcode == 0) {
                    cout << "        No records found!";
                } else {
                    cout << "     Only " << barcode << " video record(s) stored!";
                }
                break;

            default:
                if (choice != 6) {
                    cout << "       Invalid option!";
                }
                break;
        }
        inputFile.close();
        outputFile.close();
        getch();

    } while (choice != 6);

    return 0;
}

