#ifndef STOCK_PORTFOLIO_H
#define STOCK_PORTFOLIO_H

#include "account.h"
#include <string>

using namespace std;

// Node class representing each entry in the stock portfolio
class StockNode {
    friend class StockAccount; // Allow StockAccount to access private members

public:
    StockNode(string& stockSymbol, int shareCount)
        : symbol(stockSymbol), numberOfShares(shareCount), next(nullptr), prev(nullptr) {}

private:
    string symbol; // Stock symbol
    int numberOfShares; // Number of shares owned
    StockNode* next; // Pointer to the next node in the list
    StockNode* prev; // Pointer to the previous node in the list
};

// Class representing a stock account, inheriting from Account
class StockAccount : public Account {
public:
    StockAccount();

    static float totalPortfolioValue; // Static variable to hold total portfolio value

    void display(); // Display account information
    void currentPortfolio(); // Show current stocks in the portfolio
    void buyShares(); // Buy shares of a stock
    void addNode(StockNode* newNode); // Add a new stock node to the portfolio
    void sellShares(); // Sell shares of a stock
    void deleteNode(string stockSymbol); // Remove a stock node from the portfolio
    void transactionHistory(); // Display transaction history
    void updateStocks(); // Update stock information
    string getCurrentTime(); // Get the current time

    // Functions for merge sort operation on the stock list
    StockNode* split(StockNode* head); // Split the list into two halves
    StockNode* mergeSort(StockNode* head); // Sort the list using merge sort
    StockNode* sortList(StockNode* first, StockNode* second); // Merge two sorted lists
    void sortWrapper(); // Wrapper function to initiate sorting

    virtual float getBalance(); // Get the current balance
    virtual void setBalance(float newBalance); // Set a new balance

private:
    StockNode* head; // Pointer to the first node in the stock list
    StockNode* tail; // Pointer to the last node in the stock list
    int listSize; // Size of the doubly linked list
};

#endif // STOCK_PORTFOLIO_H

