using namespace std;

class Ticket {
public:
    int id = -1;

    int number = -1;
    string startCity = "undefined";
    string destinationCity = "undefined";
    string departureTime = "undefined";
    string arrivalTime = "undefined";
    double price = 0.0;
    int ticketNumber = -1;

    // Default constructor.
    Ticket() = default;

    // Parameterized constructor for initializing all attributes.
    Ticket(int number, string startCity, string destinationCity, string departureTime, string arrivalTime,
           double price, int ticketNumber) :
            number(number), startCity(move(startCity)), destinationCity(move(destinationCity)),
            departureTime(move(departureTime)), arrivalTime(move(arrivalTime)),
            price(price), ticketNumber(ticketNumber) {}

    /**
     * Converts the ticket object to a JSON representation.
     * Note: C++ lacks true reflection capabilities.
     *
     * @return JSON object representing the ticket.
     */
    Json::Value toJson() const {
        Json::Value ticketJson;

        ticketJson["id"] = to_string(id);
        ticketJson["number"] = to_string(number);
        ticketJson["startCity"] = startCity;
        ticketJson["destinationCity"] = destinationCity;
        ticketJson["departureTime"] = departureTime;
        ticketJson["arrivalTime"] = arrivalTime;
        ticketJson["price"] = to_string(price);
        ticketJson["ticketNumber"] = to_string(ticketNumber);

        return ticketJson;
    }
};

/**
 * Generates a printable string representation of a list of tickets.
 * Returns a message if the list is empty.
 *
 * @param ticketList The list of tickets to generate a string from.
 * @return A formatted string representing the ticket list.
 */
string generatePrintableTicketList(const vector<Ticket> &ticketList) {
    if (ticketList.empty()) return "There is no ticket to show, consider inserting first.";

    using namespace fort;

    utf8_table ticketTable;

    // Center align the first four columns.
    for (int i = 1; i < 5; ++i)
        ticketTable.column(i).set_cell_text_align(text_align::center);

    ticketTable.set_border_style(FT_DOUBLE2_STYLE);
    cout << endl;

    // Set the header for the ticket table.
    ticketTable << header << "Number" << "Start City" << "Destination City" <<
                "Departure Time" << "Arrival Time" << "Price (￥)" << "Ticket Number" << endr;

    // Populate the table with ticket data.
    for (const Ticket &ticket : ticketList)
        ticketTable << ticket.number << ticket.startCity << ticket.destinationCity <<
                    ticket.departureTime << ticket.arrivalTime << ticket.price << ticket.ticketNumber << endr;

    return ticketTable.to_string();
}

