/*
 * Building a FTP Client in C
 *
 * This is a simple example program that demonstrates how to use the C standard library
 * functions to build a FTP client.
 *
 * This program connects to a FTP server using the FTP protocol and retrieves a file.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define FTP_PORT 21
#define FTP_USER "user"
#define FTP_PASS "password"
#define FTP_FILE "example.txt"

int main() {
    int sock;
    struct sockaddr_in server_addr;
    char buf[1024];
    FILE *fp;

    // Create a socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket() failed");
        return 1;
    }

    // Set up the server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(FTP_PORT);
    server_addr.sin_addr.s_addr = inet_addr("127.0.0.1");

    // Connect to the server
    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect() failed");
        return 1;
    }

    // Login to the server
    fprintf(sock, "USER %s\r\n", FTP_USER);
    fprintf(sock, "PASS %s\r\n", FTP_PASS);

    // Get the file
    fprintf(sock, "RETR %s\r\n", FTP_FILE);

    // Open the file for writing
    fp = fopen("example.txt", "w");
    if (fp == NULL) {
        perror("fopen() failed");
        return 1;
    }

    // Read the file from the server and write it to the file
    while (1) {
        int n = read(sock, buf, sizeof(buf));
        if (n < 0) {
            perror("read() failed");
            break;
        } else if (n == 0) {
            break;
        }
        fwrite(buf, 1, n, fp);
    }

    // Close the file and socket
    fclose(fp);
    close(sock);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define constants
#define NUM_CARDS 52
#define NUM_PLAYERS 4
#define NUM_HANDS 5
#define HAND_SIZE 5

// Define a structure to represent a card
typedef struct {
    int rank;
    int suit;
} Card;

// Define a structure to represent a player
typedef struct {
    char name[32];
    int score;
    Card* hand[HAND_SIZE];
} Player;

// Function to shuffle a deck of cards
void shuffle(Card* deck, int num_cards) {
    for (int i = 0; i < num_cards; i++) {
        int random_index = rand() % num_cards;
        Card temp = deck[i];
        deck[i] = deck[random_index];
        deck[random_index] = temp;
    }
}

// Function to deal cards to players
void deal(Player* players, Card* deck, int num_players, int num_cards) {
    for (int i = 0; i < num_players; i++) {
        for (int j = 0; j < HAND_SIZE; j++) {
            players[i].hand[j] = &deck[i * HAND_SIZE + j];
        }
    }
}

// Function to evaluate a hand
int evaluate_hand(Card* hand) {
    int rank = 0;
    int suit = 0;
    for (int i = 0; i < HAND_SIZE; i++) {
        rank += hand[i].rank;
        suit += hand[i].suit;
    }
    return rank + suit;
}

// Function to print the results of a hand
void print_results(Player* players, int num_players) {
    for (int i = 0; i < num_players; i++) {
        printf("Player %d: %d\n", i, players[i].score);
    }
}

int main() {
    // Initialize the deck of cards
    Card deck[NUM_CARDS];
    for (int i = 0; i < NUM_CARDS; i++) {
        deck[i].rank = i % 13 + 1;
        deck[i].suit = i / 13;
    }

    // Shuffle the deck of cards
    shuffle(deck, NUM_CARDS);

    // Initialize the players
    Player players[NUM_PLAYERS];
    for (int i = 0; i < NUM_PLAYERS; i++) {
        players[i].score = 0;
        for (int j = 0; j < HAND_SIZE; j++) {
            players[i].hand[j] = NULL;
        }
    }

    // Deal the cards to the players
    deal(players, deck, NUM_PLAYERS, NUM_CARDS);

    // Evaluate the hands of the players
    for (int i = 0; i < NUM_PLAYERS; i++) {
        players[i].score = evaluate_hand(players[i].hand);
    }

    // Print the results of the game
    print_results(players, NUM_PLAYERS);

    return 0;
}

/*
 * A simple web server that responds to GET requests with a static HTML page.
 * This example uses the C standard library's `socket` and `bind` functions
 * to create a TCP socket and bind it to a port.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>

#define PORT 8080
#define MAX_CONNECTIONS 10
#define HTML_PAGE "<html><body>Hello, world!</body></html>"

int main(void) {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[1024];

    // Create the server socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Set up the server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind the server socket to the address
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_fd, MAX_CONNECTIONS) == -1) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d\n", PORT);

    while (1) {
        // Accept an incoming connection
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd == -1) {
            perror("accept");
            exit(EXIT_FAILURE);
        }

        // Handle the request
        if (read(client_fd, buffer, sizeof(buffer)) > 0) {
            printf("Received request: %s\n", buffer);
            if (strstr(buffer, "GET") != NULL) {
                write(client_fd, HTML_PAGE, strlen(HTML_PAGE));
            }
        }

        // Close the connection
        close(client_fd);
    }

    // Clean up
    close(server_fd);

    return 0;
}

