    char *token;
    char *ssid = NULL;
    char *bssid = NULL;
    FILE *fp;

    fp = popen("iwlist scan", "r");
    if (fp == NULL) {
        printf("Error: Failed to run iwlist scan command.\n");
        exit(1);
    }

    while ((len = fread(buf, 1, BUF_SIZE, fp)) > 0) {
        buf[len] = '\0';
        printf("%s", buf);

        // Extract SSID and BSSID from the output
        token = strtok(buf, " ");
        while (token!= NULL) {
            if (strncmp(token, "ESSID:", 6) == 0) {
                ssid = strtok(NULL, "\"");
            } else if (strncmp(token, "Cell:", 5) == 0) {
                bssid = strtok(NULL, "\"");
            }
            token = strtok(NULL, " ");
        }

        // Print SSID and BSSID
        if (ssid!= NULL && bssid!= NULL) {
            printf("SSID: %s\nBSSID: %s\n", ssid, bssid);
        }

        memset(buf, 0, BUF_SIZE);
    }

    pclose(fp);
}

