void Triangle::setSides(double sideA, double sideB, double sideC) {
    if (sideA <= 0 || sideB <= 0 || sideC <= 0) {
        cerr << "Invalid triangle dimensions.\n";
        exit(1);
    }

    if (!((sideA + sideB > sideC) && (sideC > fabs(sideA - sideB)))) {
        cerr << "Invalid triangle dimensions.\n";
        exit(1);
    }

    if (!((sideA + sideC > sideB) && (sideB > fabs(sideA - sideC)))) {
        cerr << "Invalid triangle dimensions.\n";
        exit(1);
    }

    if (!((sideB + sideC > sideA) && (sideA > fabs(sideB - sideC)))) {
        cerr << "Invalid triangle dimensions.\n";
        exit(1);
    } 

    setSideA(sideA);
    setSideB(sideB);
    setSideC(sideC);
}

double Triangle::calculateArea() const {
    return 0.5 * getSideA() * getSideB() * sin(calculateAngleC() * PI / 180.0);
}

bool Triangle::hasRightAngle() const {
    return (pow(getSideA(), 2) + pow(getSideB(), 2) == pow(getSideC(), 2)) ||
           (pow(getSideB(), 2) + pow(getSideC(), 2) == pow(getSideA(), 2)) ||
           (pow(getSideA(), 2) + pow(getSideC(), 2) == pow(getSideB(), 2));
}

double Triangle::calculateAngleA() const {
    double a = getSideA();
    double b = getSideB();
    double c = getSideC();
    return acos(((b * b) + (c * c) - (a * a)) / (2 * b * c)) * 180 / PI;
}

double Triangle::calculateAngleB() const {
    double a = getSideA();
    double b = getSideB();
    double c = getSideC();
    return acos(((a * a) + (c * c) - (b * b)) / (2 * a * c)) * 180 / PI;
}

double Triangle::calculateAngleC() const {
    double a = getSideA();
    double b = getSideB();
    double c = getSideC();
    return acos(((a * a) + (b * b) - (c * c)) / (2 * a * b)) * 180 / PI;
}

void Triangle::inputSides() {   
    double a, b, c;
    cout << "Enter the new side lengths of the triangle (A, B, C):\n";
    cin >> a >> b >> c;
    setSides(a, b, c);
}

void Triangle::display() const {
    cout << "A: " << getSideA() << " B: " << getSideB() << " C: " << getSideC() << endl;
}

Triangle::Triangle() {
    setSides(1.0, 1.0, 1.0);
}

Triangle::Triangle(double sideLength) {
    setSides(sideLength, sideLength, sideLength);
}

Triangle::Triangle(double sideA, double sideB) {   
    setSides(sideA, sideB, 1.0);
}

