    setSides(sideA, sideB, sideC);
}

#include <stdio.h>
#include <stdlib.h>

#define ROWS 2
#define COLS 2

void printMatrix(float mat[][COLS], char* name) {
    printf("\n%s:\n", name);
    for (int i = 0; i < ROWS; ++i) {
        for (int j = 0; j < COLS; ++j)
            printf(" %0.2f ", mat[i][j]);
        printf("\n");
    }
}

float** inputMatrix(char* name, int rows, int cols) {
    float** mat;
    mat = (float**)calloc(rows, sizeof(float*));
    for (int i = 0; i < rows; ++i) {
        mat[i] = (float*)calloc(cols, sizeof(float));
        for (int j = 0; j < cols; ++j) {
            printf("Enter element %s[%d][%d]: ", name, i, j);
            scanf("%f", &mat[i][j]);
        }
    }
    return mat;
}

float** multiplyMatrices(float** mat1, float** mat2) {
    float** result;
    result = (float**)calloc(ROWS, sizeof(float*));

    for (int i = 0; i < ROWS; ++i) {
        result[i] = (float*)calloc(COLS, sizeof(float));
        for (int j = 0; j < COLS; ++j) {
            result[i][j] = 0;
            for (int k = 0; k < COLS; ++k)
                result[i][j] += mat1[i][k] * mat2[k][j];
        }
    }
    return result;
}

void freeMatrix(float** mat, int rows) {
    for (int i = 0; i < rows; ++i)
        free(mat[i]);
    free(mat);
}

int main() {
    float** A, **B, **C;

    A = inputMatrix("Matrix A", ROWS, COLS);
    B = inputMatrix("Matrix B", ROWS, COLS);

    printMatrix(A, "Matrix A");
    printMatrix(B, "Matrix B");

    C = multiplyMatrices(A, B);

    printMatrix(C, "Product of Matrices A and B");

    for (int i = 0; i < ROWS; ++i) {
        for (int j = 0; j < COLS; ++j) {
            A[i][j] += C[i][j];
            B[i][j] -= C[i][j];
        }
    }

    printMatrix(A, "Matrix A + Product and Matrix B - Product");

    freeMatrix(A, ROWS);
    freeMatrix(B, ROWS);
    freeMatrix(C, ROWS);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define ARRAY_SIZE 100

// Randomized searching algorithm
int search(int arr[], int low, int high, int target) {
  int mid = (low + high) / 2;
  int i = 0;
  int j = ARRAY_SIZE - 1;

  // Generate a random index between low and high
  int random_index = (low + high) * (rand() / (RAND_MAX + 1));

  // Check if the target is found
  if (arr[random_index] == target) {
    return random_index;
  }

  // If not found, search the left and right subarrays
  if (arr[random_index] < target) {
    // Search the left subarray
    for (i = low; i <= mid; i++) {
      if (arr[i] == target) {
        return i;
      }
    }
    // If still not found, search the right subarray
    for (j = mid + 1; j <= high; j++) {
      if (arr[j] == target) {
        return j;
      }
    }
  } else {
    // Search the right subarray
    for (j = mid + 1; j <= high; j++) {
      if (arr[j] == target) {
        return j;
      }
    }
    // If still not found, search the left subarray
    for (i = low; i <= mid; i++) {
      if (arr[i] == target) {
        return i;
      }
    }
  }

  // If still not found, return -1
  return -1;
}

int main() {
  int arr[ARRAY_SIZE] = {1, 2, 3, 4, 5, 6, 7, 8, 9};
  int target = 8;
  int index = search(arr, 0, ARRAY_SIZE - 1, target);

  if (index != -1) {
    printf("Target found at index %d\n", index);
  } else {
    printf("Target not found\n");
  }

  return 0;
}

