#include <linux/kernel.h>
#include <linux/module.h>
#include <linux/bio.h>
#include <linux/blkdev.h>
#include <linux/scatterlist.h>
#include <linux/gfp.h>

#include "blk.h"

struct bio_batch {
	atomic_t		done;
	unsigned long		flags;
	struct completion	*wait;
};

static void bio_batch_end_io(struct bio *bio, int err)
{
	struct bio_batch *bb = bio->bi_private;

	if (err && (err != -EOPNOTSUPP))
		clear_bit(BIO_UPTODATE, &bb->flags);
	if (atomic_dec_and_test(&bb->done))
		complete(bb->wait);
	bio_put(bio);
}

/**
 * blkdev_issue_discard - queue a discard
 * @bdev:	blockdev to issue discard for
 * @sector:	start sector
 * @nr_sects:	number of sectors to discard
 * @gfp_mask:	memory allocation flags (for bio_alloc)
 * @flags:	BLKDEV_IFL_* flags to control behaviour
 *
 * Description:
 *    Issue a discard request for the sectors in question.
 */
int blkdev_issue_discard(struct block_device *bdev, sector_t sector,
		sector_t nr_sects, gfp_t gfp_mask, int flags)
{
	DECLARE_COMPLETION_ONSTACK(wait);
	struct request_queue *q = bdev_get_queue(bdev);
	int type = (1 << BIO_RW) | (1 << BIO_RW_DISCARD);
	unsigned int max_discard_sectors;
	struct bio_batch bb;
	struct bio *bio;
	int ret = 0;

	/*
	 * DEPRECATED support for DISCARD_FL_BARRIER which will
	 * fail with -EOPNOTSUPP (due to implicit BIO_RW_BARRIER)
	 */
	if (flags & DISCARD_FL_BARRIER)
		type = DISCARD_BARRIER;

	if (!q)
		return -ENXIO;

	if (!blk_queue_discard(q))
		return -EOPNOTSUPP;

	/*
	 * Ensure that max_discard_sectors is of the proper
	 * granularity
	 */
	max_discard_sectors = min(q->limits.max_discard_sectors, UINT_MAX >> 9);
	if (unlikely(!max_discard_sectors)) {
		/* Avoid infinite loop below. Being cautious never hurts. */
		return -EOPNOTSUPP;
	} else if (q->limits.discard_granularity) {
		unsigned int disc_sects = q->limits.discard_granularity >> 9;

		max_discard_sectors &= ~(disc_sects - 1);
	}

	atomic_set(&bb.done, 1);
	bb.flags = 1 << BIO_UPTODATE;
	bb.wait = &wait;

	while (nr_sects) {
		bio = bio_alloc(gfp_mask, 1);
		if (!bio) {
			ret = -ENOMEM;
			break;
		}

		bio->bi_sector = sector;
		bio->bi_end_io = bio_batch_end_io;
		bio->bi_bdev = bdev;
		bio->bi_private = &bb;

		if (nr_sects > max_discard_sectors) {
			bio->bi_size = max_discard_sectors << 9;
			nr_sects -= max_discard_sectors;
			sector += max_discard_sectors;
		} else {
			bio->bi_size = nr_sects << 9;
			nr_sects = 0;
		}

		atomic_inc(&bb.done);
		submit_bio(type, bio);
	}

	/* Wait for bios in-flight */
	if (!atomic_dec_and_test(&bb.done))
		wait_for_completion(&wait);

	if (!test_bit(BIO_UPTODATE, &bb.flags))
		ret = -EIO;

	return ret;
}
EXPORT_SYMBOL(blkdev_issue_discard);

/**
 * blkdev_issue_zeroout - generate number of zero filed write bios
 * @bdev:	blockdev to issue
 * @sector:	start sector
 * @nr_sects:	number of sectors to write
 * @gfp_mask:	memory allocation flags (for bio_alloc)
 *
 * Description:
 *  Generate and issue number of bios with zerofiled pages.
 */

int blkdev_issue_zeroout(struct block_device *bdev, sector_t sector,
			sector_t nr_sects, gfp_t gfp_mask)
{
	int ret;
	struct bio *bio;
	struct bio_batch bb;
	unsigned int sz;
	DECLARE_COMPLETION_ONSTACK(wait);

	atomic_set(&bb.done, 1);
	bb.flags = 1 << BIO_UPTODATE;
	bb.wait = &wait;

	ret = 0;
	while (nr_sects != 0) {
		bio = bio_alloc(gfp_mask,
				min(nr_sects, (sector_t)BIO_MAX_PAGES));
		if (!bio) {
			ret = -ENOMEM;
			break;
		}

		bio->bi_sector = sector;
		bio->bi_bdev   = bdev;
		bio->bi_end_io = bio_batch_end_io;
		bio->bi_private = &bb;

		while (nr_sects != 0) {
			sz = min((sector_t) PAGE_SIZE >> 9 , nr_sects);
			ret = bio_add_page(bio, ZERO_PAGE(0), sz << 9, 0);
			nr_sects -= ret >> 9;
			sector += ret >> 9;
			if (ret < (sz << 9))
				break;
		}
		ret = 0;
		atomic_inc(&bb.done);
		submit_bio(WRITE, bio);
	}

	/* Wait for bios in-flight */
	if (!atomic_dec_and_test(&bb.done))
		wait_for_completion(&wait);

	if (!test_bit(BIO_UPTODATE, &bb.flags))
		/* One of bios in the batch was completed with error.*/
		ret = -EIO;

	return ret;
}
EXPORT_SYMBOL(blkdev_issue_zeroout);

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_NODES 100
#define MAX_EDGES 1000

typedef struct Node {
    int id;
    int visited;
    int *adj;
} Node;

Node nodes[MAX_NODES];
int num_nodes, num_edges;
int graph[MAX_NODES][MAX_NODES];

void dfs(int node_id) {
    nodes[node_id].visited = true;
    printf("Visiting Node %d\n", node_id);

    for (int i = 0; i < num_nodes; ++i) {
        if (nodes[i].adj && graph[node_id][i] && !nodes[i].visited) {
            dfs(i);
        }
    }
}

void init_graph() {
    int source, destination;

    for (int i = 0; i < num_edges; ++i) {
        scanf("%d %d", &source, &destination);
        graph[source][destination] = 1;
        graph[destination][source] = 1;
    }
}

void init_nodes() {
    for (int i = 0; i < num_nodes; ++i) {
        nodes[i].id = i;
        nodes[i].visited = false;
        nodes[i].adj = malloc(num_nodes * sizeof(int));
    }
}

void map_topology() {
    for (int i = 0; i < num_nodes; ++i) {
        if (!nodes[i].visited) {
            dfs(i);
        }
    }
}

void build_adj_mat() {
    for (int i = 0; i < num_nodes; ++i) {
        for (int j = 0; j < num_nodes; ++j) {
            if (i == j) continue;
            if (graph[i][j]) {
                nodes[i].adj[j] = 1;
            }
        }
    }
}

int main() {
    printf("\nWelcome, dear reader, to this enchanting journey\n");
    printf("Through the mesmerizing world of network topology mapping!\n");
    printf("Enter the number of nodes and edges in the network:\n");
    scanf("%d %d", &num_nodes, &num_edges);

    init_nodes();
    init_graph();

    printf("Building adjacency matrix...\n");
    build_adj_mat();

    printf("Network Topology Mapping:\n");
    map_topology();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_NODES 10

int adjMat[MAX_NODES][MAX_NODES];
int numNodes;

void printHeader()
{
    printf("\n");
    printf("**********************************************\n");
    printf("          NETWORK TOPOLOGY MAPPER\n");
    printf("**********************************************\n\n");
}

void printMenu()
{
    printf("COMMAND MENU\n\n");
    printf("1. Add node\n");
    printf("2. Remove node\n");
    printf("3. Add connection\n");
    printf("4. Remove connection\n");
    printf("5. Display topology\n");
    printf("6. Exit\n\n");
}

void addNode()
{
    if (numNodes == MAX_NODES)
    {
        printf("Sorry, maximum number of nodes (%d) have already been added.\n", MAX_NODES);
    }
    else
    {
        char nodeName;
        printf("Enter node name: ");
        scanf(" %c", &nodeName);
        adjMat[numNodes][numNodes] = 1;
        printf("Node %c has been added.\n", nodeName);
        numNodes++;
    }
}

void removeNode()
{
    if (numNodes == 0)
    {
        printf("Sorry, there are no nodes to remove.\n");
    }
    else
    {
        int index;
        printf("Enter index of node to remove: ");
        scanf("%d", &index);
        if (index < 0 || index >= numNodes)
        {
            printf("Invalid index. Please try again.\n");
        }
        else
        {
            char nodeName = 'A' + index;
            for (int i = index; i < numNodes - 1; i++)
            {
                for (int j = 0; j < numNodes; j++)
                {
                    adjMat[i][j] = adjMat[i+1][j];
                }
            }
            for (int i = index; i < numNodes - 1; i++)
            {
                for (int j = 0; j < numNodes; j++)
                {
                    adjMat[j][i] = adjMat[j][i+1];
                }
            }
            for (int i = 0; i < numNodes; i++)
            {
                adjMat[numNodes-1][i] = 0;
                adjMat[i][numNodes-1] = 0;
            }
            numNodes--;
            printf("Node %c has been removed.\n", nodeName);
        }
    }
}

void addConnection()
{
    if (numNodes < 2)
    {
        printf("Sorry, you need at least 2 nodes to add a connection.\n");
    }
    else
    {
        int index1, index2;
        printf("Enter index of first node: ");
        scanf("%d", &index1);
        printf("Enter index of second node: ");
        scanf("%d", &index2);
        if (index1 < 0 || index1 >= numNodes || index2 < 0 || index2 >= numNodes || index1 == index2)
        {
            printf("Invalid indices. Please try again.\n");
        }
        else
        {
            adjMat[index1][index2] = 1;
            adjMat[index2][index1] = 1;
            printf("Connection between nodes %c and %c has been added.\n", 'A' + index1, 'A' + index2);
        }
    }
}

void removeConnection()
{
    if (numNodes < 2)
    {
        printf("Sorry, you need at least 2 nodes to remove a connection.\n");
    }
    else
    {
        int index1, index2;
        printf("Enter index of first node: ");
        scanf("%d", &index1);
        printf("Enter index of second node: ");
        scanf("%d", &index2);
        if (index1 < 0 || index1 >= numNodes || index2 < 0 || index2 >= numNodes || index1 == index2)
        {
            printf("Invalid indices. Please try again.\n");
        }
        else if (adjMat[index1][index2] == 0)
        {
            printf("There is no connection between nodes %c and %c.\n", 'A' + index1, 'A' + index2);
        }
        else
        {
            adjMat[index1][index2] = 0;
            adjMat[index2][index1] = 0;
            printf("Connection between nodes %c and %c has been removed.\n", 'A' + index1, 'A' + index2);
        }
    }
}

void displayTopology()
{
    printf("TOPOLOGY\n\n");
    printf("   ");
    for (int i = 0; i < numNodes; i++)
    {
        printf("%c ", 'A' + i);
    }
    printf("\n");
    for (int i = 0; i < numNodes; i++)
    {
        printf("%c  ", 'A' + i);
        for (int j = 0; j < numNodes; j++)
        {
            if (adjMat[i][j] == 1)
            {
                printf("X ");
            }
            else
            {
                printf("  ");
            }
        }
        printf("\n");
    }
}

int main()
{
    printHeader();
    numNodes = 0;
    int choice;
    do
    {
        printMenu();
        printf("Enter command number: ");
        scanf("%d", &choice);
        switch (choice)
        {
            case 1:
                addNode();
                break;
            case 2:
                removeNode();
                break;
            case 3:
                addConnection();
                break;
            case 4:
                removeConnection();
                break;
            case 5:
                displayTopology();
                break;
            case 6:
                printf("Exiting the program...\n");
                break;
            default:
                printf("Invalid command number. Please try again.\n");
