/*
 * Game of Life
 *
 * Usage: ./game_of_life <grid_size> <num_generations>
 *
 * This program simulates the Game of Life, a cellular automaton created by John Conway.
 * The game is played on a grid of cells, where each cell can be either alive or dead.
 * At each generation, the following rules apply:
 * 1. Any live cell with two or three live neighbors survives.
 * 2. Any dead cell with three live neighbors becomes alive.
 * 3. All other live cells die in the next generation.
 * All dead cells stay dead.
 *
 * The program takes two command-line arguments:
 * 1. <grid_size>: the size of the grid, specified as a positive integer
 * 2. <num_generations>: the number of generations to simulate, specified as a positive integer
 *
 * The program outputs the state of the grid at each generation.
 */

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define GRID_SIZE 100
#define NUM_GENERATIONS 100

int main(int argc, char *argv[]) {
  if (argc != 3) {
    printf("Usage: ./game_of_life <grid_size> <num_generations>\n");
    return 1;
  }

  int grid_size = atoi(argv[1]);
  int num_generations = atoi(argv[2]);

  // Initialize the grid with a random starting state
  int grid[GRID_SIZE][GRID_SIZE];
  srand(time(NULL));
  for (int i = 0; i < grid_size; i++) {
    for (int j = 0; j < grid_size; j++) {
      grid[i][j] = rand() % 2;
    }
  }

  // Simulate the Game of Life for the specified number of generations
  for (int i = 0; i < num_generations; i++) {
    // Update the grid based on the Game of Life rules
    for (int i = 0; i < grid_size; i++) {
      for (int j = 0; j < grid_size; j++) {
        int num_live_neighbors = 0;
        for (int k = -1; k <= 1; k++) {
          for (int l = -1; l <= 1; l++) {
            if (i + k >= 0 && i + k < grid_size && j + l >= 0 && j + l < grid_size) {
              num_live_neighbors += grid[i + k][j + l];
            }
          }
        }
        if (grid[i][j] == 0 && num_live_neighbors == 3) {
          grid[i][j] = 1;
        } else if (grid[i][j] == 1 && (num_live_neighbors < 2 || num_live_neighbors > 3)) {
          grid[i][j] = 0;
        }
      }
    }

    // Print the current state of the grid
    printf("Generation %d:\n", i + 1);
    for (int i = 0; i < grid_size; i++) {
      for (int j = 0; j < grid_size; j++) {
        printf("%c ", grid[i][j] == 1 ? '*' : ' ');
      }
      printf("\n");
    }
    printf("\n");
  }

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the maximum number of candidates and voters
#define MAX_CANDIDATES 10
#define MAX_VOTERS 100

// Declare the candidate and voter structures
typedef struct candidate {
    char name[50];
    int votes;
} candidate_t;

typedef struct voter {
    char name[50];
    int voted;
} voter_t;

// Declare the arrays to store the candidates and voters
candidate_t candidates[MAX_CANDIDATES];
voter_t voters[MAX_VOTERS];

// Declare the variables to store the number of candidates and voters
int num_candidates;
int num_voters;

// Declare the function to initialize the voting system
void init_voting_system() {
    // Initialize the number of candidates and voters to 0
    num_candidates = 0;
    num_voters = 0;

    // Initialize the candidates and voters arrays
    for (int i = 0; i < MAX_CANDIDATES; i++) {
        strcpy(candidates[i].name, "");
        candidates[i].votes = 0;
    }

    for (int i = 0; i < MAX_VOTERS; i++) {
        strcpy(voters[i].name, "");
        voters[i].voted = 0;
    }
}

// Declare the function to add a candidate to the voting system
void add_candidate(char *name) {
    // Check if the number of candidates has reached the maximum
    if (num_candidates >= MAX_CANDIDATES) {
        printf("Error: The maximum number of candidates has been reached.\n");
        return;
    }

    // Copy the candidate's name to the candidates array
    strcpy(candidates[num_candidates].name, name);

    // Increment the number of candidates
    num_candidates++;
}

// Declare the function to add a voter to the voting system
void add_voter(char *name) {
    // Check if the number of voters has reached the maximum
    if (num_voters >= MAX_VOTERS) {
        printf("Error: The maximum number of voters has been reached.\n");
        return;
    }

    // Copy the voter's name to the voters array
    strcpy(voters[num_voters].name, name);

    // Increment the number of voters
    num_voters++;
}

// Declare the function to cast a vote for a candidate
void cast_vote(char *voter_name, char *candidate_name) {
    // Find the voter in the voters array
    int voter_index = -1;
    for (int i = 0; i < num_voters; i++) {
        if (strcmp(voters[i].name, voter_name) == 0) {
            voter_index = i;
            break;
        }
    }

    // Check if the voter has already voted
    if (voter_index == -1 || voters[voter_index].voted) {
        printf("Error: The voter has already voted or does not exist.\n");
        return;
    }

    // Find the candidate in the candidates array
    int candidate_index = -1;
    for (int i = 0; i < num_candidates; i++) {
        if (strcmp(candidates[i].name, candidate_name) == 0) {
            candidate_index = i;
            break;
        }
    }

    // Check if the candidate exists
    if (candidate_index == -1) {
        printf("Error: The candidate does not exist.\n");
        return;
    }

    // Increment the candidate's vote count
    candidates[candidate_index].votes++;

    // Mark the voter as having voted
    voters[voter_index].voted = 1;
}

// Declare the function to get the winner of the election
char *get_winner() {
    // Find the candidate with the most votes
    int max_votes = -1;
    char *winner = NULL;
    for (int i = 0; i < num_candidates; i++) {
        if (candidates[i].votes > max_votes) {
            max_votes = candidates[i].votes;
            winner = candidates[i].name;
        }
    }

    return winner;
}

// Declare the function to print the results of the election
void print_results() {
    // Print the header
    printf("Election Results:\n");

    // Print the candidates and their vote counts
    for (int i = 0; i < num_candidates; i++) {
        printf("%s: %d votes\n", candidates[i].name, candidates[i].votes);
    }

    // Print the winner
    char *winner = get_winner();
    printf("Winner: %s\n", winner);
}

// Declare the main function
int main() {
    // Initialize the voting system
    init_voting_system();

    // Add some candidates to the voting system
    add_candidate("John Smith");
    add_candidate("Jane Doe");
    add_candidate("Bob Jones");

    // Add some voters to the voting system
    add_voter("Alice");
    add_voter("Bob");
    add_voter("Carol");

    // Cast some votes
    cast_vote("Alice", "John Smith");
    cast_vote("Bob", "Jane Doe");
    cast_vote("Carol", "Bob Jones");

    // Print the results of the election
    print_results();

    return 0;
}

#include <iostream>
#include <string>
