// Base class for custom exceptions, encapsulating an error message.
class Exception
{
protected:
    std::string message;

public:
    explicit Exception(const std::string& message = "");
};

// Exception for file not found scenarios.
class FileNotFoundException : public Exception {
public:
    explicit FileNotFoundException(const std::string& message = "");
    std::string ToString() const;
};

// Exception for errors encountered while reading a file.
class FileReadException : public Exception {
public:
    explicit FileReadException(const std::string& message = "");
    std::string ToString() const;
};

