int main()
{
    sf::IpAddress serverAddress;
    do
    {
        std::cout << "Enter the FTP server address: ";
        std::cin >> serverAddress;
    } while (serverAddress == sf::IpAddress::None);

    sf::Ftp ftpServer;
    sf::Ftp::Response connectionResponse = ftpServer.connect(serverAddress);
    std::cout << connectionResponse << std::endl;
    if (!connectionResponse.isOk())
        return EXIT_FAILURE;

    std::string username, userPassword;
    std::cout << "User name: ";
    std::cin >> username;
    std::cout << "Password: ";
    std::cin >> userPassword;

    sf::Ftp::Response loginResponse = ftpServer.login(username, userPassword);
    std::cout << loginResponse << std::endl;
    if (!loginResponse.isOk())
        return EXIT_FAILURE;

    int userChoice = 0;
    do
    {
        std::cout << std::endl;
        std::cout << "Choose an action:"                      << std::endl;
        std::cout << "1. Print working directory"             << std::endl;
        std::cout << "2. Print contents of working directory" << std::endl;
        std::cout << "3. Change directory"                    << std::endl;
        std::cout << "4. Create directory"                    << std::endl;
        std::cout << "5. Delete directory"                    << std::endl;
        std::cout << "6. Rename file"                         << std::endl;
        std::cout << "7. Remove file"                         << std::endl;
        std::cout << "8. Download file"                       << std::endl;
        std::cout << "9. Upload file"                         << std::endl;
        std::cout << "0. Disconnect"                          << std::endl;
        std::cout << std::endl;

        std::cout << "Your choice: ";
        std::cin >> userChoice;
        std::cout << std::endl;

        switch (userChoice)
        {
            default:
            {
                std::cout << "Invalid choice!" << std::endl;
                std::cin.clear();
                std::cin.ignore(10000, '\n');
                break;
            }

            case 1:
            {
                sf::Ftp::DirectoryResponse currentDirectoryResponse = ftpServer.getWorkingDirectory();
                std::cout << currentDirectoryResponse << std::endl;
                std::cout << "Current directory is " << currentDirectoryResponse.getDirectory() << std::endl;
                break;
            }

            case 2:
            {
                sf::Ftp::ListingResponse directoryListingResponse = ftpServer.getDirectoryListing();
                std::cout << directoryListingResponse << std::endl;
                const std::vector<std::string>& fileNames = directoryListingResponse.getListing();
                for (const auto& fileName : fileNames)
                    std::cout << fileName << std::endl;
                break;
            }

            case 3:
            {
                std::string targetDirectory;
                std::cout << "Choose a directory: ";
                std::cin >> targetDirectory;
                std::cout << ftpServer.changeDirectory(targetDirectory) << std::endl;
                break;
            }

            case 4:
            {
                std::string newDirectory;
                std::cout << "Name of the directory to create: ";
                std::cin >> newDirectory;
                std::cout << ftpServer.createDirectory(newDirectory) << std::endl;
                break;
            }

            case 5:
            {
                std::string directoryToRemove;
                std::cout << "Name of the directory to remove: ";
                std::cin >> directoryToRemove;
                std::cout << ftpServer.deleteDirectory(directoryToRemove) << std::endl;
                break;
            }

            case 6:
            {
                std::string fileToRename, newFileName;
                std::cout << "Name of the file to rename: ";
                std::cin >> fileToRename;
                std::cout << "New name: ";
                std::cin >> newFileName;
                std::cout << ftpServer.renameFile(fileToRename, newFileName) << std::endl;
                break;
            }

            case 7:
            {
                std::string fileToRemove;
                std::cout << "Name of the file to remove: ";
                std::cin >> fileToRemove;
                std::cout << ftpServer.deleteFile(fileToRemove) << std::endl;
                break;
            }

            case 8:
            {
                std::string fileToDownload, downloadDirectory;
                std::cout << "Filename of the file to download (relative to current directory): ";
                std::cin >> fileToDownload;
                std::cout << "Directory to download the file to: ";
                std::cin >> downloadDirectory;
                std::cout << ftpServer.download(fileToDownload, downloadDirectory) << std::endl;
                break;
            }

            case 9:
            {
                std::string fileToUpload, uploadDirectory;
                std::cout << "Path of the file to upload (absolute or relative to working directory): ";
                std::cin >> fileToUpload;
                std::cout << "Directory to upload the file to (relative to current directory): ";
                std::cin >> uploadDirectory;
                std::cout << ftpServer.upload(fileToUpload, uploadDirectory) << std::endl;
                break;
            }

            case 0:
            {
                break;
            }
        }

    } while (userChoice != 0);

    std::cout << "Disconnecting from server..." << std::endl;
    std::cout << ftpServer.disconnect() << std::endl;

    std::cout << "Press enter to exit..." << std::endl;
    std::cin.ignore(10000, '\n');
    std::cin.ignore(10000, '\n');

    return EXIT_SUCCESS;
}

