void runAllTests() {
    executeTest("1. Testing S1: String default ctor.", []() {
        String defaultString;
        defaultString.print();
    });

    executeTest("2. Testing S2: String one arg (char *) ctor.", []() {
        String stringFromChar("ABC");
        stringFromChar.print();
    });

    executeTest("3. Testing S3: String one arg (char) ctor.", []() {
        String stringFromChar('Z');
        stringFromChar.print();
    });

    executeTest("4. Testing S4: String one arg (int) ctor.", []() {
        String stringFromInt(10);
        stringFromInt.print();
    });

    executeTest("5. Testing S5, T5: String copy ctor.", []() {
        String originalString("Purple Rain");
        originalString.print();
        String copiedString(originalString);
        copiedString.print();
    });

    executeTest("6. Testing S6: String two arg (char, int) ctor.", []() {
        String stringWithCharAndInt('*', 10);
        stringWithCharAndInt.print();
    });

    executeTest("7. Testing S7, T7, U7: String assignment.", []() {
        String sourceString("Sally Ride"), assignedString, anotherAssignedString;
        assignedString = anotherAssignedString = sourceString;
        sourceString.print();
        assignedString.print();
        anotherAssignedString.print();
    });

    executeTest("8. Testing S8: String assignment.", []() {
        String stringToSelfAssign("ABC");
        stringToSelfAssign = stringToSelfAssign;
        stringToSelfAssign.print();
    });

    executeTest("9. Testing S9: Implicit type conversion.", []() {
        String convertedString;
        convertedString = "ABC";
        convertedString.print();
    });

    executeTest("10. Testing S10, T10, U10: String concatenation.", []() {
        String firstString("DEF");
        String secondString('H');
        String concatenatedString("ABC" + firstString + "G" + secondString + 'I');
        concatenatedString.print();
        String prefixedString('X' + concatenatedString);
        prefixedString.print();
    });

    executeTest("11. Testing S11, T11: String concatenation.", []() {
        String firstConcatString('A');
        String secondConcatString("BC");
        firstConcatString += firstConcatString += secondConcatString += 'D';
        firstConcatString.print();
        secondConcatString.print();
    });

    executeTest("12. Testing S12, T12: String unary operator.", []() {
        String unaryString("Unary +");
        String unaryResult(+unaryString);
        unaryString.print();
        unaryResult.print();
        unaryString = +unaryString;
        unaryString.print();
    });

    executeTest("13. Testing S13, T13: String comparison operators.", []() {
        String firstCompareString("ABC"), secondCompareString("ABCD");
        firstCompareString.print();
        secondCompareString.print();
        outputComparisonResults(firstCompareString, secondCompareString);
    });

    executeTest("14. Testing S14: Overloaded subscript operator.", []() {
        String subscriptString("C++ is fun.");
        for (int i = -1; i <= subscriptString.getLength(); i++) {
            char& character = subscriptString[i];
            if (character != '\0')
                ++character;
        }
        subscriptString.print();
    });

    executeTest("15. Testing S15: Pointer notation.", []() {
        String pointerString("ABCDE");
        for (int i = 0; i < pointerString.getLength(); i++)
            ++(*(pointerString + i));
        for (int j = 0; j < pointerString.getLength(); j++) {
            cout << *(j + pointerString);
            outputFile << *(j + pointerString);
        }
        cout << endl;
        outputFile << endl;
    });

    executeTest("16. Testing S16, T16, U16, V16, W16, X16, Y16, Z16: Increment and decrement operators.", []() {
        String incrementString("ABC");
        String incrementedString(++incrementString);
        incrementString.print();
        incrementedString.print();

        String postIncrementString("ABC");
        String postIncrementedString(postIncrementString++);
        postIncrementString.print();
        postIncrementedString.print();

        String decrementString("ABC");
        String decrementedString(--decrementString);
        decrementString.print();
