#define MAX_ROWS 10
#define MAX_COLS 10
#define MAX_STRlen 20

typedef struct {
    int rows;
    int cols;
    int **matrix;
} matrix_t;

void init_matrix(matrix_t *matrix) {
    matrix->rows = 0;
    matrix->cols = 0;
    matrix->matrix = NULL;
}

void destroy_matrix(matrix_t *matrix) {
    if (matrix->matrix != NULL) {
        free(matrix->matrix);
    }
    matrix->rows = 0;
    matrix->cols = 0;
}

int add_element(matrix_t *matrix, int row, int col, int value) {
    if (matrix->rows == MAX_ROWS || matrix->cols == MAX_COLS) {
        return 0;
    }

    if (row >= matrix->rows || col >= matrix->cols) {
        return 0;
    }

    if (matrix->matrix == NULL) {
        matrix->matrix = (int **) calloc(matrix->rows, sizeof(int *));
        if (matrix->matrix == NULL) {
            return 0;
        }
    }

    matrix->matrix[row][col] = value;
    return 1;
}

int get_element(matrix_t *matrix, int row, int col) {
    if (matrix->rows == MAX_ROWS || matrix->cols == MAX_COLS) {
        return 0;
    }

    if (row >= matrix->rows || col >= matrix->cols) {
        return 0;
    }

    return matrix->matrix[row][col];
}

int multiply_matrices(matrix_t *a, matrix_t *b, matrix_t *result) {
    int i, j, k;
    int rows_a = a->rows, cols_a = a->cols, rows_b = b->rows, cols_b = b->cols;

    if (rows_a == 0 || rows_b == 0) {
        return 0;
    }

    if (cols_a != rows_b) {
        return 0;
    }

    result->rows = rows_a;
    result->cols = cols_b;
    result->matrix = (int **) calloc(result->rows, sizeof(int *));

    for (i = 0; i < rows_a; i++) {
        result->matrix[i] = (int *) calloc(cols_b, sizeof(int));

        for (j = 0; j < cols_b; j++) {
            int sum = 0;

            for (k = 0; k < rows_b; k++) {
                sum += a->matrix[i][k] * b->matrix[k][j];
            }

            result->matrix[i][j] = sum;
        }
    }

    return 1;
}

int main() {
    matrix_t a, b, result;

    init_matrix(&a);
    init_matrix(&b);
    init_matrix(&result);

    add_element(&a, 1, 2, 3);
    add_element(&a, 2, 3, 4);
    add_element(&b, 1, 1, 5);
    add_element(&b, 2, 2, 6);

    if (!multiply_matrices(&a, &b, &result)) {
        printf("Matrix multiplication failed\n");
        return 1;
    }

    for (int i = 0; i < result.rows; i++) {
        for (int j = 0; j < result.cols; j++) {
            printf("%d ", result.matrix[i][j]);
        }
        printf("\n");
    }

    destroy_matrix(&a);
    destroy_matrix(&b);
    destroy_matrix(&result);

    return 0;
}

