// Abstract base class representing a storable entity
struct Storable
{
    Storable()
    {
        cout << "# ctor --> Storable" << endl;
    }

    virtual void write() = 0; // Pure virtual function for writing data

    int calculateSum()
    {
        int baseValue = 2;
        return baseValue + 2; // Returns a constant sum
    }

    virtual ~Storable() {} // Virtual destructor for proper cleanup
};

// Class representing a transmitter, inheriting from Storable
class Transmitter : public virtual Storable
{
public:
    Transmitter()
    {
        cout << "ctor --> Transmitter" << endl;
    }

    void write() override
    {
        cout << "Transmitter ... " << endl; // Output specific to Transmitter
    }
};

// Class representing a receiver, inheriting from Storable
class Receiver : public virtual Storable
{
public:
    Receiver()
    {
        cout << "ctor --> Receiver " << endl;
    }

    void write() override
    {
        cout << "Receiver ..." << endl; // Output specific to Receiver
    }
};

// Class representing a radio, combining both Transmitter and Receiver functionalities
class Radio : public Receiver, public Transmitter
{
public:
    void write() override
    {
        Transmitter::write(); // Call Transmitter's write method
        Receiver::write();    // Call Receiver's write method
        cout << "radio info .." << endl; // Additional output for Radio
    }
};

int main()
{
    // Demonstrates the construction of Radio, which utilizes virtual inheritance
    Radio radioDevice;
    radioDevice.write(); // Invoke write method to display information

    return 0;
}

