void writeAccount() {
    BankAccount account;
    ofstream outFile("account.dat", ios::binary | ios::app);
    account.createAccount();
    outFile.write(reinterpret_cast<char*>(&account), sizeof(BankAccount));
    outFile.close();
}

void displaySingleAccount(int accountNumber) {
    BankAccount account;
    bool found = false;
    ifstream inFile("account.dat", ios::binary);
    if (!inFile) {
        cout << "File could not be opened. Press any key.";
        return;
    }
    cout << "\nBalance Details\n";

    while (inFile.read(reinterpret_cast<char*>(&account), sizeof(BankAccount))) {
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();
            found = true;
        }
    }
    inFile.close();
    if (!found) {
        cout << "\n\nAccount number does not exist";
    }
}

void modifyAccount(int accountNumber) {
    bool found = false;
    BankAccount account;
    fstream file("account.dat", ios::binary | ios::in | ios::out);
    if (!file) {
        cout << "File could not be opened";
        return;
    }
    while (!file.eof() && !found) {
        file.read(reinterpret_cast<char*>(&account), sizeof(BankAccount));
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();
            cout << "\n\nEnter The new details of account: " << endl;
            account.modifyAccount();
            int position = (-1) * static_cast<int>(sizeof(BankAccount));
            file.seekp(position, ios::cur);
            file.write(reinterpret_cast<char*>(&account), sizeof(BankAccount));
            cout << "\n\n\tRecord Updated";
            found = true;
        }
    }
    file.close();
    if (!found) {
        cout << "\n\nRecord Not Found";
    }
}

void deleteAccount(int accountNumber) {
    BankAccount account;
    ifstream inFile("account.dat", ios::binary);
    if (!inFile) {
        cout << "File could not be opened";
        return;
    }
    ofstream outFile("Temp.dat", ios::binary);
    while (inFile.read(reinterpret_cast<char*>(&account), sizeof(BankAccount))) {
        if (account.getAccountNumber() != accountNumber) {
            outFile.write(reinterpret_cast<char*>(&account), sizeof(BankAccount));
        }
    }
    inFile.close();
    outFile.close();
    remove("account.dat");
    rename("Temp.dat", "account.dat");
    cout << "\n\n\tRecord Deleted...";
}

void displayAllAccounts() {
    BankAccount account;
    ifstream inFile("account.dat", ios::binary);
    if (!inFile) {
        cout << "File could not be opened";
        return;
    }
    cout << "\n\n\t\tAccount holder list\n\n";
    cout << "===================================================";
    cout << "A/c no.        NAME            TYPE BALANCE\n";
    cout << "===================================================";

    while (inFile.read(reinterpret_cast<char*>(&account), sizeof(BankAccount))) {
        account.displayAccount();
    }
    inFile.close();
}

void depositWithdraw(int accountNumber, int option) {
    int amount;
    bool found = false;
    BankAccount account;
    fstream file("account.dat", ios::binary | ios::in | ios::out);
    if (!file) {
        cout << "File could not be opened";
        return;
    }
    while (!file.eof() && !found) {
        file.read(reinterpret_cast<char*>(&account), sizeof(BankAccount));
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();
            if (option == 1) {
                cout << "\n\n\tTO DEPOSIT AMOUNT";
                cout << "\n\nEnter The amount to be deposited: ";
                cin >> amount;
                account.deposit(amount);
            } else if (option == 2) {
                cout << "\n\n\tTO WITHDRAW AMOUNT";
                cout << "\n\nEnter The amount to be withdrawn: ";
                cin >> amount;
                int newBalance = account.getBalance() - amount;
                if ((newBalance < 500 && account.getAccountType() == 'S') || (newBalance < 1000 && account.getAccountType() == 'C')) {
                    cout << "Insufficient balance";
                } else {
                    account.withdraw(amount);
                }
            }
            int position = (-1) * static_cast<int>(sizeof(account));
            file.seekp(position, ios::cur);
            file.write(reinterpret_cast<char*>(&account), sizeof(BankAccount));
            cout << "\n\n\tRecord Updated";
            found = true;
        }
    }
    file.close();
    if (!found) {
        cout << "\n\nRecord Not Found";
    }
}

