    cout << "\n\n\n\t BANK";
    cout << "\n\n\tManagement";
    cout << "\n\n\t SYSTEM";
    cout << "\n\n\n\nMADE BY: ";
    cout << "\n\nSCHOOL: Your school name";
    cin.get();
}

