int main() {
    AbstractClass *abstractPointer;

    DerivedA instanceA(1);
    DerivedB instanceB;
    DerivedA* pointerA = new DerivedA(1);
    DerivedB* pointerB = new DerivedB();

    instanceA.displayMessage();
    instanceB.displayMessage();

    pointerA->displayMessage();
    pointerB->displayMessage();

    // Upcasting
    instanceA = instanceB;
    pointerA = &instanceB;

    cout << endl << "-----------------";
    instanceA.displayMessage();
    instanceA.displayVirtualMessage();

    pointerA->displayMessage();
    pointerA->displayVirtualMessage();
    pointerB->displayVirtualMessage();

    abstractPointer = &instanceA;
    abstractPointer->mandatoryFunction(10);
    abstractPointer = &instanceB;
    abstractPointer->mandatoryFunction(10);

    string message;
    cout << endl << "The message is:";
    cin >> message;
    cout << endl << "****** " << message;

    if (!instanceB)
        cout << endl << "The average of values is 0";
    else
        cout << endl << " The average is " << (float)instanceB;

    Student *studentList = new Student[10];

    Student student1(21, "Gigel", "CSIE");
    studentList[0] = student1;

    Student **group = new Student*[10];
    group[0] = new Student(21, "Ana", "CSIE");
