void display_guests(Guest guests[], int guest_count) {
    int i;
    for (i = 0; i < guest_count; i++) {
        printf("%s\n", guests[i].name);
        printf("%s\n", guests[i].address);
        printf("%d\n", guests[i].phone_number);
