    int reportStatus();

    // Retrieves queued data for delivery to the upper layer, including sequence number and data size
    int receiveData(short *sourceAddress, short *destinationAddress, char *buffer, int bufferSize);

    // Sends a packet to the specified address with the provided information from the buffer
    int sendData(short destinationAddress, char *buffer, int bufferSize);

