    RF* rfLayer; // Associated RF layer with DemiBrad
    queue<Packet> sendQueue; // Queue for packets to be sent
    queue<Packet> receiveQueue; // Queue for packets received from the receiver class
    pthread_mutex_t mutexReceiver; // Mutex for the incoming packet queue
    pthread_mutex_t mutexSender; // Mutex for the outgoing packet queue
    pthread_mutex_t mutexOutputStream; // Mutex for thread-safe output to the stream
    pthread_mutex_t mutexTimeAdjustment; // Mutex for timestamp adjustments
    pthread_mutex_t mutexAttachRfLayer; // Mutex for attaching threads to the RF layer
    pthread_mutex_t statusMutex; // Mutex for managing the current status code
    pthread_mutexattr_t mutexAttributes; // Structure for initializing mutex attributes
    volatile long long timeAdjustment; // Offset for synchronizing RF layer clock to network time
    volatile short expectedSequenceNumber; // Flag indicating the expected sequence number for incoming acknowledgments
    volatile int statusCode; // Current status code for the most recent operation
    volatile int commandCodes[4]; // Array holding command values
    volatile bool ackReceived; // Flag indicating acknowledgment receipt
    short macAddress; // User's MAC address
};

