#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX 100
#define FCFS 1
#define SJF 2
#define PRIORITY 3
#define ROUND_ROBIN 4

struct process {
    int pid;
    int burst_time;
    int waiting_time;
    int turnaround_time;
    int priority;
};

void execute_processes(struct process *processes, int num_processes, int scheduling_algorithm) {
    int completed_processes = 0;
    int current_time = 0;
    int current_process = 0;

    printf("\nCPU Scheduling Algorithm: ");
    switch(scheduling_algorithm) {
        case FCFS:
            printf("First Come First Serve\n");
            break;
        case SJF:
            printf("Shortest Job First\n");
            break;
        case PRIORITY:
            printf("Priority Scheduling\n");
            break;
        case ROUND_ROBIN:
            printf("Round Robin Scheduling\n");
            break;
        default:
            printf("Invalid algorithm\n");
            exit(0);
    }

    while(completed_processes < num_processes) {
        if(current_time >= processes[current_process].burst_time) {
            printf("\nProcess %d completed at time %d\n", processes[current_process].pid, current_time);
            completed_processes++;
            current_process++;
            current_time = 0;
        } else {
            printf("\nExecuting process %d at time %d\n", processes[current_process].pid, current_time);
            current_time += 1;
        }
    }
}

void generate_random_processes(struct process *processes, int num_processes) {
    srand(time(NULL));

    for(int i = 0; i < num_processes; i++) {
        processes[i].pid = i + 1;
        processes[i].burst_time = rand() % 20 + 1;
        processes[i].waiting_time = 0;
        processes[i].turnaround_time = 0;
        processes[i].priority = rand() % 3;
    }
}

int main() {
    int num_processes = 10;
    int scheduling_algorithm = FCFS;

    struct process processes[MAX];

    generate_random_processes(processes, num_processes);

    execute_processes(processes, num_processes, scheduling_algorithm);

    return 0;
}

