#include "actor.h"
#include "lead_actor.h"
#include "film.h"

template <class T = actor>
class DistributionCompany {
    std::vector<film*> filmRoles;
    static int totalPeople;
    static int totalActors;

public:
    DistributionCompany() = default;

    explicit DistributionCompany(const std::vector<film*>& films) {
        for (const auto& film : films) {
            insertFilm(film);
        }
    }

    // Adds a film to the distribution company and updates actor counts
    void insertFilm(film* f) {
        filmRoles.push_back(f);

        for (const auto& person : f->getPeopleInvolved()) {
            totalPeople++;
            if (typeid(*person).name() == typeid(actor).name() || 
                typeid(*person).name() == typeid(lead_actor).name()) {
                totalActors++;
            }
        }
    }

    static int getTotalPeople() {
        return totalPeople;
    }

    static int getTotalActors() {
        return totalActors;
    }

    ~DistributionCompany() {
        for (auto& film : filmRoles) {
            delete film;
        }
    }
};

