#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>

#define MAX_SERVICES 50
#define CMD_LENGTH 256

typedef struct {
    char name[50];
    int priority;
    int delay; // in seconds
} Service;

Service services[MAX_SERVICES];
int serviceCount = 0;

void addService(const char* name, int priority, int delay) {
    if (serviceCount < MAX_SERVICES) {
        strncpy(services[serviceCount].name, name, sizeof(services[serviceCount].name));
        services[serviceCount].priority = priority;
        services[serviceCount].delay = delay;
        serviceCount++;
    } else {
        printf("Cannot add more services, max limit reached!\n");
    }
}

void sortServices() {
    for (int i = 0; i < serviceCount - 1; i++) {
        for (int j = 0; j < serviceCount - i - 1; j++) {
            if (services[j].priority > services[j + 1].priority) {
                Service temp = services[j];
                services[j] = services[j + 1];
                services[j + 1] = temp;
            }
        }
    }
}

void optimizeBootSequence() {
    sortServices();
    printf("Initiating Optimized Boot Sequence...\n");
    for (int i = 0; i < serviceCount; i++) {
        printf("Starting service: %s (Priority: %d) after %d seconds\n", 
               services[i].name, services[i].priority, services[i].delay);
        sleep(services[i].delay);
        // Simulate service start
        printf("Service %s is now running...\n", services[i].name);
    }
    printf("All services started successfully!\n");
}

void loadConfiguration() {
    // Simulating loading from a config file
    printf("Loading configurations...\n");
    addService("Network Manager", 1, 5);
    addService("Logging Service", 2, 2);
    addService("Database Service", 3, 3);
    addService("Web Server", 4, 4);
    addService("User Session Service", 5, 1);
}

void displayServices() {
    printf("\nLoaded Services:\n");
    for (int i = 0; i < serviceCount; i++) {
        printf("%d: %s (Priority: %d, Delay: %d seconds)\n", i + 1, 
               services[i].name, services[i].priority, services[i].delay);
    }
}

int main() {
    loadConfiguration();
    displayServices();
    optimizeBootSequence();
    return 0;
}

