#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 10

typedef struct Item {
    int item_id;
    int quantity;
    struct Item* next;
} Item;

void insertItem(Item* head, int item_id, int quantity) {
    Item* newNode = (Item*)malloc(sizeof(Item));
    newNode->item_id = item_id;
    newNode->quantity = quantity;
    newNode->next = NULL;

    if (head == NULL) {
        head = newNode;
    } else {
        Item* tail = head;
        while (tail->next) {
            tail = tail->next;
        }
        tail->next = newNode;
    }
}

int main() {
    Item* head = NULL;

    // Simulate post-apocalyptic scavenging
    insertItem(head, 1, 5);
    insertItem(head, 2, 3);
    insertItem(head, 3, 2);
    insertItem(head, 4, 4);

    // Greedy Algorithm - take as much as you can from the first item
    Item* currentItem = head;
    int totalQuantity = 0;
    while (currentItem) {
        int itemQuantity = currentItem->quantity;
        if (itemQuantity > totalQuantity) {
            totalQuantity = itemQuantity;
        }
        currentItem = currentItem->next;
    }

    // Display the total quantity
    printf("Total quantity taken: %d\n", totalQuantity);

    return 0;
}

#include <iostream>
#include <memory>

// Interface that defines the expected operations for the client
class Target {
public:
	virtual void requestFirst() const = 0;
	virtual void requestSecond() const = 0;
	virtual void requestThird() const = 0;
	virtual void requestFourth() const = 0;
	virtual ~Target() {}
};

// Existing class with a specific interface that needs to be adapted
class Adaptee {
public:
	void specificRequestOne() const {
		std::cout << "Specific request 1" << std::endl;
	}

	void specificRequestTwo() const {
		std::cout << "Specific request 2" << std::endl;
	}

	void specificRequestThree(int value) const {
		std::cout << "Specific request 3 set value = " << value << std::endl;
	}

	void specificRequestFour() const {
		std::cout << "Specific request 4" << std::endl;
	}

	void specificRequestFive() const {
		std::cout << "Specific request 5" << std::endl;
	}

	~Adaptee() {}
};

// Adapter class that bridges the Target interface and the Adaptee's interface
class Adapter : public Target, private Adaptee {
public:
	virtual void requestFirst() const override {
		specificRequestOne();
		specificRequestTwo();
	}

	virtual void requestSecond() const override {
		specificRequestThree(5);
	}

	virtual void requestThird() const override {
		specificRequestThree(10);
	}

	virtual void requestFourth() const override {
		specificRequestFour();
		specificRequestFive();
	}

	virtual ~Adapter() {}
};

int main() {
	std::unique_ptr<Target> target = std::make_unique<Adapter>();
	target->requestFirst();
	target->requestSecond();
	target->requestThird();
	target->requestFourth();

	system("pause");
	return 0;
}

#include <iostream>

using std::cout;
