class Cube {
public:
    // Calculates the volume of the cube
    double getVolume();

    // Calculates the surface area of the cube
    double getSurfaceArea();

    // Sets the length of the cube's side
    void setLength(double length);

private:
    double sideLength_;
};

double Cube::getVolume() {
    // Volume is calculated as side length cubed
    return sideLength_ * sideLength_ * sideLength_;
}

double Cube::getSurfaceArea() {
    // Surface area is calculated as 6 times the square of the side length
    return 6 * sideLength_ * sideLength_;
}

void Cube::setLength(double length) {
    sideLength_ = length;
}

int main() {
    int* heapIntPointer = new int; // Pointer to an integer in heap memory
    Cube* cubePointer = new Cube;   // Pointer to a Cube object in heap memory

    *heapIntPointer = 42; // Assigning value to the allocated integer
    cubePointer->setLength(14); // Setting the length of the cube

    // Displaying the address of the pointer and its value
    cout << "Address of heapIntPointer stored in stack memory: " << &heapIntPointer << endl;
    cout << "Value of heapIntPointer stored in heap memory: " << *heapIntPointer << endl;

    // Clean up allocated memory
    delete heapIntPointer;
    heapIntPointer = nullptr;

    delete cubePointer;
    cubePointer = nullptr;

    return 0;
}

