#include <iostream>
using namespace std;

class Node {
public:
    Node* next;
    Node* prev;
    int data;

    Node(int value) : next(nullptr), prev(nullptr), data(value) {}
};

class DoublyLinkedList {
    Node* head;

public:
    DoublyLinkedList() : head(nullptr) {}

    // Initializes the list with user-defined elements
    void create() {
        int numberOfElements, element;
        cout << "How many elements do you want? " << endl;
        cin >> numberOfElements;
        for (int i = 1; i <= numberOfElements; i++) {
            cout << "Enter element " << i << ": ";
            cin >> element;
            addAtEnd(element);
        }
    }

    // Adds an element at the beginning of the list
    void addAtBeginning(int value) {
        Node* newNode = new Node(value);
        newNode->next = head;
        if (head != nullptr) {
            head->prev = newNode;
        }
        head = newNode;
    }

    // Adds an element at the end of the list
    void addAtEnd(int value) {
        if (head == nullptr) {
            addAtBeginning(value);
            return;
        }

        Node* current = head;
        while (current->next != nullptr) {
            current = current->next;
        }

        Node* newNode = new Node(value);
        newNode->prev = current;
        current->next = newNode;
    }

    // Adds an element at a specific position in the list
    void addAtPosition(int position, int value) {
        int listSize = count();
        if (position > listSize + 1 || position < 1) {
            cout << "Invalid position chosen: " << position << endl;
            return;
        }

        if (position == 1) {
            addAtBeginning(value);
            return;
        }

        Node* newNode = new Node(value);
        Node* current = head;
        for (int i = 1; i < position - 1; i++) {
            current = current->next;
        }

        newNode->prev = current;
        newNode->next = current->next;
        current->next = newNode;

        if (newNode->next != nullptr) {
            newNode->next->prev = newNode;
        }
    }

    // Deletes the first element of the list
    void deleteAtBeginning() {
        if (head == nullptr) {
            return;
        }

        Node* temp = head;
        head = head->next;
        delete temp;

        if (head != nullptr) {
            head->prev = nullptr;
        }
    }

    // Deletes the last element of the list
    void deleteAtEnd() {
        if (head == nullptr) {
            return;
        }

        if (head->next == nullptr) {
            delete head;
            head = nullptr;
            return;
        }

        Node* current = head;
        while (current->next != nullptr) {
            current = current->next;
        }

        current->prev->next = nullptr;
        delete current;
    }

    // Deletes an element at a specific position in the list
    void deleteAtPosition(int position) {
        int listSize = count();
        if (position < 1 || position > listSize) {
            cout << "Invalid position: " << position << endl;
            return;
        }

        if (position == 1) {
            deleteAtBeginning();
            return;
        }

        Node* current = head;
        for (int i = 1; i < position - 1; i++) {
            current = current->next;
        }

        Node* nodeToDelete = current->next;
        current->next = nodeToDelete->next;

        if (nodeToDelete->next != nullptr) {
            nodeToDelete->next->prev = current;
        }

        delete nodeToDelete;
    }

    // Counts the number of elements in the list
    int count() {
        if (head == nullptr) {
            return 0;
        }

        int counter = 0;
        Node* current = head;
        while (current != nullptr) {
            current = current->next;
            counter++;
        }
        return counter;
    }

    // Displays the elements of the list
    void display() {
        Node* current = head;
        while (current != nullptr) {
            cout << current->data << " ";
            current = current->next;
        }
        cout << "\n" << endl;
    }
};

int main() {
    DoublyLinkedList list;
    int choice, element, position;

    while (true) {
        cout << "1) Create List " << endl;
        cout << "2) Add at Beginning " << endl;
        cout << "3) Add at End " << endl;
        cout << "4) Add at Position " << endl;
        cout << "5) Delete at Beginning " << endl;
        cout << "6) Delete at End " << endl;
        cout << "7) Delete at Position " << endl;
        cout << "8) Count " << endl;
        cout << "9) Display " << endl;
        cout << "10) Exit " << endl;
        cout << "Enter your choice: ";
        cin >> choice;

        switch (choice) {
            case 1:
                list.create();
                break;
            case 2:
                cout << "Enter the element: ";
                cin >> element;
                list.addAtBeginning(element);
                break;
            case 3:
                cout << "Enter the data: ";
                cin >> element;
                list.addAtEnd(element);
                break;
            case 4:
                cout << "Enter data value: ";
                cin >> element; 
                cout << "Enter Position: ";
                cin >> position;
                list.addAtPosition(position, element);
                break;
            case 5:
                list.deleteAtBeginning();
                cout << "\nDeleted Successfully!\n" << endl;
                break;
            case 6:
                list.deleteAtEnd();
                cout << "\nDeleted Successfully!\n" << endl;
                break;
            case 7:
                cout << "\nEnter Position: ";
                cin >> position;
                list.deleteAtPosition(position);
                cout << "\nDeleted Successfully!\n" << endl;
                break;
            case 8:
                cout << "\nSize of List is: " << list.count() << endl;
                break;
            case 9:
                cout << "\n\nList: ";
                list.display();
                break;
            case 10:
                exit(0);
                break;
            default:
                cout << "\nInvalid Choice!" << endl;
                break;
        }
    }
    return 0;
}

// A unique C cryptographic hash function example program

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

// Define a struct for storing the hash function state
typedef struct {
    uint64_t a;
    uint64_t b;
    uint64_t c;
    uint64_t d;
} hash_state_t;

// Define the hash function
void hash(const char* input, hash_state_t* state) {
    uint64_t a = state->a;
    uint64_t b = state->b;
    uint64_t c = state->c;
    uint64_t d = state->d;

    for (int i = 0; i < strlen(input); i++) {
        a = (a + input[i]) % 256;
        b = (b + a) % 256;
        c = (c + b) % 256;
        d = (d + c) % 256;
    }

    state->a = a;
    state->b = b;
    state->c = c;
    state->d = d;
}

// Define a function to print the hash value
void print_hash(hash_state_t* state) {
    printf("%llx %llx %llx %llx\n", state->a, state->b, state->c, state->d);
}

int main() {
    // Initialize the hash state
    hash_state_t state = { 0, 0, 0, 0 };

    // Hash some input
    char* input = "Hello, World!";
    hash(input, &state);

    // Print the hash value
    print_hash(&state);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MIN_X 0
#define MAX_X 10
#define MIN_Y 0
#define MAX_Y 10

#define SURVIVAL_RATE 0.5
#define HUNGER_RATE 0.2
#define THIRST_RATE 0.3

struct player {
    int x;
    int y;
    int health;
    int hunger;
    int thirst;
};

void update_player(struct player *player) {
    int hunger_change = player->hunger * HUNGER_RATE;
    int thirst_change = player->thirst * THIRST_RATE;

    player->hunger += hunger_change;
    player->thirst += thirst_change;

    if (player->hunger < 0) {
        player->hunger = 0;
    }

    if (player->thirst < 0) {
        player->thirst = 0;
    }

    player->health -= player->hunger * 0.1;
    player->health -= player->thirst * 0.1;
}

void render_game(struct player *player) {
    printf("---------------------------------\n");
    printf("Statistics Survival Game\n");
    printf("---------------------------------\n");
    printf("Health: %d\n", player->health);
    printf("Hunger: %d\n", player->hunger);
    printf("Thirst: %d\n", player->thirst);
    printf("X: %d\n", player->x);
    printf("Y: %d\n", player->y);
    printf("\n");
}

void handle_input(struct player *player, char input) {
    switch (input) {
        case 'w':
            player->y--;
            break;
        case 's':
            player->y++;
            break;
        case 'a':
            player->x--;
            break;
        case 'd':
            player->x++;
            break;
        case 'q':
            exit(0);
            break;
    }
}

int main() {
    srand(time(NULL));

    struct player player;
    player.x = (rand() % (MAX_X - MIN_X)) + MIN_X;
    player.y = (rand() % (MAX_Y - MIN_Y)) + MIN_Y;
    player.health = 100;
    player.hunger = 50;
    player.thirst = 50;

    while (1) {
        update_player(&player);
        render_game(&player);

        char input = getchar();
        handle_input(&player, input);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

typedef struct {
    int x, y;
} Point;

int main() {
    Point pacman = {0, 0};
    Point ghost[4] = {{1, 2}, {2, 3}, {3, 4}, {4, 5}};

    srand(time(NULL));

    while (1) {
        printf("--------------------------------------\n");
        printf("-    Pac-Man: %d,%d\n", pacman.x, pacman.y);
        printf("-    Ghost:  %d,%d %d,%d %d,%d %d,%d\n", ghost[0].x, ghost[0].y, ghost[1].x, ghost[1].y, ghost[2].x, ghost[2].y, ghost[3].x, ghost[3].y);

        int move = 0;
        int x, y;
        do {
            printf("Choose a move: ");
            printf("(1) Up\n");
            printf("(2) Down\n");
            printf("(3) Left\n");
            printf("(4) Right\n");
            printf("(0) Quit\n");
            scanf("%d", &move);
        } while (move!= 0 && move!= 1 && move!= 2 && move!= 3 && move!= 4);

        switch (move) {
            case 0:
                break;
            case 1:
                y = pacman.y + 1;
                break;
            case 2:
                y = pacman.y - 1;
                break;
            case 3:
                x = pacman.x - 1;
                break;
            case 4:
                x = pacman.x + 1;
                break;
        }

        if (x == -1 || x == 10 || y == -1 || y == 10) {
            printf("Game Over!\n");
            break;
        }

        pacman.x = x;
        pacman.y = y;

        if (pacman.x == ghost[0].x && pacman.y == ghost[0].y ||
            pacman.x == ghost[1].x && pacman.y == ghost[1].y ||
            pacman.x == ghost[2].x && pacman.y == ghost[2].y ||
            pacman.x == ghost[3].x && pacman.y == ghost[3].y) {
            printf("You lose!\n");
            break;
        }

        for (int i = 0; i < 4; i++) {
            int x = ghost[i].x + 1;
            int y = ghost[i].y + 1;
            if (x == 10 || y == 10) {
                ghost[i].x = rand() % 10 + 1;
                ghost[i].y = rand() % 10 + 1;
            } else if (x == pacman.x && y == pacman.y) {
                printf("You win!\n");
                break;
            }
        }
    }

    return 0;
}

