#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX 10

int main()
{

    int x, y, n, i, j, found = 0;
    char **maze = (char **)malloc(MAX * sizeof(char *));
    for (i = 0; i < MAX; i++)
    {
        maze[i] = (char *)malloc(MAX * sizeof(char));
    }

    // Build the maze
    maze[0][0] = 'S';
    maze[0][1] = '+';
    maze[1][0] = '+';
    maze[1][1] = '+';
    maze[1][2] = '+';
    maze[2][1] = '+';
    maze[2][2] = '+';
    maze[2][3] = 'T';

    // Search for the treasure
    x = 0;
    y = 0;
    n = 0;
    while (!found)
    {
        // Move in a random direction
        i = rand() % 4;
        switch (i)
        {
            case 0:
                y++;
                break;
            case 1:
                x++;
                break;
            case 2:
                y--;
                break;
            case 3:
                x--;
                break;
        }

        // Check if the cell is the treasure
        if (maze[x][y] == 'T')
        {
            found = 1;
        }
        else
        {
            // Mark the cell as visited
            maze[x][y] = '*';
        }

        // Increment the number of steps
        n++;
    }

    // Print the number of steps it took to find the treasure
    printf("The number of steps it took to find the treasure is: %d", n);

    return 0;
}

