#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CLIENT_CONNECTIONS 10
#define BUFFER_SIZE 1024

int main(int argc, char *argv[]) {
  int sock_fd, client_fd;
  struct sockaddr_in server, client;
  socklen_t client_len = sizeof(client);
  char buffer[BUFFER_SIZE];
  int num_clients = 0;

  // Create a server socket
  sock_fd = socket(AF_INET, SOCK_STREAM, 0);
  if (sock_fd == -1) {
    perror("socket creation failed");
    exit(EXIT_FAILURE);
  }

  // Set address and port number for the server
  server.sin_family = AF_INET;
  server.sin_addr.s_addr = INADDR_ANY;
  server.sin_port = htons(8080);

  // Bind the server socket to the address and port
  if (bind(sock_fd, (struct sockaddr *)&server, sizeof(server)) < 0) {
    perror("binding failed");
    exit(EXIT_FAILURE);
  }

  // Listen for incoming connections
  if (listen(sock_fd, MAX_CLIENT_CONNECTIONS) < 0) {
    perror("listening failed");
    exit(EXIT_FAILURE);
  }

  printf("Server listening on port %d...\n", server.sin_port);

  while (1) {
    // Accept an incoming connection
    if ((client_fd = accept(sock_fd, (struct sockaddr *)&client, &client_len)) < 0) {
      perror("accept failed");
      continue;
    }

    // Print the client address and port
    printf("Client connected from %s port %d...\n",
           inet_ntoa(client.sin_addr), ntohs(client.sin_port));

    // Read data from the client
    read(client_fd, buffer, BUFFER_SIZE);
    printf("Received message from client: %s\n", buffer);

    // Send a response back to the client
    char *message = "Hello, client!";
    send(client_fd, message, strlen(message), 0);

    // Close the client socket
    close(client_fd);

    num_clients++;
    if (num_clients >= MAX_CLIENT_CONNECTIONS) {
      break;
    }
  }

  // Close the server socket
  close(sock_fd);

  return 0;
}

