class Checker{
    private:
        string tester;
        string compilerExecutable;
        string cwd;
        std::string get_cwd(){
            // returns current working directory
            char temp[1000];
            return ( getcwd(temp, sizeof(temp)) ? std::string( temp ) : std::string("") );
        }
    public:

        explicit Checker(string test) {
            tester = move(test);
            cwd = get_cwd();
            compilerExecutable = "g++";
        }

        Compilation compile(){
            std::string command = compilerExecutable + " " + cwd + "/" + tester + " -o " + cwd + "/test";
            int compilationState = system(command.c_str());
            return (compilationState)? Compilation::FAILED : Compilation::SUCCESS ;
        }

        Test test(){
            std::string command = "./test";
            int returnValue = system(command.c_str());
            system("rm ./test"); // remove the test binary after testing
            return (returnValue == 0)? Test::SUCCESS : Test::FAILED; 

        }

};

#include <stdio.h>

int main() {
    printf("Peaceful C Pattern Printing Example Program\n\n");

    int rows;

    printf("Enter the number of rows: ");
    scanf("%d", &rows);

    printf("\n");

    for(int i=0; i<rows; i++) {
        for(int j=0; j<i; j++) {
            printf(" ");
        }
        for(int j=0; j<rows-i; j++) {
            printf("* ");
        }
        printf("\n");
    }

    printf("\n");

    for(int i=0; i<rows; i++) {
        for(int j=0; j<rows-i-1; j++) {
            printf("  ");
        }
        for(int j=0; j<2*i+1; j++) {
            printf("* ");
        }
        printf("\n");
    }

    printf("\n");

    for(int i=0; i<rows; i++) {
        for(int j=0; j<i; j++) {
            printf(" ");
        }
        for(int j=0; j<rows-i; j++) {
            printf("* ");
        }
        printf("\n");
    }
    for(int i=0; i<rows; i++) {
        for(int j=rows-i-1; j>0; j--) {
            printf("  ");
        }
        for(int j=0; j<(2*i)+1; j++) {
            printf("* ");
        }
        printf("\n");
    }

    printf("\n");

    for(int i=0; i<=rows/2; i++) {
        for(int j=i; j<rows-i; j++) {
            printf("* ");
        }
        printf("\n");
    }

    for(int i=(rows/2)+1; i<rows; i++) {
        for(int j=0; j<=i; j++) {
            printf("  ");
        }
        for(int j=i; j<rows; j++) {
            printf("* ");
        }
        printf("\n");
    }

    return 0;
}

