// Represents a human with a name and age
class Human {
private:
    int age;
    string name;

public:
    // Default constructor initializes with default values
    Human() {
        cout << "default constructor" << endl;
        age = 20;
        name = "anil";
    }

    // Constructor that initializes with a given name
    Human(string inputName) {
        cout << "constructor with name" << endl;
        age = 20;
        name = inputName;
    }

    // Constructor that initializes with a given age
    Human(int inputAge) {
        cout << "constructor with age" << endl;
        age = inputAge;
