#include "cpu_info.h"  // NOLINT

#include <unistd.h>

#include <cerrno>
#include <climits>
#include <cstdio>
#include <cstdlib>
#include <cstring>

namespace gav1_jni {
namespace {

// Note: The code in this file needs to use the 'long' type because it is the
// return type of the Standard C Library function strtol(). The linter warnings
// are suppressed with NOLINT comments since they are integers at runtime.

// Returns the number of online processor cores.
int GetNumberOfProcessorsOnline() {
  // See https://developer.android.com/ndk/guides/cpu-features.
  long num_cpus = sysconf(_SC_NPROCESSORS_ONLN);  // NOLINT
  if (num_cpus < 0) {
    return 0;
  }
  // It is safe to cast num_cpus to int. sysconf(_SC_NPROCESSORS_ONLN) returns
  // the return value of get_nprocs(), which is an int.
  return static_cast<int>(num_cpus);
}

}  // namespace

// These CPUs support heterogeneous multiprocessing.
#if defined(__arm__) || defined(__aarch64__)

// A helper function used by GetNumberOfPerformanceCoresOnline().
//
// Returns the cpuinfo_max_freq value (in kHz) of the given CPU. Returns 0 on
// failure.
long GetCpuinfoMaxFreq(int cpu_index) {  // NOLINT
  char buffer[128];
  const int rv = snprintf(
      buffer, sizeof(buffer),
      "/sys/devices/system/cpu/cpu%d/cpufreq/cpuinfo_max_freq", cpu_index);
  if (rv < 0 || rv >= sizeof(buffer)) {
    return 0;
  }
  FILE* file = fopen(buffer, "r");
  if (file == nullptr) {
    return 0;
  }
  char* const str = fgets(buffer, sizeof(buffer), file);
  fclose(file);
  if (str == nullptr) {
    return 0;
  }
  const long freq = strtol(str, nullptr, 10);  // NOLINT
  if (freq <= 0 || freq == LONG_MAX) {
    return 0;
  }
  return freq;
}

// Returns the number of performance CPU cores that are online. The number of
// efficiency CPU cores is subtracted from the total number of CPU cores. Uses
// cpuinfo_max_freq to determine whether a CPU is a performance core or an
// efficiency core.
//
// This function is not perfect. For example, the Snapdragon 632 SoC used in
// Motorola Moto G7 has performance and efficiency cores with the same
// cpuinfo_max_freq but different cpuinfo_min_freq. This function fails to
// differentiate the two kinds of cores and reports all the cores as
// performance cores.
int GetNumberOfPerformanceCoresOnline() {
  // Get the online CPU list. Some examples of the online CPU list are:
  //   "0-7"
  //   "0"
  //   "0-1,2,3,4-7"
  FILE* file = fopen("/sys/devices/system/cpu/online", "r");
  if (file == nullptr) {
    return 0;
  }
  char online[512];
  char* const str = fgets(online, sizeof(online), file);
  fclose(file);
  file = nullptr;
  if (str == nullptr) {
    return 0;
  }

  // Count the number of the slowest CPUs. Some SoCs such as Snapdragon 855
  // have performance cores with different max frequencies, so only the slowest
  // CPUs are efficiency cores. If we count the number of the fastest CPUs, we
  // will fail to count the second fastest performance cores.
  long slowest_cpu_freq = LONG_MAX;  // NOLINT
  int num_slowest_cpus = 0;
  int num_cpus = 0;
  const char* cp = online;
  int range_begin = -1;
  while (true) {
    char* str_end;
    const int cpu = static_cast<int>(strtol(cp, &str_end, 10));  // NOLINT
    if (str_end == cp) {
      break;
    }
    cp = str_end;
    if (*cp == '-') {
      range_begin = cpu;
    } else {
      if (range_begin == -1) {
        range_begin = cpu;
      }

      num_cpus += cpu - range_begin + 1;
      for (int i = range_begin; i <= cpu; ++i) {
        const long freq = GetCpuinfoMaxFreq(i);  // NOLINT
        if (freq <= 0) {
          return 0;
        }
        if (freq < slowest_cpu_freq) {
          slowest_cpu_freq = freq;
          num_slowest_cpus = 0;
        }
        if (freq == slowest_cpu_freq) {
          ++num_slowest_cpus;
        }
      }

      range_begin = -1;
    }
    if (*cp == '\0') {
      break;
    }
    ++cp;
  }

  // If there are faster CPU cores than the slowest CPU cores, exclude the
  // slowest CPU cores.
  if (num_slowest_cpus < num_cpus) {
    num_cpus -= num_slowest_cpus;
  }
  return num_cpus;
}

#else

// Assume symmetric multiprocessing.
int GetNumberOfPerformanceCoresOnline() {
  return GetNumberOfProcessorsOnline();
}

#endif

}  // namespace gav1_jni

#ifndef BENNYSBANK_ACCOUNT_H
#define BENNYSBANK_ACCOUNT_H

#include <string>
#include "LinkedTransactionList.h"

using namespace std;

/**
 * Represents a bank account with checking and savings balances, along with transaction history.
 */
class Account {
private:
    int accountId;
    string firstName;
    string lastName;
    double checkingBalance;
    double savingsBalance;
    LinkedTransactionList *checkingTransactionHistory;
    LinkedTransactionList *savingsTransactionHistory;

public:
    /**
     * Constructs an Account instance with specified details.
     * @param id Unique identifier for the account.
     * @param fName First name of the account holder.
     * @param lName Last name of the account holder.
     * @param cBal Initial checking balance.
     * @param sBal Initial savings balance.
     */
    Account(int id, string fName, string lName, double cBal, double sBal) 
        : accountId(id), firstName(fName), lastName(lName), 
          checkingBalance(cBal), savingsBalance(sBal) {
        checkingTransactionHistory = new LinkedTransactionList();
        savingsTransactionHistory = new LinkedTransactionList();
    }

    /**
     * Destructor to release allocated memory for transaction histories.
     */
    ~Account() {
        delete checkingTransactionHistory;
        delete savingsTransactionHistory;
    }

    /**
     * Compares two accounts based on their total balance for sorting purposes.
     * @param other The account to compare against.
     * @return True if this account has a lesser total balance than the other account.
     */
    bool operator< (const Account &other) const {
        return (checkingBalance + savingsBalance) < (other.checkingBalance + other.savingsBalance);
    }

    /**
     * Retrieves the transaction history for the checking account.
     * @return Pointer to the LinkedTransactionList for checking transactions.
     */
    LinkedTransactionList *getCheckingTransactions() const {
        return checkingTransactionHistory;
    }

    /**
     * Retrieves the transaction history for the savings account.
     * @return Pointer to the LinkedTransactionList for savings transactions.
     */
    LinkedTransactionList *getSavingsTransactions() const {
        return savingsTransactionHistory;
    }

    /**
     * Retrieves the unique identifier of the account.
     * @return The account ID.
     */
    int getId() const {
        return accountId;
    }

    /**
     * Retrieves the first name of the account holder.
     * @return The first name.
     */
    const string &getFirstName() const {
        return firstName;
    }

    /**
     * Updates the first name of the account holder.
     * @param fName The new first name.
     */
    void setFirstName(const string &fName) {
        firstName = fName;
    }

    /**
     * Retrieves the last name of the account holder.
     * @return The last name.
     */
    const string &getLastName() const {
        return lastName;
    }

    /**
     * Updates the last name of the account holder.
     * @param lName The new last name.
     */
    void setLastName(const string &lName) {
        lastName = lName;
    }

    /**
     * Retrieves the current checking account balance.
     * @return The checking balance.
     */
    double getCheckingBalance() const {
        return checkingBalance;
    }

    /**
     * Updates the current checking account balance.
     * @param cBal The new checking balance.
     */
    void setCheckingBalance(double cBal) {
        checkingBalance = cBal;
    }

    /**
     * Retrieves the current savings account balance.
     * @return The savings balance.
     */
    double getSavingsBalance() const {
        return savingsBalance;
    }

    /**
     * Updates the current savings account balance.
     * @param sBal The new savings balance.
     */
    void setSavingsBalance(double sBal) {
        savingsBalance = sBal;
    }
};

#endif //BENNYSBANK_ACCOUNT_H

#include <pcap/pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

// The main function is the entry point of the program.
int main() {
  // Define the network interface to capture packets from.
  char *device = "wlan0";
  // Define the filter expression to capture only TCP packets.
  char *filter = "tcp";
  // Define the number of packets to capture.
  int num_packets = 10;

  // Open the network interface for packet capture.
  pcap_t *handle = pcap_open_live(device, BUFSIZ, 1, 1000, NULL);
  if (handle == NULL) {
    fprintf(stderr, "Unable to open the network interface for packet capture.\n");
    return -1;
  }

  // Compile the filter expression.
  struct bpf_program fp;
  if (pcap_compile(handle, &fp, filter, 0, PCAP_NETMASK_UNKNOWN) == -1) {
    fprintf(stderr, "Unable to compile the filter expression.\n");
    return -1;
  }

  // Set the filter on the network interface.
  if (pcap_setfilter(handle, &fp) == -1) {
    fprintf(stderr, "Unable to set the filter on the network interface.\n");
    return -1;
  }

  // Create a packet buffer to store the captured packets.
  u_char *buffer = (u_char *)malloc(BUFSIZ);
  if (buffer == NULL) {
    fprintf(stderr, "Unable to allocate memory for the packet buffer.\n");
    return -1;
  }

  // Capture packets until the specified number of packets is reached.
  int count = 0;
  while (count < num_packets) {
    // Wait for a packet to arrive.
    struct pcap_pkthdr *header;
    const u_char *data;
    int res = pcap_next_ex(handle, &header, &data);
    if (res == -1) {
      fprintf(stderr, "Unable to capture a packet.\n");
      return -1;
    } else if (res == 0) {
      continue;
    }

    // Print the packet header.
    printf("Packet number: %d\n", count + 1);
    printf("Packet length: %d bytes\n", header->len);
    printf("Capture time: %s\n", ctime((const time_t *)&header->ts.tv_sec));

    // Print the packet data.
    for (int i = 0; i < header->len; i++) {
      printf("%02x ", data[i]);
      if ((i + 1) % 16 == 0) {
        printf("\n");
      }
    }

    printf("\n");

    count++;
  }

  // Free the packet buffer.
  free(buffer);

  // Close the network interface.
  pcap_close(handle);

  return 0;
}

