// Swaps the values of two variables of any type
template<typename T>
void swapValues(T& first, T& second)
{
	T temporary = first;
	first = second;
	second = temporary;
}

// Tests the swap function with character variables
void testSwap()
{
	char grade = 'a';
	char universal = 'b';
	swapValues(grade, universal);
	cout << "grade: " << grade << " universal: " << universal << endl;
}

// Reverses the elements of an array in place
template<typename T>
void reverseArray(T *array, int length)
{
	for (int index = 0; index < length / 2; index++)
	{
		swapValues(array[index], array[length - index - 1]);
	}
}

// Tests the reverse function with an integer array
void testReverse()
{
	int array[] = { 1, 2, 3, 4, 5, 6 };
	reverseArray(array, 6);
	for (int index = 0; index < 6; index++)
	{
		cout << array[index] << " ";
	}
}

// A generic pair class that holds a key-value pair
template <typename KeyType, typename ValueType>
class Pair
{
	KeyType key;
	ValueType value;

public:
	Pair(KeyType, ValueType);
	KeyType getKey();
	ValueType getValue();
	template <typename K, typename V>
	friend ostream& operator<<(ostream&, Pair<K, V> const&);
};

// Constructor for the Pair class
template <typename KeyType, typename ValueType>
Pair<KeyType, ValueType>::Pair(KeyType inputKey, ValueType inputValue)
{
	key = inputKey;
	value = inputValue;
}

// Returns the key of the pair
template <typename KeyType, typename ValueType>
KeyType Pair<KeyType, ValueType>::getKey()
{
	return key;
}

// Returns the value of the pair
template <typename KeyType, typename ValueType>
ValueType Pair<KeyType, ValueType>::getValue()
{
	return value;
}

// Overloads the output stream operator for the Pair class
template <typename KeyType, typename ValueType>
ostream& operator<<(ostream& os, Pair<KeyType, ValueType> const& pair)
{
	os << "(" << pair.key << ", " << pair.value << ")" << endl;
	return os;
}

