}

// Base class for shapes with common properties
class Shape 
{
protected:
	int width, height;

public:
	Shape(int widthValue = 0, int heightValue = 0) 
	{
		width = widthValue;
		height = heightValue;
	}

	// Calculates the area of the shape (to be overridden)
	virtual int area() 
	{
		cout << "Parent class area :" << endl;
		return 0;
	}
};

// Rectangle class that inherits from Shape
class Rectangle : public Shape 
{
public:
	Rectangle(int widthValue = 0, int heightValue = 0) : Shape(widthValue, heightValue) { }

	// Calculates the area of the rectangle
	int area() 
	{
		cout << "Rectangle class area :" << endl;
		return (width * height);
	}
};

// Triangle class that inherits from Shape
class Triangle : public Shape {
public:
	Triangle(int widthValue = 0, int heightValue = 0) : Shape(widthValue, heightValue) { }

	// Calculates the area of the triangle
	int area() 
	{
		cout << "Triangle class area :" << endl;
		return (width * height / 2);
	}
};

