    npc(npc(npc(buffer)->append(u"    .format_runs       = "_j))->append(npc(_formats)->length))->append(u"\n"_j);
    for (auto i = int32_t(0); i < npc(_formats)->length; i++) {
        auto ctf = (*_formats)[i];
