class Book {
public:
    // Retrieve various attributes of the book
    string GetName() const { return title; }
    string GetIsbn() const { return isbn; }
    string GetAuthor() const { return author; }
    int GetNumberOfCopies() const { return copiesAvailable; }
    int GetCategory() const { return category; }
    double GetPrice() const { return price; }
    double GetDiscountRate() const { return discountRate; }
    int GetMinimumDiscountQuantity() const { return minimumDiscountQuantity; }
    string GetDescription() const { return description; }

    // Update various attributes of the book
    void SetName(const string& newTitle) { title = newTitle; }
    void SetIsbn(const string& newIsbn) { isbn = newIsbn; }
    void SetAuthor(const string& newAuthor) { author = newAuthor; }
    void SetNumberOfCopies(int newCopies) { copiesAvailable = newCopies; }
    void SetCategory(int newCategory) { category = newCategory; }
    void SetPrice(double newPrice) { price = newPrice; }
    void SetDiscountRate(double newDiscountRate) { discountRate = newDiscountRate; }
    void SetMinimumDiscountQuantity(int newMinDiscountQuantity) { minimumDiscountQuantity = newMinDiscountQuantity; }
    void SetDescription(const string& newDescription) { description = newDescription; }

    // Calculate the total price for purchasing a specified number of books
    double CalculateNetPrice(int quantity) const {
        // Apply discount if quantity exceeds the minimum required for discount
        if (quantity > minimumDiscountQuantity) {
            return static_cast<double>(quantity) * price * discountRate;
        } else {
            return static_cast<double>(quantity) * price;
        }
    }

private:
    string title; // Title of the book
    string isbn; // ISBN number
    string author; // Author of the book
    int copiesAvailable; // Number of copies available
    int category; // Category identifier
    double price; // Price per unit of the book
    double discountRate; // Discount rate applicable for bulk purchases
    int minimumDiscountQuantity; // Minimum quantity to qualify for discount
    string description; // Additional information about the book
};

