    cin >> productNumber;
    fileStream.open("Shop.dat", ios::in | ios::out);
    while (fileStream.read((char*)&productInstance, sizeof(Product)) && foundFlag == 0) {
        if (productInstance.getProductNumber() == productNumber) {
            productInstance.showProduct();
            cout << "\nPlease Enter The New Details of Product" << endl;
            productInstance.createProduct();
            int position = -1 * sizeof(productInstance);
            fileStream.seekp(position, ios::cur);
            fileStream.write((char*)&productInstance, sizeof(Product));
            cout << "\n\n\t Record Updated";
            foundFlag = 1;
        }
    }
    fileStream.close();
    if (foundFlag == 0) {
        cout << "\n\n Record Not Found ";
    }
    getch();
}

// Function to delete a product record
void deleteProduct() {
    int productNumber;
    clrscr();
    cout << "\n\n\n\tDelete Record";
    cout << "\n\nPlease Enter The Product No. of The Product You Want To Delete: ";
    cin >> productNumber;
    fileStream.open("Shop.dat", ios::in | ios::out);
    fstream tempFile;
    tempFile.open("Temp.dat", ios::out);
    fileStream.seekg(0, ios::beg);
    while (fileStream.read((char*)&productInstance, sizeof(Product))) {
        if (productInstance.getProductNumber() != productNumber) {
            tempFile.write((char*)&productInstance, sizeof(Product));
        }
    }
    tempFile.close();
    fileStream.close();
    remove("Shop.dat");
    rename("Temp.dat", "Shop.dat");
    cout << "\n\n\tRecord Deleted ..";
    getch();
}

