    while (file.read(reinterpret_cast<char*>(&account), sizeof(Account)) && !found) {
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();
            if (option == 1) {
                std::cout << "\n\n\tTO DEPOSIT AMOUNT ";
                std::cout << "\n\nEnter The amount to be deposited: ";
                std::cin >> amount;
                account.deposit(amount);
            }
            if (option == 2) {
                std::cout << "\n\n\tTO WITHDRAW AMOUNT ";
                std::cout << "\n\nEnter Withdrawal Amount: ";
                std::cin >> amount;
                account.withdraw(amount);
            }
            int pos = (-1) * sizeof(account);
            file.seekp(pos, std::ios::cur);
            file.write(reinterpret_cast<char*>(&account), sizeof(Account));
            std::cout << "\nRecord Updated..\nPress Enter to continue.";
            found = true;
        }
    }
    file.close();
    if (!found) {
        std::cout << "\nRecord Not Found ";
    }
}

void transferFunds(int fromAccountNumber, int toAccountNumber) {
    float amount;
    float fee = 0.0;
    bool found = false;
    bool withdrawalSuccessful = false;
    Account fromAccount;
    Account toAccount;
    short fromAccountType;
    std::fstream file("Account.dat", std::ios::binary | std::ios::in | std::ios::out);
    if (!file) {
        std::cout << "\nFile could not be opened! Press any key...";
        return;
    }
    while (file.read(reinterpret_cast<char*>(&fromAccount), sizeof(Account)) && !found) {
        if (fromAccount.getAccountNumber() == fromAccountNumber) {
            fromAccount.displayAccount();
            std::cout << "\n\n\tTO WITHDRAW AMOUNT ";
            std::cout << "\n\nEnter Withdrawal Amount: ";
            std::cin >> amount;

            float balance = fromAccount.getBalance() - amount;
            if ((balance < 0.0 && fromAccount.getAccountType() != 2)) {
                std::cout << "Insufficient balance";
            } else {
                fromAccountType = fromAccount.getAccountType();
                fromAccount.withdraw(amount);
                int pos = (-1) * sizeof(fromAccount);
                file.seekp(pos, std::ios::cur);
                file.write(reinterpret_cast<char*>(&fromAccount), sizeof(Account));
                withdrawalSuccessful = true;
            }
            found = true;
        }
    }
    if (withdrawalSuccessful) {
        found = false;
        file.close();
        std::cout << "\nHold a second!";
        file.open("Account.dat", std::ios::binary | std::ios::in | std::ios::out);
        while (file.read(reinterpret_cast<char*>(&toAccount), sizeof(Account)) && !found) {
            if (toAccount.getAccountNumber() == toAccountNumber) {
                toAccount.displayAccount();

                if (fromAccountType == 3) {
                    if (toAccount.getOwnerClass() == 1) {
                        fee = amount * 0.02;
                    } else if (toAccount.getOwnerClass() == 2) {
                        fee = amount * 0.01;
                    } else {
                        fee = 0.0;
                    }
                }
                std::cout << "\nThe Deposited Amount is: " << amount - fee;
                std::cout << "\nPress Enter to continue";
                std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
                toAccount.deposit(amount - fee);

                int pos = (-1) * sizeof(toAccount);
                file.seekp(pos, std::ios::cur);
                file.write(reinterpret_cast<char*>(&toAccount), sizeof(Account));

                std::cout << "\nRecord Updated..\nPress Enter to continue.";
                found = true;
            }
        }
    }

    if (!found) {
        std::cout << "\nRecord Not Found ";
    }

    file.close();
}

