    double maxContractSalary = contractEmployees[0].CalculateContractSalary();

    for (int i = 1; i < permanentCount; ++i)
    {
        maxPermanentSalary = max(maxPermanentSalary, permanentEmployees[i].CalculateBaseSalary());
    }

    for (int i = 1; i < contractCount; ++i)
    {
        maxContractSalary = max(maxContractSalary, contractEmployees[i].CalculateContractSalary());
    }

    cout << "\n=================== NHAN VIEN BIEN CHE CO LUONG CAO NHAT ====================\n";
    DisplayPermanentEmployeeHeader();
    for (int i = 0; i < permanentCount; ++i)
    {
        if (permanentEmployees[i].CalculateBaseSalary() == maxPermanentSalary)
        {
            permanentEmployees[i].Output();
        }
    }

    cout << "\n=================== NHAN VIEN HOP DONG CO LUONG CAO NHAT ====================\n";
    DisplayContractEmployeeHeader();
    for (int i = 0; i < contractCount; ++i)
    {
        if (contractEmployees[i].CalculateContractSalary() == maxContractSalary)
        {
            contractEmployees[i].Output();
        }
    }
}

int main(int argc, char const *argv[])
{
    PermanentEmployee *permanentEmployees;
    ContractEmployee *contractEmployees;
    int permanentCount = 0, contractCount = 0;

    cout << "# Nhap vao so nhan vien Bien Che: ";
    cin >> permanentCount;
    permanentEmployees = new PermanentEmployee[permanentCount];

    cout << "# Nhap vao so nhan vien Hop Dong: ";
    cin >> contractCount;
    contractEmployees = new ContractEmployee[contractCount];

    InputEmployees(permanentEmployees, contractEmployees, permanentCount, contractCount);
    DisplayEmployees(permanentEmployees, contractEmployees, permanentCount, contractCount);
    DisplayMaxSalary(permanentEmployees, contractEmployees, permanentCount, contractCount);

    delete[] permanentEmployees;
    delete[] contractEmployees;

    return 0;
}

