#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#define BOARD_SIZE 9
#define BLOCK_SIZE 3

typedef struct {
    int board[BOARD_SIZE][BOARD_SIZE];
    int p_x, p_y;
} SudokuBoard;

bool is_valid(int board[BOARD_SIZE][BOARD_SIZE], int num, int row, int col) {
    for (int i = 0; i < BOARD_SIZE; i++) {
        if (board[row][i] == num) return false;
        if (board[i][col] == num) return false;
    }

    int box_x = col / BLOCK_SIZE;
    int box_y = row / BLOCK_SIZE;

    for (int i = box_y * BLOCK_SIZE; i < box_y * BLOCK_SIZE + BLOCK_SIZE; i++) {
        for (int j = box_x * BLOCK_SIZE; j < box_x * BLOCK_SIZE + BLOCK_SIZE; j++) {
            if (board[i][j] == num) return false;
        }
    }

    return true;
}

bool solve_sudoku(SudokuBoard *board, int num, int row, int col) {
    if (num > BOARD_SIZE * BOARD_SIZE) return true;

    int back_num = board->board[row][col];
    if (back_num != 0 && back_num != num) return false;

    if (back_num == 0) {
        board->board[row][col] = num;

        for (int i = 0; i < BOARD_SIZE; i++) {
            if (solve_sudoku(board, num + 1, row, i)) return true;
            if (solve_sudoku(board, num + 1, i, col)) return true;
        }

        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board->board[i][j] == 0 && is_valid(board->board, num, i, j)) {
                    board->p_x = i;
                    board->p_y = j;
                    break;
                }
            }
            if (board->p_x >= 0 && board->p_y >= 0) break;
        }

        board->board[row][col] = back_num;
    }

    return false;
}

void print_sudoku(SudokuBoard *board) {
    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (j > 0) printf(" | ");
            printf("%d ", board->board[i][j]);
        }
        if (i < BOARD_SIZE - 1) printf("\n---+---+---\n");
    }
}

int main() {
    SudokuBoard board;
    int num = 0;

    for (int i = 0; i < BOARD_SIZE; i++) {
        for (int j = 0; j < BOARD_SIZE; j++) {
            board.board[i][j] = rand() % 10 + 1;
            if (board.board[i][j] == 0) {
                num++;
                board.p_x = i;
                board.p_y = j;
            }
        }
    }

    printf("Initial board:\n");
    print_sudoku(&board);

    if (solve_sudoku(&board, num + 1, 0, 0)) {
        printf("\nSolved board:\n");
        print_sudoku(&board);
    } else {
        printf("Error: could not solve the board.\n");
    }

    return 0;
}

