    string author;
    string content;

    Book(const string& title, const string& author, const string& content);
};

class Student {
public:
    string name;
    string major;
    int age;
    int studentNumber;

    Student(const string& name, int age, int studentNumber, const string& major);

    void greet(const Student& otherStudent) const {
        cout << "Hi " << otherStudent.name << ", my name is " << this->name << ". Nice to meet you!" << endl;
    }

    void read(const Book& book) const {
        cout << book.title << " written by " << book.author << ". " << endl << "Contents: " << book.content << endl;
    }

