    {'#', '#', '#', '#', '#', '#', '#', '#', '#', '#'}
};

// The player's position
int player_x = 1;
int player_y = 1;

// The goal's position
int goal_x = 8;
int goal_y = 8;

// The main function
int main() {

    // Print the map
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            printf("%c", map[i][j]);
        }
        printf("\n");
    }

    // Start the pathfinding algorithm
    while (player_x != goal_x || player_y != goal_y) {

        // Check if the player is at the goal
        if (player_x == goal_x && player_y == goal_y) {
            break;
        }

        // Check if the player can move north
        if (map[player_y - 1][player_x] == '.') {
            player_y--;
        }

        // Check if the player can move east
        else if (map[player_y][player_x + 1] == '.') {
            player_x++;
        }

        // Check if the player can move south
        else if (map[player_y + 1][player_x] == '.') {
            player_y++;
        }

        // Check if the player can move west
        else if (map[player_y][player_x - 1] == '.') {
            player_x--;
        }

        // If the player can't move, then print an error message
        else {
            printf("The player is stuck!\n");
            break;
        }

        // Print the map
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                if (player_x == j && player_y == i) {
                    printf("P");
                } else {
                    printf("%c", map[i][j]);
                }
            }
            printf("\n");
        }
    }

    // If the player reached the goal, then print a message
    if (player_x == goal_x && player_y == goal_y) {
        printf("The player reached the goal!\n");
    }

    return 0;
}

