#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define POP3_PORT 110

int main(int argc, char **argv) {
    if (argc != 2) {
        printf("Usage: %s <email_address>\n", argv[0]);
        return 1;
    }

    char *email_address = argv[1];

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(POP3_PORT);
    server_addr.sin_addr.s_addr = inet_addr("127.0.0.1");

    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket()");
        return 1;
    }

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect()");
        return 1;
    }

    char *request = "USER\n";
    if (send(sock, request, strlen(request), 0) < 0) {
        perror("send()");
        return 1;
    }

    char response[1024];
    if (recv(sock, response, sizeof(response), 0) < 0) {
        perror("recv()");
        return 1;
    }

    if (strncmp(response, "+OK", 3) != 0) {
        printf("Invalid response: %s\n", response);
        return 1;
    }

    request = "PASS\n";
    if (send(sock, request, strlen(request), 0) < 0) {
        perror("send()");
        return 1;
    }

    if (recv(sock, response, sizeof(response), 0) < 0) {
        perror("recv()");
        return 1;
    }

    if (strncmp(response, "+OK", 3) != 0) {
        printf("Invalid response: %s\n", response);
        return 1;
    }

    request = "STAT\n";
    if (send(sock, request, strlen(request), 0) < 0) {
        perror("send()");
        return 1;
    }

    if (recv(sock, response, sizeof(response), 0) < 0) {
        perror("recv()");
        return 1;
    }

    if (strncmp(response, "+OK", 3) != 0) {
        printf("Invalid response: %s\n", response);
        return 1;
    }

    char *token = strtok(response, " ");
    if (token == NULL) {
        printf("Invalid response: %s\n", response);
        return 1;
    }

    int num_messages = atoi(token);
    printf("Number of messages: %d\n", num_messages);

    for (int i = 0; i < num_messages; i++) {
        request = "RETR\n";
        if (send(sock, request, strlen(request), 0) < 0) {
            perror("send()");
            return 1;
        }

        if (recv(sock, response, sizeof(response), 0) < 0) {
            perror("recv()");
            return 1;
        }

        if (strncmp(response, "+OK", 3) != 0) {
            printf("Invalid response: %s\n", response);
            return 1;
        }

        char *message = strtok(response, "\r\n");
        while (message != NULL) {
            printf("%s\n", message);
            message = strtok(NULL, "\r\n");
        }
    }

    request = "QUIT\n";
    if (send(sock, request, strlen(request), 0) < 0) {
        perror("send()");
        return 1;
    }

    if (recv(sock, response, sizeof(response), 0) < 0) {
        perror("recv()");
        return 1;
    }

    if (strncmp(response, "+OK", 3) != 0) {
        printf("Invalid response: %s\n", response);
        return 1;
    }

    close(sock);
    return 0;
}

