#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Vehicle struct
typedef struct {
    int x;
    int y;
    int speed;
    int direction;
} Vehicle;

// Function to initialize vehicle
void initVehicle(Vehicle* v) {
    v->x = rand() % 20 + 1; // Randomly place vehicle on x-axis
    v->y = rand() % 10 + 1; // Randomly place vehicle on y-axis
    v->speed = 0; // Initially, the vehicle is not moving
    v->direction = 0; // Initially, the vehicle is facing upwards
}

// Function to move vehicle
void moveVehicle(Vehicle* v) {
    int dx = 0;
    int dy = 0;

    if (v->direction == 0) { // If the vehicle is facing upwards
        dy = v->speed; // Move the vehicle upwards
    }
    else if (v->direction == 1) { // If the vehicle is facing downwards
        dy = -v->speed; // Move the vehicle downwards
    }
    else if (v->direction == 2) { // If the vehicle is facing left
        dx = -v->speed; // Move the vehicle left
    }
    else if (v->direction == 3) { // If the vehicle is facing right
        dx = v->speed; // Move the vehicle right
    }

    v->x += dx; // Update x-coordinate
    v->y += dy; // Update y-coordinate
}

// Function to display vehicle
void displayVehicle(Vehicle* v) {
    printf("Vehicle at (%d,%d) facing %d\n", v->x, v->y, v->direction);
}

// Function to change direction of vehicle
void changeDirection(Vehicle* v) {
    v->direction = (v->direction + 1) % 4; // Change direction by 90 degrees
}

// Main function
int main() {
    srand(time(NULL)); // Seed the random number generator with current time

    Vehicle vehicle;
    initVehicle(&vehicle); // Initialize vehicle

    while (1) {
        moveVehicle(&vehicle); // Move the vehicle
        displayVehicle(&vehicle); // Display the vehicle
        changeDirection(&vehicle); // Change direction of the vehicle
    }

    return 0;
}

#ifndef QUEUE_H
#define QUEUE_H

#include "CLL.h"

/**
 * Represents a queue data structure.
 * @tparam T The type of the data stored in the queue.
 */
template<typename T>
class Queue {
private:
    CLL<T> circularLinkedList;

public:
    Queue();
    int getSize() const;
    bool isEmpty() const;
    const T front() const;
    void enqueue(const T item);
    void dequeue();
    void moveForward();
};

/**
 * Initializes an empty queue.
 * @tparam T The type of the data stored in the queue.
 */
template<typename T>
Queue<T>::Queue() {}

/**
 * Retrieves the number of elements in the queue.
 * @tparam T The type of the data stored in the queue.
 * @return The count of elements in the queue.
 */
template<typename T>
int Queue<T>::getSize() const {
    return circularLinkedList.getSize();
}

/**
 * Checks if the queue is empty.
 * @tparam T The type of the data stored in the queue.
 * @return True if the queue is empty, otherwise false.
 */
template<typename T>
bool Queue<T>::isEmpty() const {
    return circularLinkedList.isEmpty();
}

/**
 * Accesses the item at the front of the queue.
 * @tparam T The type of the data stored in the queue.
 * @return A reference to the item at the front of the queue.
 */
template<typename T>
const T Queue<T>::front() const {
    return circularLinkedList.getFirst();
}

/**
 * Adds an element to the rear of the queue.
 * @tparam T The type of the data stored in the queue.
 */
template<typename T>
void Queue<T>::enqueue(const T item) {
    circularLinkedList.addLast(item);
}

/**
 * Removes the front element from the queue.
 * @tparam T The type of the data stored in the queue.
 */
template<typename T>
void Queue<T>::dequeue() {
    circularLinkedList.removeFirst();
}

/**
 * Advances to the next node in the circular linked list.
 * @tparam T The type of the data stored in the queue.
 */
template<typename T>
void Queue<T>::moveForward() {
    circularLinkedList.moveForward();
}

