// TestValues.cpp : Test XML encoding and decoding of XmlRpcValues.

#include <stdlib.h>

#include "XmlRpcValue.h"


#include <assert.h>
#include <iostream>


using namespace XmlRpc;


void testBoolean()
{
  XmlRpcValue booleanFalse(false);
  XmlRpcValue booleanTrue(true);
  int offset = 0;
  XmlRpcValue booleanFalseXml("<value><boolean>0</boolean></value>", &offset);
  offset = 0;
  XmlRpcValue booleanTrueXml("<value><boolean>1</boolean></value>", &offset);
  assert(booleanFalse != booleanTrue);
  assert(booleanFalse == booleanFalseXml);
  assert(booleanFalse != booleanTrueXml);

  if (bool(booleanFalse))
    assert(false);

  if ( ! bool(booleanTrue))
    assert(false);
}

// Int
void testInt()
{
  XmlRpcValue int0(0);
  XmlRpcValue int1(1);
  XmlRpcValue int10(10);
  XmlRpcValue int_1(-1);
  int offset = 0;
  XmlRpcValue int0Xml("<value><int>0</int></value>", &offset);
  offset = 0;
  XmlRpcValue int9Xml("<value><i4>9</i4></value>", &offset);
  assert(int0 == int0Xml);
  assert(int(int10) - int(int1) == int(int9Xml));
  assert(9 == int(int9Xml));
  assert(int(int10) + int(int_1) == int(int9Xml));
}

void testDouble()
{
  // Double
  XmlRpcValue d(43.7);
  int offset = 0;
  XmlRpcValue dXml("<value><double>56.3</double></value>", &offset);
  assert(double(d) + double(dXml) == 100.0);  // questionable practice...
}

void testString()
{
  // String
  XmlRpcValue s("Now is the time <&");
  char csxml[] = "<value><string>Now is the time &lt;&amp;</string></value>";
  std::string ssxml = csxml;
  int offset = 0;
  XmlRpcValue vscXml(csxml, &offset);
  offset = 0;
  XmlRpcValue vssXml(ssxml, &offset);
  assert(s == vscXml);
  assert(s == vssXml);
  offset = 0;
  XmlRpcValue fromXml(vssXml.toXml(), &offset);
  assert(s == fromXml);

  // Empty or blank strings with no <string> tags
  std::string emptyStringXml("<value></value>");
  offset = 0;
  XmlRpcValue emptyStringVal1(emptyStringXml, &offset);
  XmlRpcValue emptyStringVal2("");
  assert(emptyStringVal1 == emptyStringVal2);

  emptyStringXml = "<value>  </value>";
  offset = 0;
  XmlRpcValue blankStringVal(emptyStringXml, &offset);
  assert(std::string(blankStringVal) == "  ");
}


void testDateTime()
{
  // DateTime
  int offset = 0;
  XmlRpcValue dateTime("<value><dateTime.iso8601>19040101T03:12:35</dateTime.iso8601></value>", &offset);
  struct tm &t = dateTime;
  assert(t.tm_year == 1904 && t.tm_min == 12);
}


void testArray(XmlRpcValue const& d)
{
  // Array
  XmlRpcValue a;
  a.setSize(4);
  a[0] = 1;
  a[1] = std::string("two");
  a[2] = 43.7;
  a[3] = "four";
  assert(int(a[0]) == 1);
  assert(a[2] == d);

  char csaXml[] =
    "<value><array>\n"
    "  <data>\n"
    "    <value><i4>1</i4></value> \n"
    "    <value> <string>two</string></value>\n"
    "    <value><double>43.7</double></value>\n"
    "    <value>four</value>\n"
    "  </data>\n"
    "</array></value>";

  int offset = 0;
  XmlRpcValue aXml(csaXml, &offset);
  assert(a == aXml);
}

void testStruct()
{
  // Struct
  XmlRpcValue struct1;
  struct1["i4"] = 1;
  struct1["str"] = "two";
  struct1["d"] = 43.7;

  XmlRpcValue a;
  a.setSize(4);
  a[0] = 1;
  a[1] = std::string("two");
  a[2] = 43.7;
  a[3] = "four";

  assert(struct1["d"] == a[2]);

  char csStructXml[] =
    "<value><struct>\n"
    "  <member>\n"
    "    <name>i4</name> \n"
    "    <value><i4>1</i4></value> \n"
    "  </member>\n"
    "  <member>\n"
    "    <name>d</name> \n"
    "    <value><double>43.7</double></value>\n"
    "  </member>\n"
    "  <member>\n"
    "    <name>str</name> \n"
    "    <value> <string>two</string></value>\n"
    "  </member>\n"
    "</struct></value>";

  int offset = 0;
  XmlRpcValue structXml(csStructXml, &offset);
  assert(struct1 == structXml);

  XmlRpcValue astruct;
  astruct["array"] = a;
  assert(astruct["array"][2] == struct1["d"]);

  for (int i=0; i<10; i++) {
    XmlRpcValue Event;
    Event["Name"] = "string";

    Event.clear();

    const int NELMTS = 100;
    int ii;

    for (ii=0; ii< NELMTS; ++ii) {
      char buf[40];
      sprintf(buf,"%d", ii);
      Event[std::string(buf)] = buf;
    }

    Event.clear();

    for (ii=0; ii< NELMTS; ++ii) {
      char buf[40];
      sprintf(buf,"%d", ii);
      if (ii != NELMTS/2)
        Event[std::string(buf)] = ii;
      else
        for (int jj=0; jj< NELMTS; ++jj) {
          char bufj[40];
          sprintf(bufj,"%d", jj);
          Event[std::string(buf)][std::string(bufj)] = bufj;
        }
    }

    for (ii=0; ii< NELMTS; ++ii) {
      char buf[40];
      sprintf(buf,"%d", ii);
      if (ii != NELMTS/2)
        assert(Event[std::string(buf)] == XmlRpcValue(ii));
      else
        assert(Event[std::string(buf)].size() == NELMTS);
    }
  }
}



int main(int argc, char* argv[])
{
  testBoolean();

  testInt();


  testDouble();


  testString();


  testDateTime();


  testArray(43.7);


  testStruct();

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
   int id;
   char name[50];
   char email[50];
} Person;

Person* create_person(int id, char* name, char* email) {
    Person* person = malloc(sizeof(Person));
    person->id = id;
    strcpy(person->name, name);
    strcpy(person->email, email);
    return person;
}

void print_person(Person* person) {
    printf("ID: %d\n", person->id);
    printf("Name: %s\n", person->name);
    printf("Email: %s\n", person->email);
}

typedef struct {
    char* key;
    int value;
} Index;

Index* create_index(char* key, int value) {
    Index* index = malloc(sizeof(Index));
    index->key = malloc(strlen(key)+1);
    strcpy(index->key, key);
    index->value = value;
    return index;
}

void print_index(Index* index) {
    printf("Key: %s\n", index->key);
    printf("Value: %d\n", index->value);
}

typedef struct {
    Person** data;
    int size;
    Index** indexes;
    int num_indexes;
} Database;

Database* create_database(int size) {
    Database* db = malloc(sizeof(Database));
    db->data = malloc(sizeof(Person*) * size);
    db->size = size;
    db->indexes = malloc(sizeof(Index*) * size);
    db->num_indexes = 0;
    return db;
}

void insert_person(Database* db, Person* person) {
    if(db->num_indexes > 0) {
        for(int i = 0; i < db->num_indexes; i++) {
            Index* index = db->indexes[i];
            if(strcmp(index->key, person->email) == 0) {
                printf("Error: Email already exists.\n");
                return;
            }
        }
    }
    for(int i = 0; i < db->size; i++) {
        if(db->data[i] == NULL) {
            db->data[i] = person;
            return;
        }
    }
    printf("Error: Database is full.\n");
}

void create_index_for_database(Database* db, char* key) {
    if(db->num_indexes == db->size) {
        printf("Error: Maximum number of indexes exceeded.\n");
        return;
    }
    for(int i = 0; i < db->num_indexes; i++) {
        Index* index = db->indexes[i];
        if(strcmp(index->key, key) == 0) {
            printf("Error: Index already exists.\n");
            return;
        }
    }
    Index* index = create_index(key, db->num_indexes);
    db->indexes[db->num_indexes] = index;
    db->num_indexes++;
    for(int i = 0; i < db->size; i++) {
        if(db->data[i] != NULL) {
            if(strcmp(key, "id") == 0) {
                index->value = db->data[i]->id;
            } else if(strcmp(key, "name") == 0) {
                strcpy(index->key, db->data[i]->name);
            } else if(strcmp(key, "email") == 0) {
                strcpy(index->key, db->data[i]->email);
            }
        }
    }
}

Database* load_database(char* filename) {
    FILE* fp = fopen(filename, "r");
    if(fp == NULL) {
        printf("Error: File not found.\n");
        return NULL;
    }
    int size;
    fscanf(fp, "%d", &size);
    Database* db = create_database(size);
    for(int i = 0; i < size; i++) {
        int id;
        char name[50];
        char email[50];
        fscanf(fp, "%d,%[^,],%s\n", &id, name, email);
        Person* person = create_person(id, name, email);
        insert_person(db, person);
    }
    fclose(fp);
    return db;
}

void save_database(Database* db, char* filename) {
    FILE* fp = fopen(filename, "w");
    if(fp == NULL) {
        printf("Error: Could not create file.\n");
        return;
    }
    fprintf(fp, "%d\n", db->size);
    for(int i = 0; i < db->size; i++) {
        if(db->data[i] != NULL) {
            fprintf(fp, "%d,%s,%s\n", db->data[i]->id, db->data[i]->name, db->data[i]->email);
        }
    }
    fclose(fp);
}

void search_database_for(Database* db, char* key, char* value) {
    int found = 0;
    for(int i = 0; i < db->size; i++) {
        if(db->data[i] != NULL) {
            if(strcmp(key, "id") == 0) {
                if(db->data[i]->id == atoi(value)) {
