// Class representing a hero with various attributes and abilities
class Hero {
    char name[101];
    int health;
    unsigned level;
    unsigned experience;
    int strength;
    int speed;
    int intellect;

public:
    // Default constructor initializes a hero with default values
    Hero() {
        strcpy(name, "");
        health = 10;
        level = 1;
        experience = 0;
        strength = 0;
        speed = 0;
        intellect = 0;
    }

    // Parameterized constructor for creating a hero with specific attributes
    Hero(char* _name, int _health, unsigned _level, unsigned _experience,
         int _strength, int _speed, int _intellect) {
        strcpy(name, _name);
        health = _health;
        level = _level;
        experience = _experience;
        strength = _strength;
        speed = _speed;
        intellect = _intellect;
    }

    // Copy constructor for creating a hero from another hero instance
    Hero(Hero const& h) {
        strcpy(name, h.name);
        health = h.health;
        level = h.level;
        experience = h.experience;
        strength = h.strength;
        speed = h.speed;
        intellect = h.intellect;
    }

    // Additional methods for Hero class would go here (e.g., print, setName, setLevel)
};

void testHero() {
    Hero defaultHero; // Create a hero using the default constructor
    defaultHero.print();

    Hero namedHero("Gandalf", 990, 99, 9899, 10, 1, 256); // Create a hero with specific attributes
    namedHero.print();

    Hero copiedHero(namedHero); // Create a copy of the named hero
    copiedHero.setName("Saruman");
    copiedHero.print();

    copiedHero.setLevel(98); // Update the level of the copied hero
}

// Function to test dynamic array allocation and average calculation
void testDynamic1() {
    int size;
    cout << "Enter size: ";
    cin >> size;

    double* arr = new double[size]; // Allocate memory for the array
    double avg = 0;

    for (int i = 0; i < size; i++) {
        cin >> arr[i]; // Input values into the array
        avg += arr[i]; // Calculate the sum for average
    }

    cout << avg / size << endl; // Output the average
    delete[] arr; // Free allocated memory
}

// Function to test dynamic matrix allocation and transposition
void testDynamic2() {
    int size;
    cout << "Enter size: ";
    cin >> size;

    double** matrix = new double*[size]; // Allocate memory for the matrix
    for (int i = 0; i < size; i++) {
        matrix[i] = new double[size]; // Allocate memory for each row
        for (int j = 0; j < size; j++) {
            cin >> matrix[i][j]; // Input values into the matrix
        }
    }

    // Transpose the matrix
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            double tmp = matrix[j][i];
            matrix[j][i] = matrix[i][j];
            matrix[i][j] = tmp;
        }
    }

    // Output the transposed matrix
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            cout << matrix[i][j] << ' ';
        }
        cout << endl;
    }

    // Free allocated memory for the matrix
    for (int i = 0; i < size; i++) {
        delete[] matrix[i];
    }
    delete[] matrix;
}

