 * This program simulates a GPS navigation system that uses
 * mathematical algorithms to calculate the shortest distance
 * between two points on the Earth's surface.
 *
 * Author: [Your Name]
 * Date: [Date]
 */

#include <stdio.h>
#include <math.h>

#define RADIUS_EARTH 6371.0 // radius of the Earth in kilometers

// Structure to represent a point on the Earth's surface
typedef struct {
    double lat; // latitude in degrees
    double lon; // longitude in degrees
} Point;

// Function to calculate the distance between two points on the Earth's surface
double calculate_distance(Point p1, Point p2) {
    // Convert lat and lon to radians
    double lat1 = p1.lat * (M_PI / 180);
    double lat2 = p2.lat * (M_PI / 180);
    double lon1 = p1.lon * (M_PI / 180);
    double lon2 = p2.lon * (M_PI / 180);

    // Calculate the distance using the Haversine formula
    double dlat = lat2 - lat1;
    double dlon = lon2 - lon1;
    double a = sin(dlat / 2) * sin(dlat / 2) +
              cos(lat1) * cos(lat2) *
              sin(dlon / 2) * sin(dlon / 2);
    double c = 2 * atan2(sqrt(a), sqrt(1 - a));
    return RADIUS_EARTH * c;
}

// Main function
int main() {
    // Define two points on the Earth's surface
    Point p1 = {40.7128, -74.0060}; // New York City
    Point p2 = {34.0522, -118.2437}; // Los Angeles

    // Calculate the distance between the two points
    double distance = calculate_distance(p1, p2);

    // Print the distance
    printf("The distance between New York City and Los Angeles is %.2f km\n", distance);

    return 0;
}

