#define MAX_FORTUNE 100
#define MAX_LENGTH 80

// structure to hold each fortune
typedef struct {
    char text[MAX_LENGTH];
    int length;
} fortune;

// function prototypes
void load_fortunes(fortune *fortunes);
int pick_random_fortune(fortune *fortunes, int num_fortunes);

int main(int argc, char *argv[]) {
    fortune fortunes[MAX_FORTUNE];
    load_fortunes(fortunes);

    int num_fortunes = sizeof(fortunes) / sizeof(fortunes[0]);
    int choice;

    printf("Welcome to the Automated Fortune Teller!\n");
    printf("Inspired by Romeo and Juliet.\n");
    printf("How many fortunes would you like to hear? ");
    scanf("%d", &choice);

    if (choice < 1 || choice > num_fortunes) {
        printf("Invalid choice.\n");
        return 1;
    }

    for (int i = 0; i < choice; i++) {
        int index = pick_random_fortune(fortunes, num_fortunes);
        printf("\nFortune #%d:\n%s\n", i+1, fortunes[index].text);
    }

    return 0;
}

// load fortunes from a file
void load_fortunes(fortune *fortunes) {
    FILE *fp;
    char line[MAX_LENGTH];
    int count = 0;

    fp = fopen("fortunes.txt", "r");
    if (fp == NULL) {
        printf("Error opening fortunes file.\n");
        exit(1);
    }

    while (fgets(line, MAX_LENGTH, fp)!= NULL) {
        if (count >= MAX_FORTUNE) {
            printf("Too many fortunes in file.\n");
            exit(1);
        }
        strcpy(fortunes[count].text, line);
        fortunes[count].length = strlen(line);
        count++;
    }

    fclose(fp);
}

// pick a random fortune from the array
int pick_random_fortune(fortune *fortunes, int num_fortunes) {
    return rand() % num_fortunes;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

struct node
{
    int x, y, f, g, h;
    bool traversable;
    struct node *parent;
};

typedef struct node node_t;

int **create_map(int rows, int cols)
{
    int **map = (int **)malloc(rows * sizeof(int *));
    for (int i = 0; i < rows; i++)
        map[i] = (int *)malloc(cols * sizeof(int));

    // initialize map with random values
    for (int i = 0; i < rows; i++)
        for (int j = 0; j < cols; j++)
            map[i][j] = rand() % 2;

    return map;
}

void free_map(int **map, int rows)
{
    for (int i = 0; i < rows; i++)
        free(map[i]);
    free(map);
}

// euclidean distance heuristic
int heuristic(node_t *node, node_t *goal)
{
    int x_dist = abs(node->x - goal->x);
    int y_dist = abs(node->y - goal->y);
    return x_dist + y_dist;
}

node_t *create_node(int x, int y, bool traversable)
{
    node_t *node = (node_t *)malloc(sizeof(node_t));
    node->x = x;
    node->y = y;
    node->f = 0;
    node->g = 0;
    node->h = 0;
    node->traversable = traversable;
    node->parent = NULL;
    return node;
}

void free_node(node_t *node)
{
    free(node);
}

node_t *get_lowest_f_node(node_t **open_set, int open_set_size)
{
    int lowest_f = open_set[0]->f;
    int lowest_f_index = 0;

    for (int i = 1; i < open_set_size; i++)
    {
        if (open_set[i]->f < lowest_f)
        {
            lowest_f = open_set[i]->f;
            lowest_f_index = i;
        }
    }

    return open_set[lowest_f_index];
}

bool is_in_closed_set(node_t *node, node_t **closed_set, int closed_set_size)
{
    for (int i = 0; i < closed_set_size; i++)
    {
        if (node->x == closed_set[i]->x && node->y == closed_set[i]->y)
        {
            return true;
        }
    }

    return false;
}

bool is_in_open_set(node_t *node, node_t **open_set, int open_set_size)
{
    for (int i = 0; i < open_set_size; i++)
    {
        if (node->x == open_set[i]->x && node->y == open_set[i]->y)
        {
            return true;
        }
    }

    return false;
}

node_t **get_neighbours(node_t *node, int **map, int rows, int cols)
{
    static node_t *neighbours[8];

    int index = 0;

    for (int i = -1; i <= 1; i++)
    {
        for (int j = -1; j <= 1; j++)
        {
            if (i == 0 && j == 0)
                continue;

            int x = node->x + i;
            int y = node->y + j;

            if (x < 0 || x >= rows || y < 0 || y >= cols)
                continue;

            if (!map[x][y])
                continue;

            neighbours[index++] = create_node(x, y, true);
        }
    }

    return neighbours;
}

void reconstruct_path(node_t *current)
{
    node_t *p = current;
    while (p->parent)
    {
        printf("(%d,%d) -> ", p->x, p->y);
        p = p->parent;
    }
    printf("(%d,%d)\n", p->x, p->y);
}

node_t *a_star_search(int **map, int rows, int cols, node_t *start, node_t *goal)
{
    node_t *open_set[rows * cols];
    int open_set_size = 0;

    node_t *closed_set[rows * cols];
    int closed_set_size = 0;

    open_set[open_set_size++] = start;

    while (open_set_size > 0)
    {
        node_t *current = get_lowest_f_node(open_set, open_set_size);
        if (current->x == goal->x && current->y == goal->y)
        {
            return current;
        }

        open_set_size--;
        for (int i = 0; i < open_set_size; i++)
        {
            if (open_set[i] == current)
            {
                open_set[i] = open_set[open_set_size];
                break;
            }
        }

        closed_set[closed_set_size++] = current;

        node_t **neighbours = get_neighbours(current, map, rows, cols);
        int neighbours_size = sizeof(neighbours) / sizeof(node_t *);

        for (int i = 0; i < neighbours_size; i++)
        {
            node_t *neighbour = neighbours[i];

            if (is_in_closed_set(neighbour, closed_set, closed_set_size))
            {
                free_node(neighbour);
                continue;
            }

            int tentative_g_score = current->g + 1;

            if (!is_in_open_set(neighbour, open_set, open_set_size))
            {
                open_set[open_set_size++] = neighbour;
                neighbour->h = heuristic(neighbour, goal);
            }
            else if (tentative_g_score >= neighbour->g)
            {
                free_node(neighbour);
                continue;
            }

            neighbour->parent = current;
            neighbour->g = tentative_g_score;
            neighbour->f = neighbour->g + neighbour->h;
        }
    }

    return NULL;
}

int main()
{
    int rows = 10;
    int cols = 10;

    int **map = create_map(rows, cols);

    node_t *start = create_node(0, 0, true);
    node_t *goal = create_node(rows - 1, cols - 1, true);

    node_t *path = a_star_search(map, rows, cols, start, goal);

    if (path == NULL)
    {
        printf("No path found.\n");
    }
    else
    {
        printf("Path found:\n");
        reconstruct_path(path);
    }

    free_map(map, rows);
    free_node(start);
    free_node(goal);
    free_node(path);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define ALPHABET_SIZE 26
#define KEY_SIZE 16

typedef struct {
    char *plain_text;
    char *cipher_text;
    char *key;
} message;

void generate_key(char *key) {
    for (int i = 0; i < KEY_SIZE; i++) {
        key[i] = 'a' + rand() % ALPHABET_SIZE;
    }
    key[KEY_SIZE] = '\0';
}

int is_uppercase(char c) {
    return (c >= 'A' && c <= 'Z');
}

int is_lowercase(char c) {
    return (c >= 'a' && c <= 'z');
}

void shift_letter(char *letter, int shift) {
    if (is_uppercase(*letter)) {
        *letter = 'A' + ((*letter - 'A') + shift) % ALPHABET_SIZE;
    } else if (is_lowercase(*letter)) {
        *letter = 'a' + ((*letter - 'a') + shift) % ALPHABET_SIZE;
    }
}

void encrypt(char *plain_text, char *key) {
    int plain_text_length = strlen(plain_text);
    char *cipher_text = malloc(plain_text_length + 1);

    for (int i = 0; i < plain_text_length; i++) {
        if (is_uppercase(plain_text[i])) {
            shift_letter(&plain_text[i], (key[i % KEY_SIZE] - 'a') % ALPHABET_SIZE);
        } else if (is_lowercase(plain_text[i])) {
            shift_letter(&plain_text[i], (key[i % KEY_SIZE] - 'a') % ALPHABET_SIZE);
        }
    }

    strcpy(cipher_text, plain_text);
}

void decrypt(char *cipher_text, char *key) {
    int cipher_text_length = strlen(cipher_text);
    char *plain_text = malloc(cipher_text_length + 1);

    for (int i = 0; i < cipher_text_length; i++) {
        if (is_uppercase(cipher_text[i])) {
            shift_letter(&cipher_text[i], (26 - (key[i % KEY_SIZE] - 'a') % ALPHABET_SIZE));
        } else if (is_lowercase(cipher_text[i])) {
            shift_letter(&cipher_text[i], (26 - (key[i % KEY_SIZE] - 'a') % ALPHABET_SIZE));
        }
    }

    strcpy(plain_text, cipher_text);
}

int main() {
    message message;

    printf("Enter plain text: ");
    scanf("%s", message.plain_text);

    generate_key(message.key);

    printf("Enter key: ");
    scanf("%s", message.key);

    encrypt(message.plain_text, message.key);

    printf("Cipher text: %s\n", message.cipher_text);

    decrypt(message.cipher_text, message.key);

    printf("Plain text: %s\n", message.plain_text);

    return 0;
}

