#include <stdio.h>
#include <stdlib.h>

#define MAX 10

void initialize_board(int **board, int size)
{
    board = (int *)malloc(size * sizeof(int *));
    for (int i = 0; i < size; i++)
    {
        board[i] = (int *)malloc(size * sizeof(int));
        for (int j = 0; j < size; j++)
        {
            board[i][j] = 0;
        }
    }
}

void print_board(int **board, int size)
{
    for (int i = 0; i < size; i++)
    {
        for (int j = 0; j < size; j++)
        {
            printf("%d ", board[i][j]);
        }
        printf("\n");
    }
}

int count_alive(int **board, int x, int y)
{
    int alive_neighbors = 0;
    int size = board[0][0];

    // Check the neighbors to the left
    if (x - 1 >= 0)
    {
        alive_neighbors++;
    }

    // Check the neighbors above
    if (y - 1 >= 0)
    {
        alive_neighbors++;
    }

    // Check the neighbors to the right
    if (x + 1 < size)
    {
        alive_neighbors++;
    }

    // Check the neighbors below
    if (y + 1 < size)
    {
        alive_neighbors++;
    }

    return alive_neighbors;
}

void update_board(int **board, int size)
{
    for (int i = 0; i < size; i++)
    {
        for (int j = 0; j < size; j++)
        {
            int alive_neighbors = count_alive(board, i, j);

            if (alive_neighbors < 2)
            {
                board[i][j] = 0;
            }
            else if (alive_neighbors == 2)
            {
                board[i][j] = 1;
            }
            else if (alive_neighbors > 3)
            {
                board[i][j] = 0;
            }
        }
    }
}

int main()
{
    int size = MAX;
    int **board = NULL;

    initialize_board(&board, size);

    // Initial board setup
    board[0][0] = 1;
    board[1][0] = 1;
    board[2][0] = 1;
    board[3][0] = 1;
    board[0][1] = 1;
    board[1][1] = 1;
    board[2][1] = 1;

    print_board(board, size);

    update_board(board, size);

    print_board(board, size);

    return 0;
}

class Gold {

private:



	int numer, denom; //голда ще бъден представен като рационално число



	int gcd(int x, int y) 

	{

		if (x <= 0 || y <= 0) 

		{

			return 1;

		}

		while (x != y)

		{

			if (x > y)

				x -= y;

			else

				y -= x;

		}

		return x;

	}



public:



	Gold()

	{

		numer=1;

		denom=1;

	}	



	Gold(int n, int d) 

	{

		numer=n;

		denom=d;

		if (denom == 0) //не може да имаме знаменател 0

		{

			cout <<"ERROR!";

			denom = 1;

		}	

		if (numer != 0) 

		{

			int g = gcd(numer, denom);

			numer /= g;

			denom /= g;

		}

		else // ако числителя е 0 ще представяме дробта като 0/1

			denom = 1;

	}



	Gold(Gold const& r) 

	{

		numer=r.numer;

		denom=r.denom;

	}



	//гетъри

	int getNumerator() const { return numer; }



	int getDenominator() const { return denom; }



	void print() const 

	{

		cout << getNumerator() << '/' << getDenominator()<<endl;

	}



	//От тук нататък предефинираме почти всички оператори на света...

	const Gold& operator=(const Gold& other) 

	{

		if(this != &other)

		{

			numer = other.numer;

			denom = other.denom;

		}

		return *this;

	}



	Gold operator+(const Gold& q) 

	{

		return Gold(getNumerator() * q.getDenominator()+ getDenominator() * q.getNumerator(),

								getDenominator() * q.getDenominator());

	}



	Gold operator-(const Gold& q) 

	{

		return Gold(getNumerator() * q.getDenominator()- getDenominator() * q.getNumerator(),

						getDenominator() * q.getDenominator());

	}



	Gold operator*(const Gold& q) 

	{

		return Gold(getNumerator() * q.getNumerator(),

						getDenominator() * q.getDenominator());

	}



	Gold operator/(const Gold& q) 

	{

		return Gold(getNumerator() * q.getDenominator(),

						getDenominator() * q.getNumerator());

	}



	operator double() const 

	{

		return (double)numer / (double)denom;

	}



	friend istream& operator>>(istream& in, Gold& gold) 

	{

		in>>gold.numer;

		in>>gold.denom;

		return in;

	}



	friend ostream& operator<<(ostream& out,const Gold& gold)

	{

		out<<gold.numer<<"/"<<gold.denom<<endl;

		return out;

	}



	bool operator==(Gold& rgold) const

	{

		return (numer==rgold.numer && denom==rgold.denom);

	}



	bool operator>(Gold& rgold) const

	{

		Gold helper;

		helper=rgold;

		helper= helper-*this;

		return (helper.numer<0);

	}



	bool operator>=(Gold& rgold) const

	{

		Gold helper;

		helper=rgold;

		helper= helper-*this;

		return (helper.numer<=0);

	}



	bool operator<(Gold& rgold) const

	{

		return (rgold>=*this);

	}



	bool operator<=(Gold& rgold) const

	{

		return (rgold>*this);

	}



	const Gold& operator+=(const Gold& rgold) 

	{	

		*this=*this+rgold;

		return *this;

	}



	const Gold& operator-=(const Gold& rgold) 

	{	

		*this=*this-rgold;

		return *this;

	}



	const Gold& operator*=(const Gold& rgold) 

	{	

		*this=*this*rgold;

		return *this;

	}



	const Gold& operator/=(const Gold& rgold) 

	{	

		*this=*this/rgold;

		return *this;

	}



};

