  Reservation reservation1;
  reservation1.room = &room1;
  reservation1.guest = &guest1;
  reservation1.check_in_date = 20230301;
  reservation1.check_out_date = 20230303;

  add_reservation(&hotel, &reservation1);

  print_hotel(&hotel);

  return 0;
}

