// Cơ sở cho các lớp kế thừa, cung cấp các phương thức in và chào hỏi
class Base
{
public:
    // In thông điệp từ lớp cơ sở
    virtual void print()
    {
        cout << "Base Function\n";
    }

    // Chào hỏi người dùng
    virtual void greet()
    {
        cout << "Good Morning";
    }
};

// Lớp kế thừa từ lớp Base, ghi đè các phương thức
class Derived : public Base
{
public:
    // In thông điệp từ lớp kế thừa
    void print() override
    {
        cout << "Derived Function\n";
    }

    // Ghi đè phương thức greet để thay đổi thông điệp chào hỏi
    void greet() override
