void package::calcprice()
{
	totalprice=0;
	int dur=journey::Duration();
	int meal=food::calcFood();
	totalprice=6000*dur;
	totalprice=totalprice+(dur*meal);
	int activ=activities::calcAct();
	totalprice+=activ;
	int itin=Access::calcAccess();
	totalprice+=itin;
}

