#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#include <openssl/bio.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

#define BUFSIZE 1024

void usage(char *argv[]) {
	fprintf(stderr, "Usage: %s [options] <host> <port> <username> <password>\n", argv[0]);
	fprintf(stderr, "Options:\n");
	fprintf(stderr, "  -v: Be verbose.\n");
	fprintf(stderr, "  -l: Enable TLS/SSL.\n");
	fprintf(stderr, "  -d: Enable debugging output.\n");
	fprintf(stderr, "Example:\n");
	fprintf(stderr, "  %s -l imap.example.com 993 bob password\n", argv[0]);
	exit(EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
	int verbose = 0;
	int tls = 0;
	int debug = 0;
	struct sockaddr_in addr;
	int sockfd;
	SSL_CTX *ssl_ctx = NULL;
	SSL *ssl = NULL;
	char buf[BUFSIZE];
	int n;
	int rc;

	// Parse command-line arguments.
	for (int i = 1; i < argc; i++) {
		if (!strcmp(argv[i], "-v")) {
			verbose = 1;
		} else if (!strcmp(argv[i], "-l")) {
			tls = 1;
		} else if (!strcmp(argv[i], "-d")) {
			debug = 1;
		} else if (i + 4 == argc) {
			addr.sin_family = AF_INET;
			addr.sin_port = htons(atoi(argv[i + 2]));
			if (inet_pton(AF_INET, argv[i + 1], &addr.sin_addr) != 1) {
				fprintf(stderr, "Invalid IP address: %s\n", argv[i + 1]);
				usage(argv);
			}
			i += 3;
		} else {
			usage(argv);
		}
	}

	// Create a socket.
	sockfd = socket(AF_INET, SOCK_STREAM, 0);
	if (sockfd == -1) {
		perror("socket");
		exit(EXIT_FAILURE);
	}

	// Connect to the server.
	if (connect(sockfd, (struct sockaddr *)&addr, sizeof(addr)) == -1) {
		perror("connect");
		exit(EXIT_FAILURE);
	}

	// Initialize the TLS/SSL context.
	if (tls) {
		ssl_ctx = SSL_CTX_new(TLS_client_method());
		if (ssl_ctx == NULL) {
			ERR_print_errors_fp(stderr);
			exit(EXIT_FAILURE);
		}

		// Load the CA certificate.
		if (SSL_CTX_load_verify_locations(ssl_ctx, "ca.crt", NULL) != 1) {
			ERR_print_errors_fp(stderr);
			exit(EXIT_FAILURE);
		}

		// Create the SSL object.
		ssl = SSL_new(ssl_ctx);
		if (ssl == NULL) {
			ERR_print_errors_fp(stderr);
			exit(EXIT_FAILURE);
		}

		// Set the SSL socket.
		SSL_set_fd(ssl, sockfd);

		// Perform the SSL handshake.
		rc = SSL_connect(ssl);
		if (rc != 1) {
			ERR_print_errors_fp(stderr);
			exit(EXIT_FAILURE);
		}
	}

	// Authenticate to the server.
	snprintf(buf, BUFSIZE, "LOGIN %s %s", argv[argc - 2], argv[argc - 1]);
	if (tls) {
		rc = SSL_write(ssl, buf, strlen(buf));
	} else {
		rc = write(sockfd, buf, strlen(buf));
	}
	if (rc == -1) {
		perror("write");
		exit(EXIT_FAILURE);
	}

	// Read the server's response.
	if (tls) {
		rc = SSL_read(ssl, buf, BUFSIZE);
	} else {
		rc = read(sockfd, buf, BUFSIZE);
	}
	if (rc == -1) {
		perror("read");
		exit(EXIT_FAILURE);
	}

	// Print the server's response.
	if (verbose) {
		printf("%s", buf);
	}

	// Close the socket.
	if (tls) {
		SSL_free(ssl);
	}
	close(sockfd);

	return EXIT_SUCCESS;
}

