void FrontDesk::manageFrontDesk() {
    while (true) {
        std::cout << "\n\n\t\t\t\t\t\t...Front Desk Space...\n\n";
        std::cout << "\t\t\t\t\t\tEnter\n\n\t\t\t\t\t\t1. Customer Check\n\n\t\t\t\t\t\t"
                  << "2. Borrow Books\n\n\t\t\t\t\t\t3. List of Borrowed Books"
                  << "\n\n\t\t\t\t\t\t4. Renew Book\n\n\t\t\t\t\t\t5. Return Book\n\n\t\t\t\t\t\t"
                  << "6. Exit\n\n\t\t\t\t\t\tEnter Choice : ";
        char choice;
        std::cin >> choice;

        switch (choice) {
            case '1':
                std::cout << "\n\t\t\t\t\t\tChecking Customer existence";
                currentCustomer = verifyCustomer();
                if (currentCustomer == nullptr) {
                    std::cout << "\n\t\t\t\t\t\tThe Customer doesn't exist. Please Sign Up";
                } else {
                    std::cout << "\n\t\t\t\t\t\tThe Customer exists.";
                    currentCustomer->displayDetails();
                }
                break;
            case '2':
                borrowBook();
                break;
            case '3':
                displayBorrowedBooks();
                break;
            case '4':
                renewBorrowedBook();
                break;
            case '5':
                returnBorrowedBook();
                break;
            case '6':
                return;
            default:
                std::cout << "\n\t\t\t\t\t\tInvalid option!\n";
        }
    }
}

void FrontDesk::borrowBook() {
    currentCustomer = verifyCustomer();
    if (currentCustomer != nullptr) {
        std::cout << "\n\t\t\t\t\t\tSearch by title-(0) or author-(1) ?\n\n\t\t\t\t\t\tEnter choice 0 or 1 : ";
        char searchChoice;
        std::cin >> searchChoice;

        if (searchChoice == '0') {
            char bookTitle[25];
            std::cout << "\n\n\t\t\t\t\t\tEnter name of book to search : ";
            std::cin >> bookTitle;

            for (int i = 0; i < BookCount; ++i) {
                if (strcmp(bookPointer[i]->getTitle(), bookTitle) == 0) {
                    if (bookPointer[i]->availableCopies > 0) {
                        --(bookPointer[i]->availableCopies);
                        bookPointer[i]->displayDetails();

                        time_t currentTime = time(0);
                        struct tm* now = localtime(&currentTime);
                        Date currentDate(now->tm_mday, now->tm_mon + 1, now->tm_year + 1900);
                        currentCustomer->borrowedBooks[currentCustomer->bookCount] = *bookPointer[i];
                        currentCustomer->issueDates[currentCustomer->bookCount] = currentDate;

                        std::cout << "\n\t\t\t\t\t\tEnter Return Date :";
                        Date returnDate;
                        int errorFlag = 1;

