void FrontDesk::returnBorrowedBook() {
    currentCustomer = verifyCustomer();
    if (currentCustomer != nullptr) {
        std::cout << "\n\t\t\t\t\t\tSearch by title-(0) or author-(1) ?\n\n\t\t\t\t\t\tEnter choice 0 or 1 : ";
