                if (strcmp(currentCustomer->borrowedBooks[i].getTitle(), bookTitle) == 0) {
                    std::cout << "\n\n\t\t\t\t\t\tExpected Return date : " << currentCustomer->returnDates[i] << "\n";

                    std::cout << "\n\t\t\t\t\t\tEnter Return Date :";
                    Date actualReturnDate;
                    int errorFlag = 1;

                    while (errorFlag == 1) {
