void FrontDesk::displayBorrowedBooks() {
    currentCustomer = verifyCustomer();
    if (currentCustomer != nullptr) {
        std::cout << "\n\n\t\t\t\t\t\tBorrowed Books are : \n";
        for (int i = 0; i < currentCustomer->bookCount; i++) {
            currentCustomer->borrowedBooks[i].displayDetails();
            std::cout << "\n\t\t\t\t\t\tIssue Date  : " << currentCustomer->issueDates[i] << "\n";
            std::cout << "\n\t\t\t\t\t\tReturn Date : " << currentCustomer->returnDates[i] << "\n";
        }
    } else {
        std::cout << "\n\n\t\t\t\t\t\tInvalid Customer ID";
    }
}

Customer* FrontDesk::verifyCustomer() {
    std::cout << "\n\t\t\t\t\t\tEnter customer ID(int):";
    int tempID;
    char input[10];
    std::cin >> input;
    tempID = 0;
    int length = strlen(input);

    try {
        for (int i = 0; input[i] != '\0'; ++i) {
            if (!isdigit(input[i])) {
                throw "\n\t\t\t\t\t\tInvalid input\n";
            } else {
                tempID = tempID + ((int)(input[i] - '0')) * pow(10, length - i - 1);
            }
        }
        for (int i = 0; i < CustomerCount; i++) {
            if (customerPointer[i]->getID() == tempID) {
                return customerPointer[i];
            }
        }
        return nullptr;
    } catch (const char* msg) {
        std::cout << msg;
    }
}

