#include<iostream>


using namespace std;

class Human {
	public:
	static int scount;//cannot be defined inside a class
	int count=0;
	//constructor
	Human() {
		scount++;
		count++;
		cout<<"Number of static humans"<<" "<<scount<<endl;

	}

	//destructor
	~Human()
	{
		cout<<endl;
		cout<<"There are now "<<scount<<" humans reamining"<<endl;
		scount--;
	}

	static void totalHuman() {
		cout<<"There are "<<scount<< " "<< "people"<<endl;
//		cout<<"There are "<<count<< " "<< "people"<<endl;-Produces Error as static member function can only access, static class variable

	}


};
//static variable needs to be defined outside a class defination

int Human :: scount=0;


int main () {
	//only 1 copy of static variable created and shared amongst all the objects.
	Human anish;
	Human mrinal;
	Human lucky;
	Human vaibhav;
	//4 objects- the constructor is called 4 times and scount(static variable) becomes 4

	Human :: totalHuman(); 
	//can access static variables and methods without using an object of class.
	cout<< Human :: scount; 


return 0;	
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef enum {
    RED,
    YELLOW,
    GREEN
} LightState;

void init_lights(LightState *lights) {
    lights[0] = RED;
    lights[1] = GREEN;
    lights[2] = YELLOW;
}

void toggle_lights(LightState *lights) {
    lights[0] = (lights[0] == RED)? GREEN : RED;
    lights[1] = (lights[1] == GREEN)? RED : GREEN;
    lights[2] = (lights[2] == YELLOW)? GREEN : YELLOW;
}

void wait_for_switch(LightState *lights) {
    while (lights[0]!= RED) {
        printf(".");
        fflush(stdout);
        sleep(1);
    }
}

int main() {
    LightState lights[3];
    init_lights(lights);

    while (1) {
        printf("Switching traffic lights...\n");
        printf("Lights: %d %d %d\n", lights[0], lights[1], lights[2]);
        printf("Press enter to switch the lights.\n");
        getchar();

        toggle_lights(lights);
        wait_for_switch(lights);
        printf("Lights: %d %d %d\n", lights[0], lights[1], lights[2]);
        printf("Press enter to switch the lights.\n");
        getchar();

        toggle_lights(lights);
        wait_for_switch(lights);
        printf("Lights: %d %d %d\n", lights[0], lights[1], lights[2]);
        printf("Press enter to switch the lights.\n");
        getchar();
    }

    return 0;
}

