#define MAX_LEN 1024

// Compression function
void compress(char *input, int len, char *output) {
  int i, j, k;
  uint32_t hash = 0;
  char *ptr = input;

  // Step 1: Hashing
  for (i = 0; i < len; i++) {
    hash ^= (uint32_t)ptr[i] << (i % 4);
  }

  // Step 2: Frequency analysis
  for (i = 0; i < len; i++) {
    hash ^= (uint32_t)ptr[i] << (i % 4);
  }

  // Step 3: Huffman coding
  for (i = 0; i < len; i++) {
    if (hash & 1) {
      output[i] = '1';
    } else {
      output[i] = '0';
    }
    hash >>= 1;
  }
}

// Decompression function
void decompress(char *input, int len, char *output) {
  int i, j, k;
  uint32_t hash = 0;
  char *ptr = input;

  // Step 1: Huffman decoding
  for (i = 0; i < len; i++) {
    if (input[i] == '1') {
      hash ^= (uint32_t)ptr[i] << (i % 4);
    } else {
      hash >>= 1;
    }
  }

  // Step 2: Inverse Huffman decoding
  for (i = 0; i < len; i++) {
    if (hash & 1) {
      output[i] = '1';
    } else {
      output[i] = '0';
    }
    hash >>= 1;
  }

  // Step 3: Inverse frequency analysis
  for (i = 0; i < len; i++) {
    if (output[i] == '1') {
      hash ^= (uint32_t)ptr[i] << (i % 4);
    }
  }

  // Step 4: Inverse hashing
  for (i = 0; i < len; i++) {
    if (hash & 1) {
      output[i] = ptr[i];
    }
    hash >>= 1;
  }
}

int main() {
  char input[] = "Hello World!";
  char output[MAX_LEN];

  compress(input, strlen(input), output);
  printf("Compressed string: %s\n", output);

  decompress(output, strlen(output), input);
  printf("Original string: %s\n", input);

  return 0;
}

