             << "\t\t\t\t\t\t6 - View customers\n"
             << "\t\t\t\t\t\t7 - Add Front desk staff\n"
             << "\t\t\t\t\t\t8 - Exit: ";

        char choice;
        cin >> choice;

        switch (choice) {
            case '1':
                addBooks();
                break;
            case '2':
                addCustomer();
                break;
            case '3':
                viewAllBooks();
                break;
            case '6':
                viewAllCustomers();
                break;
            case '4':
                removeCustomer();
                break;
            case '5':
                removeBook();
                break;
            case '7': {
                char name[10];
                char username[10];
                char password[10];
                char email[10];

                cout << "\n\n\t\t\t\t\t\tEnter name: ";
                cin >> name;
                cout << "\n\t\t\t\t\t\tEnter email-ID: ";
                while (true) {
                    cin >> email;
                    if (isValidEmailAddress(email)) {
                        break;
                    }
                    cout << "\n\t\t\t\t\t\tEnter a valid email-ID: ";
                }
                cout << "\n\t\t\t\t\t\tChoose username: ";
                cin >> username;
                cout << "\n\t\t\t\t\t\tEnter a password: ";
                cin >> password;

                fd[FDcount] = new FDClass(name, email, username, password);
                FDcount++;

                writeFD();
                break;
            }
            case '8':
                return;
            default:
                cout << "\n\n\t\t\t\t\t\tInvalid input\n";
        }
    }
}

void LibraryManager::addBooks() {
    char title[25];
    char author[25];
    char isbn[25];
    float price;
    int numberOfCopies;

    cout << "\n\n\t\t\t\t\t\tEnter title: ";
    cin.ignore();
    cin.getline(title, 25);
    cout << "\n\n\t\t\t\t\t\tEnter author: ";
    cin.getline(author, 25);
    cout << "\n\n\t\t\t\t\t\tEnter ISBN: ";
    cin.getline(isbn, 25);
    cout << "\n\n\t\t\t\t\t\tEnter price: ";
    price = getValidatedIntegerInput();
    cout << "\n\n\t\t\t\t\t\tEnter number of copies: ";
    numberOfCopies = getValidatedIntegerInput();

    book_ptr[Bookct] = new book(title, author, isbn, price, numberOfCopies);
    Bookct++;
    writeRecordsBooks();
}

void LibraryManager::viewAllBooks() {
    for (int i = 0; i < Bookct; i++) {
        book_ptr[i]->PrintBookDetails();
    }
}

void LibraryManager::addCustomer() {
    char name[30];
    char mobile[10];
    char email[30];

    cout << "\n\n\t\t\t\t\t\tEnter your name: ";
    cin.ignore();
    cin.getline(name, 30);
    cout << "\n\t\t\t\t\t\tEnter your email-ID: ";
    while (true) {
        cin >> email;
        if (isValidEmailAddress(email)) {
            break;
        }
        cout << "\n\t\t\t\t\t\tEnter a valid email-ID: ";
    }
    cout << "\n\t\t\t\t\t\tEnter your mobile number: ";
    cin >> mobile;

    customer_ptr[Customerct] = new customerClass(name, email, mobile, previous + 1);
    cout << "\n\n\t\t\t\t\t\tCustomer ID generated: " << previous + 1 << "\n";
    Customerct++;
    previous++;
    writeRecords();
}

void LibraryManager::viewAllCustomers() {
    for (int i = 0; i < Customerct; ++i) {
        customer_ptr[i]->PrintCustomerDetails();
    }
}

void LibraryManager::removeCustomer() {
    int customerId;
    cout << "\n\n\t\t\t\t\t\tEnter ID of customer to remove: ";
    cin >> customerId;
    bool customerFound = false;

    for (int i = 0; i < Customerct; ++i) {
        if (customer_ptr[i]->getid() == customerId) {
            cout << "\n\n\t\t\t\t\t\tCustomer found and deleted\n";
            customerFound = true;
            for (int j = i + 1; j < Customerct; ++j) {
                copyCustomerData(j - 1, j);
            }
            --Customerct;
            break;
        }
    }
    if (customerFound) {
        writeRecords();
    }
}

void LibraryManager::removeBook() {
    char isbn[25];
    cout << "\n\n\t\t\t\t\t\tEnter ISBN of book to remove: ";
    cin >> isbn;
    bool bookFound = false;

    for (int i = 0; i < Bookct; ++i) {
        if (strcmp(book_ptr[i]->getISBN(), isbn) == 0) {
            cout << "\n\n\t\t\t\t\t\tBook found and deleted\n";
            bookFound = true;
            for (int j = i + 1; j < Bookct; ++j) {
                copyBookData(j - 1, j);
            }
            --Bookct;
            break;
        }
    }
    if (bookFound) {
        writeRecordsBooks();
    }
}

