#include <iostream>

using namespace std;

// Class representing marks with internal and external components
class Marks {
public:
    Marks() : internalMarks(0), externalMarks(0) {}

    Marks(int internal, int external) : internalMarks(internal), externalMarks(external) {}

    void display() const;

    // Overloads the + operator to sum two Marks objects
    Marks operator+(const Marks& other) const {
        Marks result; // Temporary object to hold the sum of marks
        result.internalMarks = internalMarks + other.internalMarks;
        result.externalMarks = externalMarks + other.externalMarks;
        return result;
    }

private:
    int internalMarks; // Internal marks
    int externalMarks; // External marks
};

void Marks::display() const {
    cout << "Internal Marks are: " << internalMarks << endl;
    cout << "External Marks are: " << externalMarks << endl;
}

int main() {
    Marks student1(89, 60), student2(15, 55);

    Marks totalMarks = student1 + student2; // Using overloaded + operator

    totalMarks.display();

    return 0;
}

