#include <iostream>

using namespace std;

class Bus;
class Truck;

// Compares the weights of a Bus and a Truck and outputs which is heavier.
void compareWeights(const Bus& bus, const Truck& truck);

class Bus {
private:
    int weight;

public:
    Bus(int weight) : weight(weight) {}

    void displayWeight() const {
        cout << "Bus weight is: " << weight << endl;
    }

    friend void compareWeights(const Bus& bus, const Truck& truck);
};

class Truck {
private:
    int weight;

public:
    Truck(int weight) : weight(weight) {}

    void displayWeight() const {
        cout << "Truck weight is: " << weight << endl;
    }

    friend void compareWeights(const Bus& bus, const Truck& truck);
};

// Compares the weights of the Bus and Truck and determines which is heavier.
void compareWeights(const Bus& bus, const Truck& truck) {
    if (bus.weight > truck.weight) {
        cout << "Bus is heavier." << endl;
    } else {
        cout << "Truck is heavier." << endl;
    }
}

int main() {
    Bus volvo(500);
    volvo.displayWeight();

    Truck tata(1000);
    tata.displayWeight();

    compareWeights(volvo, tata);

    return 0;
}

