#include <iostream>
#include <map>
#include <string>
#include <vector>
#include <algorithm>
#include <cctype>
#include <sstream>

using namespace std;

typedef pair<string, int> FrequencyPair;
typedef pair<string, vector<int>> LeaderList;

// Functor for sorting based on frequency
class FrequencyComparator {
public:
    bool operator()(const FrequencyPair& first, const FrequencyPair& second) {
        return first.second < second.second;
    }
};

int main() {
    int numberOfSentences, topWordCount;

    scanf("%d %d\n", &numberOfSentences, &topWordCount);

    // Maps to store word frequencies and leader-wise frequencies
    map<string, int> wordFrequencyMap;
    map<string, vector<int>> leaderFrequencyMap;

    vector<int> zeroVector(10000);

    // Process each sentence input
    for (int i = 0; i < numberOfSentences; i++) {
        int speakerNumber;
        string spokenSentence;

        scanf("%d", &speakerNumber);
        getline(cin, spokenSentence);

        // Remove punctuation marks from the sentence
        for (int j = 0, length = spokenSentence.size(); j < length; j++) {
            if (ispunct(spokenSentence[j])) {
                spokenSentence.erase(j--, 1);
                length = spokenSentence.size();
            }
        }

        // Convert all characters to lowercase
        transform(spokenSentence.begin(), spokenSentence.end(), spokenSentence.begin(), ::tolower);

        istringstream wordStream(spokenSentence);
        string word;

        FrequencyPair wordFrequency;
        LeaderList wordLeaders;

        while (wordStream >> word) {
            // Update frequency map
            if (wordFrequencyMap.find(word) == wordFrequencyMap.end()) {
                wordFrequency.first = word;
                wordFrequency.second = 1;
                wordFrequencyMap.insert(wordFrequency);
            } else {
                wordFrequencyMap[word]++;
            }

            // Update leader frequency map
            if (leaderFrequencyMap.find(word) == leaderFrequencyMap.end()) {
                wordLeaders.first = word;
                wordLeaders.second = zeroVector;
                leaderFrequencyMap.insert(wordLeaders);
            }
            leaderFrequencyMap[word][speakerNumber]++;
        }
    }

    // Output the top words based on frequency
    for (int d = 0; d < topWordCount; d++) {
        FrequencyComparator comparator;
        string mostFrequentWord;

        // Find the word with the maximum frequency
        auto maxFrequencyElement = max_element(wordFrequencyMap.begin(), wordFrequencyMap.end(), comparator);
        mostFrequentWord = maxFrequencyElement->first;

        vector<int>::iterator leaderFrequencyIterator;
        // Find the leader of the most frequent word
        leaderFrequencyIterator = max_element(leaderFrequencyMap[mostFrequentWord].begin(), leaderFrequencyMap[mostFrequentWord].end());

        int maxLeaderFrequency = *leaderFrequencyIterator;
        int leaderCount = leaderFrequencyMap[mostFrequentWord].size();
        cout << mostFrequentWord;

        // Print leaders with the maximum frequency in descending order
        for (int i = leaderCount; i >= 1; i--) {
            if (leaderFrequencyMap[mostFrequentWord][i] == maxLeaderFrequency) {
                cout << " " << i;
            }
        }
        cout << endl;

        // Reset the frequency to avoid reusing the word in subsequent iterations
        wordFrequencyMap[mostFrequentWord] = 0;
    }
    return 0;
}

#include <iostream>

using namespace std;

class CppArray {
private:
    int elements[10];
    int sizeLimit;
    int tempStorage;

public:
    void inputElements();
    void displayElements();
    void sortElements();
    void displayRange();
    void exchangeElements();
    int getSize();
};

// Collects user input for the array elements and sets the size limit
void CppArray::inputElements() {
    cout << "\nEnter the limit of array: ";
    cin >> sizeLimit;

    cout << "\nEnter the array elements: ";
    for (int index = 0; index < sizeLimit; index++) {
        cout << "\na[" << index << "] = ";
        cin >> elements[index];
    }
}

// Displays the elements of the array
void CppArray::displayElements() {
    cout << "\nThe entered array is: ";
    for (int index = 0; index < sizeLimit; index++) {
        cout << "\na[" << index << "] = " << elements[index];
    }
}

// Sorts the array elements in ascending order using bubble sort
void CppArray::sortElements() {
    for (int outerIndex = 0; outerIndex < sizeLimit; outerIndex++) {
        for (int innerIndex = 0; innerIndex < sizeLimit - 1; innerIndex++) {
            if (elements[innerIndex] > elements[innerIndex + 1]) {
                tempStorage = elements[innerIndex + 1];
                elements[innerIndex + 1] = elements[innerIndex];
                elements[innerIndex] = tempStorage;
            }
        }
    }

    cout << "\nThe sorted array is: ";
    for (int index = 0; index < sizeLimit; index++) {
        cout << "\na[" << index << "] = " << elements[index];
    }
}

// Displays the range of the array elements
void CppArray::displayRange() {
    cout << "\nThe range of array is from " << elements[0] << " to " << elements[sizeLimit - 1];
}

// Copies the elements to a new array and displays it
void CppArray::exchangeElements() {
    int exchangedArray[10];
    for (int index = 0; index < sizeLimit; index++) {
        exchangedArray[index] = elements[index];
    }

    cout << "\nThe exchanged array is: ";
    for (int index = 0; index < sizeLimit; index++) {
        cout << "\nb[" << index << "] = " << exchangedArray[index];
    }
}

// Returns the size of the array
int CppArray::getSize() {
    return sizeLimit;
}

int main() {
    int arraySize;
    CppArray arrayObject;

    arrayObject.inputElements();
    arrayObject.displayElements();
    arrayObject.displayRange();
    arrayObject.exchangeElements();
    arrayObject.sortElements();
    arraySize = arrayObject.getSize();

    cout << "\nThe size of array is: " << arraySize;
    return 0;
}

