// Decentralized C Syntax Parsing Example Program
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Custom struct to store tokens
typedef struct {
    char *token;
    int line;
    int col;
} Token;

// Custom struct to store parsed tokens
typedef struct {
    Token *tokens;
    int num_tokens;
} ParsedTokens;

// Function to tokenize a string
Token *tokenize(char *input, int *num_tokens) {
    // Initialize tokens array
    Token *tokens = malloc(10 * sizeof(Token));
    *num_tokens = 0;

    // Iterate over input string
    char *token_start = input;
    char *token_end = input;
    while (*token_end != '\0') {
        // If current character is a token delimiter, add current token to tokens array
        if (*token_end == ' ' || *token_end == '\t' || *token_end == '\n') {
            // Add current token to tokens array
            tokens[*num_tokens].token = token_start;
            tokens[*num_tokens].line = 1;
            tokens[*num_tokens].col = token_start - input;
            (*num_tokens)++;

            // If tokens array is full, reallocate it
            if (*num_tokens == 10) {
                tokens = realloc(tokens, (2 * *num_tokens) * sizeof(Token));
            }

            // Update token_start and token_end pointers
            token_start = token_end + 1;
        }

        // Update token_end pointer
        token_end++;
    }

    // Add last token to tokens array
    tokens[*num_tokens].token = token_start;
    tokens[*num_tokens].line = 1;
    tokens[*num_tokens].col = token_start - input;
    (*num_tokens)++;

    // Return tokens array
    return tokens;
}

// Function to parse tokens
ParsedTokens *parse(Token *tokens, int num_tokens) {
    // Initialize parsed tokens array
    ParsedTokens *parsed_tokens = malloc(sizeof(ParsedTokens));
    parsed_tokens->tokens = malloc(num_tokens * sizeof(Token));
    parsed_tokens->num_tokens = num_tokens;

    // Iterate over tokens array
    for (int i = 0; i < num_tokens; i++) {
        // If current token is a keyword, add it to parsed tokens array
        if (strcmp(tokens[i].token, "if") == 0 || strcmp(tokens[i].token, "else") == 0 || strcmp(tokens[i].token, "while") == 0) {
            parsed_tokens->tokens[i].token = tokens[i].token;
            parsed_tokens->tokens[i].line = tokens[i].line;
            parsed_tokens->tokens[i].col = tokens[i].col;
        }
    }

    // Return parsed tokens array
    return parsed_tokens;
}

int main() {
    // Get input from user
    char *input = malloc(1000 * sizeof(char));
    printf("Enter a C syntax program: ");
    scanf("%s", input);

    // Tokenize input string
    int num_tokens = 0;
    Token *tokens = tokenize(input, &num_tokens);

    // Parse tokens
    ParsedTokens *parsed_tokens = parse(tokens, num_tokens);

    // Print parsed tokens
    for (int i = 0; i < parsed_tokens->num_tokens; i++) {
        printf("Token %d: %s\n", i, parsed_tokens->tokens[i].token);
    }

    // Free memory
    free(tokens);
    free(parsed_tokens);
    free(input);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>

void print_board(char board[3][3]) {
    for(int i = 0; i < 3; i++) {
        for(int j = 0; j < 3; j++) {
            printf(" %c ", board[i][j]);
        }
        printf("\n");
    }
}

int check_winner(char board[3][3]) {
    for(int i = 0; i < 3; i++) {
        if(board[i][0] == board[i][1] && board[i][1] == board[i][2]) {
            return 1;
        }
        if(board[0][i] == board[1][i] && board[1][i] == board[2][i]) {
            return 1;
        }
    }
    if(board[0][0] == board[1][1] && board[1][1] == board[2][2]) {
        return 1;
    }
    if(board[0][2] == board[1][1] && board[1][1] == board[2][0]) {
        return 1;
    }
    return 0;
}

int main() {
    srand(time(NULL));
    char board[3][3] = {{'1', '2', '3'}, {'4', '5', '6'}, {'7', '8', '9'}};
    int player = 1;
    int choice;
    while(1) {
        system("clear");
        print_board(board);
        printf("\nPlayer %d's turn\n", player);
        printf("Enter your choice: ");
        scanf("%d", &choice);
        if(choice < 1 || choice > 9) {
            printf("Invalid choice. Skipping turn.\n");
            continue;
        }
        int row = (choice-1)/3;
        int col = (choice-1)%3;
        if(board[row][col]!= 'X' && board[row][col]!= 'O') {
            board[row][col] = (player == 1)? 'X' : 'O';
            player = (player == 1)? 2 : 1;
        } else {
            printf("Invalid choice. Skipping turn.\n");
        }
        if(check_winner(board)) {
            printf("\nPlayer %d wins!\n", player);
            break;
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define EMPTY ' '
#define SIZE 8

typedef struct {
    char board[SIZE][SIZE];
} ChessGame;

void init_game(ChessGame *game) {
    const char *start[] = {
        "rnbqkbnr",
        "pppppppp",
        "        ",
        "        ",
        "        ",
        "        ",
        "PPPPPPPP",
        "RNBQKBNR"
    };
    for (int i = 0; i < SIZE; i++) {
        strcpy(game->board[i], start[i]);
    }
}

void print_board(ChessGame *game) {
    printf("  a b c d e f g h\n");
    for (int i = 0; i < SIZE; i++) {
        printf("%d ", SIZE - i);
        for (int j = 0; j < SIZE; j++) {
            printf("%c ", game->board[i][j]);
        }
        printf("\n");
    }
}

int is_valid_move(char piece, int src_row, int src_col, int dest_row, int dest_col) {
    // Very basic move validation (only checks if the destination is empty)
    return (piece != EMPTY && (piece == EMPTY || piece == piece));
}

void make_move(ChessGame *game, int src_row, int src_col, int dest_row, int dest_col) {
    game->board[dest_row][dest_col] = game->board[src_row][src_col];
    game->board[src_row][src_col] = EMPTY;
}

void ai_move(ChessGame *game) {
    int src_row, src_col, dest_row, dest_col;
    while (1) {
        src_row = rand() % SIZE;
        src_col = rand() % SIZE;
        dest_row = rand() % SIZE;
        dest_col = rand() % SIZE;
        char piece = game->board[src_row][src_col];
        if (is_valid_move(piece, src_row, src_col, dest_row, dest_col)) {
            make_move(game, src_row, src_col, dest_row, dest_col);
            break;
        }
    }
}

int main() {
    ChessGame game;
    init_game(&game);
    char input[5];
    int src_row, src_col, dest_row, dest_col;

    printf("Welcome to minimalist Chess AI!\n");
    while (1) {
        print_board(&game);
        printf("Enter your move (e.g., e2 e4): ");
        fgets(input, sizeof(input), stdin);
        if (sscanf(input, "%c%d %c%d", &input[0], &src_row, &input[2], &dest_row) != 4) {
            printf("Invalid input. Please try again.\n");
            continue;
        }
        src_row = SIZE - src_row;
        dest_row = SIZE - dest_row;
        src_col = input[0] - 'a';
        dest_col = input[2] - 'a';

        if (is_valid_move(game.board[src_row][src_col], src_row, src_col, dest_row, dest_col)) {
            make_move(&game, src_row, src_col, dest_row, dest_col);
            printf("AI is moving...\n");
            ai_move(&game);
        } else {
            printf("Invalid move! Try again.\n");
        }
    }
    return 0;
}

