using namespace std;

class Matrix{	
	public:
    int r,c;
    vector < vector<int> > array2d;

//the constructor function that populates our main array named array2d
       Matrix(){

            cin >> r >> c; 
            int temp1;

           array2d.resize(r);
           for ( int i = 0 ; i < r ; i++ )
               array2d[i].resize(c);

            for(int i = 0; i < r; i++)
            {
                  for(int j = 0; j < c; j++)
                  {
                     cin >> temp1; 
                     array2d[i][j] = temp1;
                  }
            }		    
        }   
};

class SORTED_ARRAY : public Matrix {

    public :

    //the query search function that does it in O(m+n) time and O(1) auxiliary space
    pair<int,int> sorted_search(){

        long int element;
         cin >> element;

        int i ;
        i = 0;
        int j = c-1;
    //the algorithm runs a iteration starting from one of the diagonal elements and navigating upto the query element(if it exists)
         while(i != r && j != -1)
         {
             if(array2d[i][j] == element) {return make_pair(i, j);}  //if found return the coordinate pair

              if(array2d[i][j] > element) {j--;} //if the query element is smaller then traverse to left

              if(array2d[i][j] < element) {i++;} //if the query element is bigger then traverse down
          }
//note that the iteration traverses utmost from one corner to diagonally opposite corner thus taking a maximum of m+n steps thus yielding O(m+n)
        return make_pair(-1, -1); //the iterations will exit the above loop only if the query element is absent in the loop
    }


};


int main(){

    Matrix array2d(); //creates and populates the array array2d

    SORTED_ARRAY A1; //initialises a object in whose scope we perform the sorted search operation
    pair<int,int> p = A1.sorted_search();
    cout << p.first << " "<< p.second<< endl;

   return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_GUESSES 10
#define MAX_WORDS 20

// Structure to store the game state
struct game_state {
    int current_word[MAX_WORDS];
    int guesses_left[MAX_GUESSES];
    int correct_guesses[MAX_GUESSES];
};

// Function to generate a random word
void generate_word(struct game_state *state) {
    int i;
    for (i = 0; i < MAX_WORDS; i++) {
        state->current_word[i] = rand() % 9 + 1;
    }
}

// Function to check if a guess is correct
int check_guess(struct game_state *state, int guess) {
    int i;
    for (i = 0; i < MAX_WORDS; i++) {
        if (guess == state->current_word[i]) {
            return 1;
        }
    }
    return 0;
}

// Function to update the game state after a guess
void update_game_state(struct game_state *state, int guess) {
    int i;
    for (i = 0; i < MAX_WORDS; i++) {
        if (check_guess(state, guess)) {
            state->correct_guesses[i]++;
            state->guesses_left[i]--;
            if (state->guesses_left[i] == 0) {
                state->current_word[i] = 0; // Mark the word as guessed
            }
        }
    }
}

// Function to display the game state
void display_game_state(struct game_state *state) {
    int i;
    for (i = 0; i < MAX_WORDS; i++) {
        printf("%d ", state->current_word[i]);
    }
    printf("\n");
    for (i = 0; i < MAX_GUESSES; i++) {
        printf("%d guesses left for word %d\n", state->guesses_left[i], i + 1);
    }
}

int main() {
    struct game_state state;

    // Initialize the game state
    generate_word(&state);
    update_game_state(&state, 0);

    // Display the game state
    display_game_state(&state);

    // Game loop
    while (1) {
        int guess;
        printf("Guess a word: ");
        scanf("%d", &guess);
        update_game_state(&state, guess);
        display_game_state(&state);
    }

    return 0;
}

