    perror("socket failed");
    exit(EXIT_FAILURE);
  }

  struct sockaddr_in server_addr;
  server_addr.sin_family = AF_INET;
  server_addr.sin_port = htons(8080);
  inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

  if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
    perror("bind failed");
    exit(EXIT_FAILURE);
  }

  if (listen(sock, 3) < 0) {
    perror("listen failed");
    exit(EXIT_FAILURE);
  }

  while (1) {
    int client_sock = accept(sock, NULL, NULL);
    if (client_sock < 0) {
      perror("accept failed");
      continue;
    }

    char client_address[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &server_addr.sin_addr, client_address, sizeof(client_address));
    printf("Accepted connection from %s\n", client_address);

    char packet[MAX_PACKET_LENGTH];
    int packet_len = recv(client_sock, packet, MAX_PACKET_LENGTH, 0);
    if (packet_len < 0) {
      perror("recv failed");
      close(client_sock);
      continue;
    }

    // Drop any packets that are not from a trusted source
    if (strcmp(packet, "Hello from an untrusted source") != 0) {
      close(client_sock);
      continue;
    }

    // Allow packets from trusted sources
    char *ptr = packet;
    while (*ptr != '\0') {
      printf("%c", *ptr);
      ptr++;
    }

    close(client_sock);
  }

  close(sock);
  return 0;
}

