#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_DEPTH 5
#define MIN_TEMP 0
#define MAX_TEMP 50

struct weather {
    int temp;
    int humidity;
    int pressure;
    struct weather *next;
};

void weather_simulate(struct weather *root) {
    // Simulate one day
    for (int i = 0; i < 24; i++) {
        // Update temperature
        root->temp += (rand() % 5) - 2;
        if (root->temp < MIN_TEMP) {
            root->temp = MIN_TEMP;
        } else if (root->temp > MAX_TEMP) {
            root->temp = MAX_TEMP;
        }

        // Update humidity
        root->humidity += (rand() % 5) - 2;
        if (root->humidity < 0) {
            root->humidity = 0;
        } else if (root->humidity > 100) {
            root->humidity = 100;
        }

        // Update pressure
        root->pressure += (rand() % 5) - 2;
        if (root->pressure < 0) {
            root->pressure = 0;
        } else if (root->pressure > 1000) {
            root->pressure = 1000;
        }

        // Recursively simulate child nodes
        if (root->next != NULL) {
            weather_simulate(root->next);
        }
    }
}

int main() {
    struct weather *root = NULL;

    // Create the root node
    root = malloc(sizeof(struct weather));
    root->temp = 20;
    root->humidity = 50;
    root->pressure = 500;
    root->next = NULL;

    // Create child nodes
    struct weather *child1 = malloc(sizeof(struct weather));
    child1->temp = 15;
    child1->humidity = 70;
    child1->pressure = 400;
    child1->next = NULL;

    struct weather *child2 = malloc(sizeof(struct weather));
    child2->temp = 25;
    child2->humidity = 30;
    child2->pressure = 600;
    child2->next = NULL;

    // Simulate the weather
    weather_simulate(root);

    // Print the final weather conditions
    printf("Final weather conditions:\n");
    printf("Temperature: %d\n", root->temp);
    printf("Humidity: %d\n", root->humidity);
    printf("Pressure: %d\n", root->pressure);

    return 0;
}

