#ifndef __TITANIA_INPUT_OUTPUT_NUMBER_H__
#define __TITANIA_INPUT_OUTPUT_NUMBER_H__

#include <istream>
#include <string>

#include "../LOG.h"

namespace titania {
namespace io {

/**
 *  Template to represent a number match agains a std::basic_istream.
 *
 *  Extern instantiations for char and wchar are part of the
 *  library.  Results with any other type are not guaranteed.
 *
 *  @param  CharT   Type of characters.
 *  @param  Traits  Character traits
 */
template <class Type, class CharT, class Traits = std::char_traits <CharT>> 
class basic_number
{
public:

	///  @name Construction

	///  Constructs the io::basic_number.  A std::basic_istream can then be tested against the number type.
	constexpr
	basic_number ();

	///  @name Operations

	///  Test whether the next characters in @a istream are a number. Returns true on success and changes
	///  @a istreams position to the next character after the matched characters otherwise it returns false and doesn't
	///  changes the streams current position.
	bool
	operator () (std::basic_istream <CharT, Traits> & istream, Type & value) const;

};

template <class Type, class CharT, class Traits>
inline
constexpr
basic_number <Type, CharT, Traits>::basic_number ()
{ }

template <class Type, class CharT, class Traits>
bool
basic_number <Type, CharT, Traits>::operator () (std::basic_istream <CharT, Traits> & istream, Type & value) const
{
	const auto state = istream .rdstate ();
	const auto pos   = istream .tellg ();

	Type v;

	if (istream >> std::dec >> v)
	{
		value = v;
		return true;
	}

	istream .clear (state);

	for (size_t i = 0, size = istream .tellg () - pos; i < size; ++ i)
		istream .unget ();

	return false;
}

template <class Type>
using number = basic_number <Type, char>;

template <class Type>
using wnumber = basic_number <Type, wchar_t>;

} // io
} // titania

#endif

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define PHONE_BOOK_SIZE 100
#define PHONE_NUMBER_LENGTH 10

struct phone_book {
    char name[50];
    char phone_number[PHONE_NUMBER_LENGTH];
};

struct phone_book g_phone_book[PHONE_BOOK_SIZE];
int g_num_entries = 0;

void add_entry(char *name, char *phone_number) {
    if (g_num_entries >= PHONE_BOOK_SIZE) {
        printf("Surprise! The phone book is full! :O\n");
        return;
    }

    strcpy(g_phone_book[g_num_entries].name, name);
    strcpy(g_phone_book[g_num_entries].phone_number, phone_number);
    g_num_entries++;

    printf("Entry added successfully! :D\n");
}

void search_entry(char *name) {
    int i;
    for (i = 0; i < g_num_entries; i++) {
        if (strcmp(g_phone_book[i].name, name) == 0) {
            printf("Found! %s's phone number is %s\n", name, g_phone_book[i].phone_number);
            return;
        }
    }

    printf("Oops! %s not found in the phone book :(\n", name);
}

int main() {
    char name[50];
    char phone_number[PHONE_NUMBER_LENGTH];

    srand(time(NULL));

    for (int i = 0; i < 10; i++) {
        printf("Add a new entry: ");
        fgets(name, 50, stdin);
        printf("Add a new phone number: ");
        fgets(phone_number, PHONE_NUMBER_LENGTH, stdin);
        add_entry(name, phone_number);
    }

    for (int i = 0; i < 10; i++) {
        printf("Search for %s: ", name[i]);
        search_entry(name[i]);
    }

    return 0;
}
